362:     @Test
363:     void testMinCheckpointPause() throws Exception {
364:         // will use a different thread to allow checkpoint triggering before exiting from
365:         // receiveAcknowledgeMessage
366:         ScheduledExecutorService executorService = Executors.newSingleThreadScheduledExecutor();
367:         CheckpointCoordinator coordinator = null;
368:         try {
369:             int pause = 1000;
370:             JobVertexID jobVertexId = new JobVertexID();
371:             ExecutionGraph graph =
372:                     new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder()
373:                             .addJobVertex(jobVertexId)
374:                             .setMainThreadExecutor(
375:                                     ComponentMainThreadExecutorServiceAdapter
376:                                             .forSingleThreadExecutor(
377:                                                     new DirectScheduledExecutorService()))
378:                             .build(EXECUTOR_RESOURCE.getExecutor());
379: 
380:             ExecutionVertex vertex = graph.getJobVertex(jobVertexId).getTaskVertices()[0];
381:             ExecutionAttemptID attemptId = vertex.getCurrentExecutionAttempt().getAttemptId();
382: 
383:             coordinator =
384:                     new CheckpointCoordinatorBuilder()
385:                             .setTimer(new ScheduledExecutorServiceAdapter(executorService))
386:                             .setCheckpointCoordinatorConfiguration(
387:                                     CheckpointCoordinatorConfiguration.builder()
388:                                             .setCheckpointInterval(pause)
389:                                             .setCheckpointTimeout(Long.MAX_VALUE)
390:                                             .setMaxConcurrentCheckpoints(1)
391:                                             .setMinPauseBetweenCheckpoints(pause)
392:                                             .build())
393:                             .build(graph);
394:             coordinator.startCheckpointScheduler();
395: 
396:             coordinator.triggerCheckpoint(
397:                     true); // trigger, execute, and later complete by receiveAcknowledgeMessage
398:             coordinator.triggerCheckpoint(
399:                     true); // enqueue and later see if it gets executed in the middle of
400:             // receiveAcknowledgeMessage
401:             while (coordinator.getPendingCheckpoints().values().stream()
402:                     .noneMatch(pc -> pc.getCheckpointStorageLocation() != null)) {
403:                 // wait for at least 1 request to be fully processed
404:                 // explicitly check for the checkpoint storage location to make sure
405:                 // that the checkpoint was actually triggered
406:                 // if the checkpoint wasn't triggered yet the acknowledge below
407:                 // will fail with an error
408:                 Thread.sleep(10);
409:             }
410:             coordinator.receiveAcknowledgeMessage(
411:                     new AcknowledgeCheckpoint(graph.getJobID(), attemptId, 1L),
412:                     TASK_MANAGER_LOCATION_INFO);
413:             Thread.sleep(pause / 2);
414:             assertThat(coordinator.getNumberOfPendingCheckpoints()).isZero();
415:             // make sure that the 2nd request is eventually processed
416:             while (coordinator.getNumberOfPendingCheckpoints() == 0) {
417:                 Thread.sleep(1);
418:             }
419:         } finally {
420:             if (coordinator != null) {
421:                 coordinator.shutdown();
422:             }
423:             executorService.shutdownNow();
424:         }
425:     }
