2667:     @Test
2668:     void testPartitionableStateRepartitioning() {
2669:         Random r = new Random(42);
2670: 
2671:         for (int run = 0; run < 10000; ++run) {
2672:             int oldParallelism = 1 + r.nextInt(9);
2673:             int newParallelism = 1 + r.nextInt(9);
2674: 
2675:             int numNamedStates = 1 + r.nextInt(9);
2676:             int maxPartitionsPerState = 1 + r.nextInt(9);
2677: 
2678:             doTestPartitionableStateRepartitioning(
2679:                     r, oldParallelism, newParallelism, numNamedStates, maxPartitionsPerState);
2680:         }
2681:     }
2682: 
2683:     private void doTestPartitionableStateRepartitioning(
2684:             Random r,
2685:             int oldParallelism,
2686:             int newParallelism,
2687:             int numNamedStates,
2688:             int maxPartitionsPerState) {
2689: 
2690:         List<List<OperatorStateHandle>> previousParallelOpInstanceStates =
2691:                 new ArrayList<>(oldParallelism);
2692: 
2693:         for (int i = 0; i < oldParallelism; ++i) {
2694:             Path fakePath = new Path("/fake-" + i);
2695:             Map<String, OperatorStateHandle.StateMetaInfo> namedStatesToOffsets = new HashMap<>();
2696:             int off = 0;
2697:             for (int s = 0; s < numNamedStates - 1; ++s) {
2698:                 long[] offs = new long[1 + r.nextInt(maxPartitionsPerState)];
2699: 
2700:                 for (int o = 0; o < offs.length; ++o) {
2701:                     offs[o] = off;
2702:                     ++off;
2703:                 }
2704: 
2705:                 OperatorStateHandle.Mode mode =
2706:                         r.nextInt(10) == 0
2707:                                 ? OperatorStateHandle.Mode.UNION
2708:                                 : OperatorStateHandle.Mode.SPLIT_DISTRIBUTE;
2709:                 namedStatesToOffsets.put(
2710:                         "State-" + s, new OperatorStateHandle.StateMetaInfo(offs, mode));
2711:             }
2712: 
2713:             if (numNamedStates % 2 == 0) {
2714:                 // finally add a broadcast state
2715:                 long[] offs = {off + 1, off + 2, off + 3, off + 4};
2716: 
2717:                 namedStatesToOffsets.put(
2718:                         "State-" + (numNamedStates - 1),
2719:                         new OperatorStateHandle.StateMetaInfo(
2720:                                 offs, OperatorStateHandle.Mode.BROADCAST));
2721:             }
2722: 
2723:             previousParallelOpInstanceStates.add(
2724:                     Collections.singletonList(
2725:                             new OperatorStreamStateHandle(
2726:                                     namedStatesToOffsets, new FileStateHandle(fakePath, -1))));
2727:         }
2728: 
2729:         Map<StreamStateHandle, Map<String, List<Long>>> expected = new HashMap<>();
2730: 
2731:         int taskIndex = 0;
2732:         int expectedTotalPartitions = 0;
2733:         for (List<OperatorStateHandle> previousParallelOpInstanceState :
2734:                 previousParallelOpInstanceStates) {
2735:             assertThat(previousParallelOpInstanceState.size()).isOne();
2736: 
2737:             for (OperatorStateHandle psh : previousParallelOpInstanceState) {
2738:                 Map<String, OperatorStateHandle.StateMetaInfo> offsMap =
2739:                         psh.getStateNameToPartitionOffsets();
2740:                 Map<String, List<Long>> offsMapWithList = new HashMap<>(offsMap.size());
2741:                 for (Map.Entry<String, OperatorStateHandle.StateMetaInfo> e : offsMap.entrySet()) {
2742: 
2743:                     long[] offs = e.getValue().getOffsets();
2744:                     int replication;
2745:                     switch (e.getValue().getDistributionMode()) {
2746:                         case UNION:
2747:                             replication = newParallelism;
2748:                             break;
2749:                         case BROADCAST:
2750:                             int extra = taskIndex < (newParallelism % oldParallelism) ? 1 : 0;
2751:                             replication = newParallelism / oldParallelism + extra;
2752:                             break;
2753:                         case SPLIT_DISTRIBUTE:
2754:                             replication = 1;
2755:                             break;
2756:                         default:
2757:                             throw new RuntimeException(
2758:                                     "Unknown distribution mode "
2759:                                             + e.getValue().getDistributionMode());
2760:                     }
2761: 
2762:                     if (replication > 0) {
2763:                         expectedTotalPartitions += replication * offs.length;
2764:                         List<Long> offsList = new ArrayList<>(offs.length);
2765: 
2766:                         for (long off : offs) {
2767:                             for (int p = 0; p < replication; ++p) {
2768:                                 offsList.add(off);
2769:                             }
2770:                         }
2771:                         offsMapWithList.put(e.getKey(), offsList);
2772:                     }
2773:                 }
2774: 
2775:                 if (!offsMapWithList.isEmpty()) {
2776:                     expected.put(psh.getDelegateStateHandle(), offsMapWithList);
2777:                 }
2778:                 taskIndex++;
2779:             }
2780:         }
2781: 
2782:         OperatorStateRepartitioner<OperatorStateHandle> repartitioner =
2783:                 RoundRobinOperatorStateRepartitioner.INSTANCE;
2784: 
2785:         List<List<OperatorStateHandle>> pshs =
2786:                 repartitioner.repartitionState(
2787:                         previousParallelOpInstanceStates, oldParallelism, newParallelism);
2788: 
2789:         Map<StreamStateHandle, Map<String, List<Long>>> actual = new HashMap<>();
2790: 
2791:         int minCount = Integer.MAX_VALUE;
2792:         int maxCount = 0;
2793:         int actualTotalPartitions = 0;
2794:         for (int p = 0; p < newParallelism; ++p) {
2795:             int partitionCount = 0;
2796: 
2797:             Collection<OperatorStateHandle> pshc = pshs.get(p);
2798:             for (OperatorStateHandle sh : pshc) {
2799:                 for (Map.Entry<String, OperatorStateHandle.StateMetaInfo> namedState :
2800:                         sh.getStateNameToPartitionOffsets().entrySet()) {
2801: 
2802:                     Map<String, List<Long>> stateToOffsets =
2803:                             actual.computeIfAbsent(
2804:                                     sh.getDelegateStateHandle(), k -> new HashMap<>());
2805: 
2806:                     List<Long> actualOffs =
2807:                             stateToOffsets.computeIfAbsent(
2808:                                     namedState.getKey(), k -> new ArrayList<>());
2809:                     long[] add = namedState.getValue().getOffsets();
2810:                     for (long l : add) {
2811:                         actualOffs.add(l);
2812:                     }
2813: 
2814:                     partitionCount += namedState.getValue().getOffsets().length;
2815:                 }
2816:             }
2817: 
2818:             minCount = Math.min(minCount, partitionCount);
2819:             maxCount = Math.max(maxCount, partitionCount);
2820:             actualTotalPartitions += partitionCount;
2821:         }
2822: 
2823:         for (Map<String, List<Long>> v : actual.values()) {
2824:             for (List<Long> l : v.values()) {
2825:                 Collections.sort(l);
2826:             }
2827:         }
2828: 
2829:         // if newParallelism equals to oldParallelism, we would only redistribute UNION state if
2830:         // possible.
2831:         if (oldParallelism != newParallelism) {
2832:             int maxLoadDiff = maxCount - minCount;
2833:             assertThat(maxLoadDiff <= 1)
2834:                     .as("Difference in partition load is > 1 : " + maxLoadDiff)
2835:                     .isTrue();
2836:         }
2837:         assertThat(actualTotalPartitions).isEqualTo(expectedTotalPartitions);
2838:         assertThat(actual).isEqualTo(expected);
2839:     }
