3851:     @Test
3852:     void testAbortingBeforeTriggeringCheckpointOperatorCoordinator() throws Exception {
3853:         // Warn: The case is fragile since a specific order of executing the tasks is required to
3854:         // reproduce the issue.
3855:         JobVertexID jobVertexID = new JobVertexID();
3856:         ExecutionGraph graph =
3857:                 new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder()
3858:                         .addJobVertex(jobVertexID)
3859:                         .build(EXECUTOR_RESOURCE.getExecutor());
3860: 
3861:         String trigger = "Trigger";
3862:         String abort = "Abort";
3863:         final List<String> notificationSequence = new ArrayList<>();
3864:         CheckpointCoordinatorTestingUtils.MockOperatorCoordinatorCheckpointContext context =
3865:                 new CheckpointCoordinatorTestingUtils
3866:                                 .MockOperatorCheckpointCoordinatorContextBuilder()
3867:                         .setOperatorID(new OperatorID())
3868:                         .setOnCallingCheckpointCoordinator(
3869:                                 (id, future) -> {
3870:                                     notificationSequence.add(trigger + id);
3871:                                     future.complete(new byte[0]);
3872:                                 })
3873:                         .setOnCallingAbortCurrentTriggering(() -> notificationSequence.add(abort))
3874:                         .build();
3875: 
3876:         CheckpointCoordinator checkpointCoordinator =
3877:                 new CheckpointCoordinatorBuilder()
3878:                         .setCheckpointCoordinatorConfiguration(
3879:                                 CheckpointCoordinatorConfiguration.builder()
3880:                                         .setCheckpointTimeout(10)
3881:                                         .build())
3882:                         .setIoExecutor(manuallyTriggeredScheduledExecutor)
3883:                         .setTimer(manuallyTriggeredScheduledExecutor)
3884:                         .setCoordinatorsToCheckpoint(Collections.singleton(context))
3885:                         .build(graph);
3886:         try {
3887:             checkpointCoordinator.triggerCheckpoint(false);
3888:             // trigger three times to trigger checkpoint, to get checkpoint id and create pending
3889:             // checkpoint
3890:             manuallyTriggeredScheduledExecutor.trigger();
3891:             manuallyTriggeredScheduledExecutor.trigger();
3892:             manuallyTriggeredScheduledExecutor.trigger();
3893: 
3894:             // declineCheckpoint should be called after pending checkpoint is created but before the
3895:             // following steps
3896:             declineCheckpoint(1L, checkpointCoordinator, jobVertexID, graph);
3897:             // then trigger all tasks. the order is 1.initialize checkpoint location, 2.handle
3898:             // checkpoint abortion, 3.trigger coordinator checkpointing for the aborted checkpoint.
3899:             // The disordering of abortion and triggering was causing an error
3900:             manuallyTriggeredScheduledExecutor.triggerAll();
3901: 
3902:             // trigger the next checkpoint
3903:             checkState(!checkpointCoordinator.isTriggering());
3904:             checkpointCoordinator.triggerCheckpoint(false);
3905:             manuallyTriggeredScheduledExecutor.triggerAll();
3906: 
3907:             assertThat(
3908:                             !notificationSequence.contains(trigger + "1")
3909:                                     || notificationSequence.indexOf(trigger + "1")
3910:                                             < notificationSequence.indexOf(abort))
3911:                     .isTrue();
3912:         } finally {
3913:             checkpointCoordinator.shutdown();
3914:         }
3915:     }
