144:     /**
145:      * Verify operators would be notified as checkpoint aborted.
146:      *
147:      * <p>The job would run with at least two checkpoints. The 1st checkpoint would fail due to add
148:      * checkpoint to store, and the 2nd checkpoint would decline by async checkpoint phase of
149:      * 'DeclineSink'.
150:      *
151:      * <p>The job graph looks like: NormalSource --> keyBy --> NormalMap --> DeclineSink
152:      */
153:     @Test(timeout = TEST_TIMEOUT)
154:     public void testNotifyCheckpointAborted() throws Exception {
155:         final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
156:         env.enableCheckpointing(200, CheckpointingMode.EXACTLY_ONCE);
157:         env.getCheckpointConfig().enableUnalignedCheckpoints(unalignedCheckpointEnabled);
158:         env.getCheckpointConfig().setTolerableCheckpointFailureNumber(2);
159:         env.disableOperatorChaining();
160:         env.setParallelism(1);
