162:         final StateBackend failingStateBackend = new DeclineSinkFailingStateBackend(checkpointPath);
163:         env.setStateBackend(failingStateBackend);
164: 
165:         env.addSource(new NormalSource())
166:                 .name("NormalSource")
167:                 .keyBy((KeySelector<Tuple2<Integer, Integer>, Integer>) value -> value.f0)
168:                 .transform("NormalMap", TypeInformation.of(Integer.class), new NormalMap())
169:                 .transform(DECLINE_SINK_NAME, TypeInformation.of(Object.class), new DeclineSink());
170: 
171:         final ClusterClient<?> clusterClient = cluster.getClusterClient();
172:         JobGraph jobGraph = env.getStreamGraph().getJobGraph();
173:         JobID jobID = jobGraph.getJobID();
174: 
175:         clusterClient.submitJob(jobGraph).get();
176: 
177:         TestingCompletedCheckpointStore.addCheckpointLatch.await();
178:         log.info("The checkpoint to abort is ready to add to checkpoint store.");
179:         TestingCompletedCheckpointStore.abortCheckpointLatch.trigger();
