181:         log.info("Verifying whether all operators have been notified of checkpoint-1 aborted.");
182:         verifyAllOperatorsNotifyAborted();
183:         log.info("Verified that all operators have been notified of checkpoint-1 aborted.");
184:         resetAllOperatorsNotifyAbortedLatches();
185:         verifyAllOperatorsNotifyAbortedTimes(1);
186: 
187:         DECLINE_CHECKPOINT_WAIT_LATCH.trigger();
188:         log.info("Verifying whether all operators have been notified of checkpoint-2 aborted.");
189:         verifyAllOperatorsNotifyAborted();
190:         log.info("Verified that all operators have been notified of checkpoint-2 aborted.");
191:         verifyAllOperatorsNotifyAbortedTimes(2);
