432:         @Override
433:         public CompletedCheckpoint addCheckpointAndSubsumeOldestOne(
434:                 CompletedCheckpoint checkpoint,
435:                 CheckpointsCleaner checkpointsCleaner,
436:                 Runnable postCleanup)
437:                 throws Exception {
438:             if (abortCheckpointLatch.isTriggered()) {
439:                 return super.addCheckpointAndSubsumeOldestOne(
440:                         checkpoint, checkpointsCleaner, postCleanup);
441:             } else {
442:                 // tell main thread that all checkpoints on task side have been finished.
443:                 addCheckpointLatch.trigger();
444:                 // wait for the main thread to throw exception so that the checkpoint would be
445:                 // notified as aborted.
446:                 abortCheckpointLatch.await();
447:                 throw new ExpectedTestException();
448:             }
449:         }
450: 
451:         static void reset() {
452:             addCheckpointLatch.reset();
453:             abortCheckpointLatch.reset();
454:         }
