595:     private void injectChannelStateWriterIntoChannels() {
596:         final Environment env = getEnvironment();
597:         final ChannelStateWriter channelStateWriter =
598:                 subtaskCheckpointCoordinator.getChannelStateWriter();
599:         for (final InputGate gate : env.getAllInputGates()) {
600:             gate.setChannelStateWriter(channelStateWriter);
601:         }
602:         for (ResultPartitionWriter writer : env.getAllWriters()) {
603:             if (writer instanceof ChannelStateHolder) {
604:                 ((ChannelStateHolder) writer).setChannelStateWriter(channelStateWriter);
605:             }
606:         }
607:     }
