689:     protected void endData(StopMode mode) throws Exception {
690: 
691:         if (mode == StopMode.DRAIN) {
692:             advanceToEndOfEventTime();
693:         }
694:         // finish all operators in a chain effect way
695:         operatorChain.finishOperators(actionExecutor, mode);
696:         this.finishedOperators = true;
697: 
698:         for (ResultPartitionWriter partitionWriter : getEnvironment().getAllWriters()) {
699:             partitionWriter.notifyEndOfData(mode);
700:         }
701: 
702:         this.endOfDataReceived = true;
703:     }
