769:     @Override
770:     public final void restore() throws Exception {
771:         restoreInternal();
772:     }
773: 
774:     void restoreInternal() throws Exception {
775:         if (isRunning) {
776:             LOG.debug("Re-restore attempt rejected.");
777:             return;
778:         }
779:         isRestoring = true;
780:         closedOperators = false;
781:         getEnvironment().getMetricGroup().getIOMetricGroup().markTaskInitializationStarted();
782:         LOG.debug("Initializing {}.", getName());
783: 
784:         SubTaskInitializationMetricsBuilder initializationMetrics =
785:                 new SubTaskInitializationMetricsBuilder(
786:                         SystemClock.getInstance().absoluteTimeMillis());
787:         try {
788:             operatorChain =
789:                     getEnvironment().getTaskStateManager().isTaskDeployedAsFinished()
790:                             ? new FinishedOperatorChain<>(this, recordWriter)
791:                             : new RegularOperatorChain<>(this, recordWriter);
792:             mainOperator = operatorChain.getMainOperator();
793: 
794:             getEnvironment()
795:                     .getTaskStateManager()
796:                     .getRestoreCheckpointId()
797:                     .ifPresent(restoreId -> latestReportCheckpointId = restoreId);
798: 
799:             // task specific initialization
800:             init();
801:             configuration.clearInitialConfigs();
802: 
803:             // save the work of reloading state, etc, if the task is already canceled
804:             ensureNotCanceled();
805: 
806:             // -------- Invoke --------
807:             LOG.debug("Invoking {}", getName());
808: 
809:             // we need to make sure that any triggers scheduled in open() cannot be
810:             // executed before all operators are opened
811:             CompletableFuture<Void> allGatesRecoveredFuture =
812:                     actionExecutor.call(() -> restoreStateAndGates(initializationMetrics));
813: 
814:             // Run mailbox until all gates will be recovered.
815:             mailboxProcessor.runMailboxLoop();
816: 
817:             initializationMetrics.addDurationMetric(
818:                     GATE_RESTORE_DURATION,
819:                     SystemClock.getInstance().absoluteTimeMillis() - initializeStateEndTs);
820: 
821:             ensureNotCanceled();
822: 
823:             checkState(
824:                     allGatesRecoveredFuture.isDone(),
825:                     "Mailbox loop interrupted before recovery was finished.");
826: 
827:             // we recovered all the gates, we can close the channel IO executor as it is no longer
828:             // needed
829:             channelIOExecutor.shutdown();
830: 
831:             isRunning = true;
832:             isRestoring = false;
833:             initializationMetrics.setStatus(InitializationStatus.COMPLETED);
834:         } finally {
835:             environment
836:                     .getTaskStateManager()
837:                     .reportInitializationMetrics(initializationMetrics.build());
838:         }
839:     }
840: 
841:     private CompletableFuture<Void> restoreStateAndGates(
842:             SubTaskInitializationMetricsBuilder initializationMetrics) throws Exception {
843: 
844:         long mailboxStartTs = SystemClock.getInstance().absoluteTimeMillis();
845:         initializationMetrics.addDurationMetric(
846:                 MAILBOX_START_DURATION,
847:                 mailboxStartTs - initializationMetrics.getInitializationStartTs());
848: 
849:         SequentialChannelStateReader reader =
850:                 getEnvironment().getTaskStateManager().getSequentialChannelStateReader();
851:         reader.readOutputData(
852:                 getEnvironment().getAllWriters(), !configuration.isGraphContainingLoops());
853: 
854:         long readOutputDataTs = SystemClock.getInstance().absoluteTimeMillis();
855:         initializationMetrics.addDurationMetric(
856:                 READ_OUTPUT_DATA_DURATION, readOutputDataTs - mailboxStartTs);
857: 
858:         operatorChain.initializeStateAndOpenOperators(
859:                 createStreamTaskStateInitializer(initializationMetrics));
860: 
861:         initializeStateEndTs = SystemClock.getInstance().absoluteTimeMillis();
862:         initializationMetrics.addDurationMetric(
863:                 INITIALIZE_STATE_DURATION, initializeStateEndTs - readOutputDataTs);
864:         IndexedInputGate[] inputGates = getEnvironment().getAllInputGates();
865: 
866:         channelIOExecutor.execute(
867:                 () -> {
868:                     try {
869:                         reader.readInputData(inputGates);
870:                     } catch (Exception e) {
871:                         asyncExceptionHandler.handleAsyncException(
872:                                 "Unable to read channel state", e);
873:                     }
874:                 });
875: 
876:         // We wait for all input channel state to recover before we go into RUNNING state, and thus
877:         // start checkpointing. If we implement incremental checkpointing of input channel state
878:         // we must make sure it supports CheckpointType#FULL_CHECKPOINT
879:         List<CompletableFuture<?>> recoveredFutures = new ArrayList<>(inputGates.length);
880:         for (InputGate inputGate : inputGates) {
881:             recoveredFutures.add(inputGate.getStateConsumedFuture());
882: 
883:             inputGate
884:                     .getStateConsumedFuture()
885:                     .thenRun(
886:                             () ->
887:                                     mainMailboxExecutor.execute(
888:                                             inputGate::requestPartitions,
889:                                             "Input gate request partitions"));
890:         }
891: 
892:         return CompletableFuture.allOf(recoveredFutures.toArray(new CompletableFuture[0]))
893:                 .thenRun(mailboxProcessor::suspend);
894:     }
895: 
896:     private void ensureNotCanceled() {
897:         if (canceled) {
898:             throw new CancelTaskException();
899:         }
900:     }
