1048:     private boolean areCheckpointsWithFinishedTasksEnabled() {
1049:         return configuration
1050:                         .getConfiguration()
1051:                         .get(CheckpointingOptions.ENABLE_CHECKPOINTS_AFTER_TASKS_FINISH)
1052:                 && configuration.isCheckpointingEnabled();
1053:     }
