1254:     @Override
1255:     public CompletableFuture<Boolean> triggerCheckpointAsync(
1256:             CheckpointMetaData checkpointMetaData, CheckpointOptions checkpointOptions) {
1257:         checkForcedFullSnapshotSupport(checkpointOptions);
1258: 
1259:         CompletableFuture<Boolean> result = new CompletableFuture<>();
1260:         mainMailboxExecutor.execute(
1261:                 () -> {
1262:                     try {
1263:                         boolean noUnfinishedInputGates =
1264:                                 Arrays.stream(getEnvironment().getAllInputGates())
1265:                                         .allMatch(InputGate::isFinished);
1266: 
1267:                         if (noUnfinishedInputGates) {
1268:                             result.complete(
1269:                                     triggerCheckpointAsyncInMailbox(
1270:                                             checkpointMetaData, checkpointOptions));
1271:                         } else {
1272:                             result.complete(
1273:                                     triggerUnfinishedChannelsCheckpoint(
1274:                                             checkpointMetaData, checkpointOptions));
1275:                         }
1276:                     } catch (Exception ex) {
1277:                         // Report the failure both via the Future result but also to the mailbox
1278:                         result.completeExceptionally(ex);
1279:                         throw ex;
1280:                     }
1281:                 },
1282:                 "checkpoint %s with %s",
1283:                 checkpointMetaData,
1284:                 checkpointOptions);
1285:         return result;
1286:     }
