1470:     private void checkForcedFullSnapshotSupport(CheckpointOptions checkpointOptions) {
1471:         if (checkpointOptions.getCheckpointType().equals(CheckpointType.FULL_CHECKPOINT)
1472:                 && !stateBackend.supportsNoClaimRecoveryClaimMode()) {
1473:             throw new IllegalStateException(
1474:                     String.format(
1475:                             "Configured state backend (%s) does not support enforcing a full"
1476:                                     + " snapshot. If you are restoring in %s mode, please"
1477:                                     + " consider choosing %s mode.",
1478:                             stateBackend, RecoveryClaimMode.NO_CLAIM, RecoveryClaimMode.CLAIM));
1479:         } else if (checkpointOptions.getCheckpointType().isSavepoint()) {
1480:             SavepointType savepointType = (SavepointType) checkpointOptions.getCheckpointType();
1481:             if (!stateBackend.supportsSavepointFormat(savepointType.getFormatType())) {
1482:                 throw new IllegalStateException(
1483:                         String.format(
1484:                                 "Configured state backend (%s) does not support %s savepoints",
1485:                                 stateBackend, savepointType.getFormatType()));
1486:             }
1487:         }
1488:     }
