1556:     private void notifyCheckpointComplete(long checkpointId) throws Exception {
1557:         LOG.debug("Notify checkpoint {} complete on task {}", checkpointId, getName());
1558: 
1559:         if (checkpointId <= latestReportCheckpointId) {
1560:             return;
1561:         }
1562: 
1563:         latestReportCheckpointId = checkpointId;
1564: 
1565:         subtaskCheckpointCoordinator.notifyCheckpointComplete(
1566:                 checkpointId, operatorChain, this::isRunning);
1567:         if (isRunning) {
1568:             if (isCurrentSyncSavepoint(checkpointId)) {
1569:                 finalCheckpointCompleted.complete(null);
1570:             } else if (syncSavepoint == null
1571:                     && finalCheckpointMinId != null
1572:                     && checkpointId >= finalCheckpointMinId) {
1573:                 finalCheckpointCompleted.complete(null);
1574:             }
1575:         }
1576:     }
