1726:         List<RecordWriter<SerializationDelegate<StreamRecord<OUT>>>> recordWrites =
1727:                 createRecordWriters(configuration, environment);
1728:         if (recordWrites.size() == 1) {
1729:             return new SingleRecordWriter<>(recordWrites.get(0));
1730:         } else if (recordWrites.size() == 0) {
