1737:     private static <OUT>
1738:             List<RecordWriter<SerializationDelegate<StreamRecord<OUT>>>> createRecordWriters(
1739:                     StreamConfig configuration, Environment environment) {
1740:         List<RecordWriter<SerializationDelegate<StreamRecord<OUT>>>> recordWriters =
1741:                 new ArrayList<>();
1742:         List<NonChainedOutput> outputsInOrder =
1743:                 configuration.getVertexNonChainedOutputs(
1744:                         environment.getUserCodeClassLoader().asClassLoader());
1745: 
1746:         int index = 0;
1747:         for (NonChainedOutput streamOutput : outputsInOrder) {
1748:             replaceForwardPartitionerIfConsumerParallelismDoesNotMatch(
1749:                     environment, streamOutput, index);
1750:             recordWriters.add(
1751:                     createRecordWriter(
1752:                             streamOutput,
1753:                             index++,
1754:                             environment,
1755:                             environment.getTaskInfo().getTaskNameWithSubtasks(),
1756:                             streamOutput.getBufferTimeout()));
1757:         }
1758:         return recordWriters;
1759:     }
