618:     @VisibleForTesting
619:     CompletableFuture<CompletedCheckpoint> triggerCheckpoint(
620:             CheckpointProperties props,
621:             @Nullable String externalSavepointLocation,
622:             boolean isPeriodic) {
623: 
624:         CheckpointTriggerRequest request =
625:                 new CheckpointTriggerRequest(props, externalSavepointLocation, isPeriodic);
626:         chooseRequestToExecute(request).ifPresent(this::startTriggeringCheckpoint);
627:         return request.onCompletionPromise;
