901:     private PendingCheckpoint createPendingCheckpoint(
902:             long timestamp,
903:             CheckpointProperties props,
904:             CheckpointPlan checkpointPlan,
905:             boolean isPeriodic,
906:             long checkpointID,
907:             CompletableFuture<CompletedCheckpoint> onCompletionPromise,
908:             CompletableFuture<Void> masterTriggerCompletionPromise) {
909: 
910:         synchronized (lock) {
911:             try {
912:                 // since we haven't created the PendingCheckpoint yet, we need to check the
913:                 // global state here.
914:                 preCheckGlobalState(isPeriodic);
915:             } catch (Throwable t) {
916:                 throw new CompletionException(t);
917:             }
918:         }
919: 
920:         PendingCheckpointStats pendingCheckpointStats =
921:                 trackPendingCheckpointStats(checkpointID, checkpointPlan, props, timestamp);
922: 
923:         final PendingCheckpoint checkpoint =
924:                 new PendingCheckpoint(
925:                         job,
926:                         checkpointID,
927:                         timestamp,
928:                         checkpointPlan,
929:                         OperatorInfo.getIds(coordinatorsToCheckpoint),
930:                         masterHooks.keySet(),
931:                         props,
932:                         onCompletionPromise,
933:                         pendingCheckpointStats,
934:                         masterTriggerCompletionPromise);
935: 
936:         synchronized (lock) {
937:             pendingCheckpoints.put(checkpointID, checkpoint);
938: 
939:             ScheduledFuture<?> cancellerHandle =
940:                     timer.schedule(
941:                             new CheckpointCanceller(checkpoint),
942:                             checkpointTimeout,
943:                             TimeUnit.MILLISECONDS);
944: 
945:             if (!checkpoint.setCancellerHandle(cancellerHandle)) {
946:                 // checkpoint is already disposed!
947:                 cancellerHandle.cancel(false);
948:             }
949:         }
950: 
951:         LOG.info(
952:                 "Triggering checkpoint {} (type={}) @ {} for job {}.",
953:                 checkpointID,
954:                 checkpoint.getProps().getCheckpointType(),
955:                 timestamp,
956:                 job);
957:         return checkpoint;
958:     }
959: 
960:     /**
961:      * Snapshot master hook states asynchronously.
962:      *
963:      * @param checkpoint the pending checkpoint
964:      * @return the future represents master hook states are finished or not
965:      */
966:     private CompletableFuture<Void> snapshotMasterState(PendingCheckpoint checkpoint) {
967:         if (masterHooks.isEmpty()) {
968:             return CompletableFuture.completedFuture(null);
969:         }
970: 
971:         final long checkpointID = checkpoint.getCheckpointID();
972:         final long timestamp = checkpoint.getCheckpointTimestamp();
973: 
974:         final CompletableFuture<Void> masterStateCompletableFuture = new CompletableFuture<>();
975:         for (MasterTriggerRestoreHook<?> masterHook : masterHooks.values()) {
976:             MasterHooks.triggerHook(masterHook, checkpointID, timestamp, executor)
977:                     .whenCompleteAsync(
978:                             (masterState, throwable) -> {
979:                                 try {
980:                                     synchronized (lock) {
981:                                         if (masterStateCompletableFuture.isDone()) {
982:                                             return;
983:                                         }
984:                                         if (checkpoint.isDisposed()) {
985:                                             throw new IllegalStateException(
986:                                                     "Checkpoint "
987:                                                             + checkpointID
988:                                                             + " has been discarded");
989:                                         }
990:                                         if (throwable == null) {
991:                                             checkpoint.acknowledgeMasterState(
992:                                                     masterHook.getIdentifier(), masterState);
993:                                             if (checkpoint.areMasterStatesFullyAcknowledged()) {
994:                                                 masterStateCompletableFuture.complete(null);
995:                                             }
996:                                         } else {
997:                                             masterStateCompletableFuture.completeExceptionally(
998:                                                     throwable);
999:                                         }
1000:                                     }
1001:                                 } catch (Throwable t) {
1002:                                     masterStateCompletableFuture.completeExceptionally(t);
1003:                                 }
1004:                             },
1005:                             timer);
1006:         }
1007:         return masterStateCompletableFuture;
1008:     }
