1038:     /**
1039:      * The trigger request is failed. NOTE, it must be invoked if trigger request is failed.
1040:      *
1041:      * @param checkpoint the pending checkpoint which is failed. It could be null if it's failed
1042:      *     prematurely without a proper initialization.
1043:      * @param throwable the reason of trigger failure
1044:      */
1045:     private void onTriggerFailure(
1046:             @Nullable PendingCheckpoint checkpoint,
1047:             CheckpointProperties checkpointProperties,
1048:             Throwable throwable) {
1049:         try {
1050:             // beautify the stack trace a bit
1051:             throwable = ExceptionUtils.stripCompletionException(throwable);
1052: 
1053:             coordinatorsToCheckpoint.forEach(
1054:                     OperatorCoordinatorCheckpointContext::abortCurrentTriggering);
1055: 
1056:             final CheckpointException cause =
1057:                     getCheckpointException(
1058:                             CheckpointFailureReason.TRIGGER_CHECKPOINT_FAILURE, throwable);
1059: 
1060:             if (checkpoint != null && !checkpoint.isDisposed()) {
1061:                 synchronized (lock) {
1062:                     abortPendingCheckpoint(checkpoint, cause);
1063:                 }
1064:             } else {
1065:                 failureManager.handleCheckpointException(
1066:                         checkpoint, checkpointProperties, cause, null, job, null, statsTracker);
1067:             }
1068:         } catch (Throwable secondThrowable) {
1069:             secondThrowable.addSuppressed(throwable);
1070:             throw secondThrowable;
1071: 
1072:         } finally {
1073:             isTriggering = false;
1074:             executeQueuedRequest();
1075:         }
1076:     }
