1551:     private void reportFailedCheckpoint(
1552:             PendingCheckpoint pendingCheckpoint, CheckpointException exception) {
1553: 
1554:         failureManager.handleCheckpointException(
1555:                 pendingCheckpoint,
1556:                 pendingCheckpoint.getProps(),
1557:                 exception,
1558:                 null,
1559:                 job,
1560:                 getStatsCallback(pendingCheckpoint),
1561:                 statsTracker);
1562:     }
