1564:     void scheduleTriggerRequest() {
1565:         synchronized (lock) {
1566:             if (isShutdown()) {
1567:                 LOG.debug(
1568:                         "Skip scheduling trigger request because the CheckpointCoordinator is shut down");
1569:             } else {
1570:                 timer.execute(this::executeQueuedRequest);
