1575:     @VisibleForTesting
1576:     void sendAcknowledgeMessages(
1577:             List<ExecutionVertex> tasksToCommit,
1578:             long completedCheckpointId,
1579:             long completedTimestamp,
1580:             long lastSubsumedCheckpointId) {
1581:         // commit tasks
1582:         for (ExecutionVertex ev : tasksToCommit) {
1583:             Execution ee = ev.getCurrentExecutionAttempt();
1584:             if (ee != null) {
1585:                 ee.notifyCheckpointOnComplete(
1586:                         completedCheckpointId, completedTimestamp, lastSubsumedCheckpointId);
1587:             }
1588:         }
1589: 
1590:         // commit coordinators
1591:         for (OperatorCoordinatorCheckpointContext coordinatorContext : coordinatorsToCheckpoint) {
1592:             coordinatorContext.notifyCheckpointComplete(completedCheckpointId);
1593:         }
1594:     }
