1596:     private void sendAbortedMessages(
1597:             List<ExecutionVertex> tasksToAbort, long checkpointId, long timeStamp) {
1598:         assert (Thread.holdsLock(lock));
1599:         long latestCompletedCheckpointId = completedCheckpointStore.getLatestCheckpointId();
1600: 
1601:         // send notification of aborted checkpoints asynchronously.
1602:         executor.execute(
1603:                 () -> {
1604:                     // send the "abort checkpoint" messages to necessary vertices.
1605:                     for (ExecutionVertex ev : tasksToAbort) {
1606:                         Execution ee = ev.getCurrentExecutionAttempt();
1607:                         if (ee != null) {
1608:                             try {
1609:                                 ee.notifyCheckpointAborted(
1610:                                         checkpointId, latestCompletedCheckpointId, timeStamp);
1611:                             } catch (Throwable e) {
1612:                                 LOG.warn(
1613:                                         "Could not send aborted message of checkpoint {} to task {} belonging to job {}.",
1614:                                         checkpointId,
1615:                                         ee.getAttemptId(),
1616:                                         ee.getVertex().getJobId(),
1617:                                         e);
1618:                             }
1619:                         }
1620:                     }
1621:                 });
1622: 
1623:         // commit coordinators
1624:         for (OperatorCoordinatorCheckpointContext coordinatorContext : coordinatorsToCheckpoint) {
1625:             coordinatorContext.notifyCheckpointAborted(checkpointId);
1626:         }
1627:     }
