1630:         if (recentExpiredCheckpoints.size() >= NUM_GHOST_CHECKPOINT_IDS) {
1631:             recentExpiredCheckpoints.removeFirst();
1632:         }
1633:         recentExpiredCheckpoints.addLast(id);
