1647:     /**
1648:      * Restores the latest checkpointed state to a set of subtasks. This method represents a "local"
1649:      * or "regional" failover and does restore states to coordinators. Note that a regional failover
1650:      * might still include all tasks.
1651:      *
1652:      * @param tasks Set of job vertices to restore. State for these vertices is restored via {@link
1653:      *     Execution#setInitialState(JobManagerTaskRestore)}.
1654:      * @return An {@code OptionalLong} with the checkpoint ID, if state was restored, an empty
1655:      *     {@code OptionalLong} otherwise.
1656:      * @throws IllegalStateException If the CheckpointCoordinator is shut down.
1657:      * @throws IllegalStateException If no completed checkpoint is available and the <code>
1658:      *     failIfNoCheckpoint</code> flag has been set.
1659:      * @throws IllegalStateException If the checkpoint contains state that cannot be mapped to any
1660:      *     job vertex in <code>tasks</code> and the <code>allowNonRestoredState</code> flag has not
1661:      *     been set.
1662:      * @throws IllegalStateException If the max parallelism changed for an operator that restores
1663:      *     state from this checkpoint.
1664:      * @throws IllegalStateException If the parallelism changed for an operator that restores
1665:      *     <i>non-partitioned</i> state from this checkpoint.
1666:      */
1667:     public OptionalLong restoreLatestCheckpointedStateToSubtasks(
1668:             final Set<ExecutionJobVertex> tasks) throws Exception {
1669:         // when restoring subtasks only we accept potentially unmatched state for the
1670:         // following reasons
1671:         //   - the set frequently does not include all Job Vertices (only the ones that are part
1672:         //     of the restarted region), meaning there will be unmatched state by design.
1673:         //   - because what we might end up restoring from an original savepoint with unmatched
1674:         //     state, if there is was no checkpoint yet.
1675:         return restoreLatestCheckpointedStateInternal(
1676:                 tasks,
1677:                 OperatorCoordinatorRestoreBehavior
1678:                         .SKIP, // local/regional recovery does not reset coordinators
1679:                 false, // recovery might come before first successful checkpoint
1680:                 true,
1681:                 false); // see explanation above
1682:     }
1683: 
1684:     /**
1685:      * Restores the latest checkpointed state to all tasks and all coordinators. This method
1686:      * represents a "global restore"-style operation where all stateful tasks and coordinators from
1687:      * the given set of Job Vertices are restored. are restored to their latest checkpointed state.
1688:      *
1689:      * @param tasks Set of job vertices to restore. State for these vertices is restored via {@link
1690:      *     Execution#setInitialState(JobManagerTaskRestore)}.
1691:      * @param allowNonRestoredState Allow checkpoint state that cannot be mapped to any job vertex
1692:      *     in tasks.
1693:      * @return <code>true</code> if state was restored, <code>false</code> otherwise.
1694:      * @throws IllegalStateException If the CheckpointCoordinator is shut down.
1695:      * @throws IllegalStateException If no completed checkpoint is available and the <code>
1696:      *     failIfNoCheckpoint</code> flag has been set.
1697:      * @throws IllegalStateException If the checkpoint contains state that cannot be mapped to any
1698:      *     job vertex in <code>tasks</code> and the <code>allowNonRestoredState</code> flag has not
1699:      *     been set.
1700:      * @throws IllegalStateException If the max parallelism changed for an operator that restores
1701:      *     state from this checkpoint.
1702:      * @throws IllegalStateException If the parallelism changed for an operator that restores
1703:      *     <i>non-partitioned</i> state from this checkpoint.
1704:      */
1705:     public boolean restoreLatestCheckpointedStateToAll(
1706:             final Set<ExecutionJobVertex> tasks, final boolean allowNonRestoredState)
1707:             throws Exception {
1708: 
1709:         final OptionalLong restoredCheckpointId =
1710:                 restoreLatestCheckpointedStateInternal(
1711:                         tasks,
1712:                         OperatorCoordinatorRestoreBehavior
1713:                                 .RESTORE_OR_RESET, // global recovery restores coordinators, or
1714:                         // resets them to empty
1715:                         false, // recovery might come before first successful checkpoint
1716:                         allowNonRestoredState,
1717:                         false);
1718: 
1719:         return restoredCheckpointId.isPresent();
1720:     }
1721: 
1722:     /**
1723:      * Restores the latest checkpointed at the beginning of the job execution. If there is a
1724:      * checkpoint, this method acts like a "global restore"-style operation where all stateful tasks
1725:      * and coordinators from the given set of Job Vertices are restored.
1726:      *
1727:      * @param tasks Set of job vertices to restore. State for these vertices is restored via {@link
1728:      *     Execution#setInitialState(JobManagerTaskRestore)}.
1729:      * @return True, if a checkpoint was found and its state was restored, false otherwise.
1730:      */
1731:     public boolean restoreInitialCheckpointIfPresent(final Set<ExecutionJobVertex> tasks)
1732:             throws Exception {
1733:         final OptionalLong restoredCheckpointId =
1734:                 restoreLatestCheckpointedStateInternal(
1735:                         tasks,
1736:                         OperatorCoordinatorRestoreBehavior.RESTORE_IF_CHECKPOINT_PRESENT,
1737:                         false, // initial checkpoints exist only on JobManager failover. ok if not
1738:                         // present.
1739:                         false,
1740:                         true); // JobManager failover means JobGraphs match exactly.
1741: 
1742:         return restoredCheckpointId.isPresent();
1743:     }
1744: 
1745:     /**
1746:      * Performs the actual restore operation to the given tasks.
1747:      *
1748:      * <p>This method returns the restored checkpoint ID (as an optional) or an empty optional, if
1749:      * no checkpoint was restored.
1750:      */
1751:     private OptionalLong restoreLatestCheckpointedStateInternal(
1752:             final Set<ExecutionJobVertex> tasks,
1753:             final OperatorCoordinatorRestoreBehavior operatorCoordinatorRestoreBehavior,
1754:             final boolean errorIfNoCheckpoint,
1755:             final boolean allowNonRestoredState,
1756:             final boolean checkForPartiallyFinishedOperators)
1757:             throws Exception {
1758: 
1759:         synchronized (lock) {
1760:             if (shutdown) {
1761:                 throw new IllegalStateException("CheckpointCoordinator is shut down");
1762:             }
1763:             long restoreTimestamp = SystemClock.getInstance().absoluteTimeMillis();
1764:             statsTracker.reportInitializationStarted(
1765:                     tasks.stream()
1766:                             .map(ExecutionJobVertex::getTaskVertices)
1767:                             .flatMap(Stream::of)
1768:                             .map(ExecutionVertex::getCurrentExecutionAttempt)
1769:                             .map(Execution::getAttemptId)
1770:                             .collect(Collectors.toSet()),
1771:                     restoreTimestamp);
1772: 
1773:             // Restore from the latest checkpoint
1774:             CompletedCheckpoint latest = completedCheckpointStore.getLatestCheckpoint();
1775: 
1776:             if (latest == null) {
1777:                 LOG.info("No checkpoint found during restore.");
1778: 
1779:                 if (errorIfNoCheckpoint) {
1780:                     throw new IllegalStateException("No completed checkpoint available");
1781:                 }
1782: 
1783:                 LOG.debug("Resetting the master hooks.");
1784:                 MasterHooks.reset(masterHooks.values(), LOG);
1785: 
1786:                 if (operatorCoordinatorRestoreBehavior
1787:                         == OperatorCoordinatorRestoreBehavior.RESTORE_OR_RESET) {
1788:                     // we let the JobManager-side components know that there was a recovery,
1789:                     // even if there was no checkpoint to recover from, yet
1790:                     LOG.info("Resetting the Operator Coordinators to an empty state.");
1791:                     restoreStateToCoordinators(
1792:                             OperatorCoordinator.NO_CHECKPOINT, Collections.emptyMap());
1793:                 }
1794: 
1795:                 return OptionalLong.empty();
1796:             }
1797: 
1798:             statsTracker.reportRestoredCheckpoint(
1799:                     latest.getCheckpointID(),
1800:                     latest.getProperties(),
1801:                     latest.getExternalPointer(),
1802:                     latest.getStateSize());
1803: 
1804:             LOG.info("Restoring job {} from {}.", job, latest);
1805: 
1806:             this.forceFullSnapshot = latest.getProperties().isUnclaimed();
1807: 
1808:             // re-assign the task states
1809:             final Map<OperatorID, OperatorState> operatorStates = extractOperatorStates(latest);
1810: 
1811:             if (checkForPartiallyFinishedOperators) {
1812:                 VertexFinishedStateChecker vertexFinishedStateChecker =
1813:                         vertexFinishedStateCheckerFactory.apply(tasks, operatorStates);
1814:                 vertexFinishedStateChecker.validateOperatorsFinishedState();
1815:             }
1816: 
1817:             StateAssignmentOperation stateAssignmentOperation =
1818:                     new StateAssignmentOperation(
1819:                             latest.getCheckpointID(), tasks, operatorStates, allowNonRestoredState);
1820: 
1821:             stateAssignmentOperation.assignStates();
1822: 
1823:             // call master hooks for restore. we currently call them also on "regional restore"
1824:             // because
1825:             // there is no other failure notification mechanism in the master hooks
1826:             // ultimately these should get removed anyways in favor of the operator coordinators
1827: 
1828:             MasterHooks.restoreMasterHooks(
1829:                     masterHooks,
1830:                     latest.getMasterHookStates(),
1831:                     latest.getCheckpointID(),
1832:                     allowNonRestoredState,
1833:                     LOG);
1834: 
1835:             if (operatorCoordinatorRestoreBehavior != OperatorCoordinatorRestoreBehavior.SKIP) {
1836:                 restoreStateToCoordinators(latest.getCheckpointID(), operatorStates);
1837:             }
1838: 
1839:             return OptionalLong.of(latest.getCheckpointID());
1840:         }
1841:     }
1842: 
1843:     private Map<OperatorID, OperatorState> extractOperatorStates(CompletedCheckpoint checkpoint) {
1844:         Map<OperatorID, OperatorState> originalOperatorStates = checkpoint.getOperatorStates();
1845: 
1846:         if (checkpoint.getCheckpointID() != checkpointIdOfIgnoredInFlightData) {
1847:             // Don't do any changes if it is not required.
1848:             return originalOperatorStates;
1849:         }
1850: 
1851:         HashMap<OperatorID, OperatorState> newStates = new HashMap<>();
1852:         // Create the new operator states without in-flight data.
1853:         for (OperatorState originalOperatorState : originalOperatorStates.values()) {
1854:             newStates.put(
1855:                     originalOperatorState.getOperatorID(),
1856:                     originalOperatorState.copyAndDiscardInFlightData());
1857:         }
1858: 
1859:         return newStates;
1860:     }
