1862:     /**
1863:      * Restore the state with given savepoint.
1864:      *
1865:      * @param restoreSettings Settings for a snapshot to restore from. Includes the path and
1866:      *     parameters for the restore process.
1867:      * @param tasks Map of job vertices to restore. State for these vertices is restored via {@link
1868:      *     Execution#setInitialState(JobManagerTaskRestore)}.
1869:      * @param userClassLoader The class loader to resolve serialized classes in legacy savepoint
1870:      *     versions.
1871:      */
1872:     public boolean restoreSavepoint(
1873:             SavepointRestoreSettings restoreSettings,
1874:             Map<JobVertexID, ExecutionJobVertex> tasks,
1875:             ClassLoader userClassLoader)
1876:             throws Exception {
1877: 
1878:         final String savepointPointer = restoreSettings.getRestorePath();
1879:         final boolean allowNonRestored = restoreSettings.allowNonRestoredState();
1880:         Preconditions.checkNotNull(savepointPointer, "The savepoint path cannot be null.");
1881: 
1882:         LOG.info(
1883:                 "Starting job {} from savepoint {} ({})",
1884:                 job,
1885:                 savepointPointer,
1886:                 (allowNonRestored ? "allowing non restored state" : ""));
1887: 
1888:         final CompletedCheckpointStorageLocation checkpointLocation =
1889:                 checkpointStorageView.resolveCheckpoint(savepointPointer);
1890: 
1891:         // convert to checkpoint so the system can fall back to it
1892:         final CheckpointProperties checkpointProperties;
1893:         switch (restoreSettings.getRestoreMode()) {
1894:             case CLAIM:
1895:                 checkpointProperties = this.checkpointProperties;
1896:                 break;
1897:             case LEGACY:
1898:                 checkpointProperties =
1899:                         CheckpointProperties.forSavepoint(
1900:                                 false,
1901:                                 // we do not care about the format when restoring, the format is
1902:                                 // necessary when triggering a savepoint
1903:                                 SavepointFormatType.CANONICAL);
1904:                 break;
1905:             case NO_CLAIM:
1906:                 checkpointProperties = CheckpointProperties.forUnclaimedSnapshot();
1907:                 break;
1908:             default:
1909:                 throw new IllegalArgumentException("Unknown snapshot claim mode");
1910:         }
1911: 
1912:         // Load the savepoint as a checkpoint into the system
1913:         CompletedCheckpoint savepoint =
1914:                 Checkpoints.loadAndValidateCheckpoint(
1915:                         job,
1916:                         tasks,
1917:                         checkpointLocation,
1918:                         userClassLoader,
1919:                         allowNonRestored,
1920:                         checkpointProperties);
1921: 
1922:         // register shared state - even before adding the checkpoint to the store
1923:         // because the latter might trigger subsumption so the ref counts must be up-to-date
1924:         savepoint.registerSharedStatesAfterRestored(
1925:                 completedCheckpointStore.getSharedStateRegistry(),
1926:                 restoreSettings.getRestoreMode());
1927: 
1928:         completedCheckpointStore.addCheckpointAndSubsumeOldestOne(
1929:                 savepoint, checkpointsCleaner, this::scheduleTriggerRequest);
1930: 
1931:         // Reset the checkpoint ID counter
1932:         long nextCheckpointId = savepoint.getCheckpointID() + 1;
1933:         checkpointIdCounter.setCount(nextCheckpointId);
1934: 
1935:         LOG.info("Reset the checkpoint ID of job {} to {}.", job, nextCheckpointId);
1936: 
1937:         final OptionalLong restoredCheckpointId =
1938:                 restoreLatestCheckpointedStateInternal(
1939:                         new HashSet<>(tasks.values()),
1940:                         OperatorCoordinatorRestoreBehavior.RESTORE_IF_CHECKPOINT_PRESENT,
1941:                         true,
1942:                         allowNonRestored,
1943:                         true);
1944: 
1945:         return restoredCheckpointId.isPresent();
1946:     }
