2032:     public void startCheckpointScheduler() {
2033:         synchronized (lock) {
2034:             if (shutdown) {
2035:                 throw new IllegalArgumentException("Checkpoint coordinator is shut down");
2036:             }
2037:             Preconditions.checkState(
2038:                     isPeriodicCheckpointingConfigured(),
2039:                     "Can not start checkpoint scheduler, if no periodic checkpointing is configured");
2040: 
2041:             if (isPeriodicCheckpointingStarted()) {
2042:                 // cancel previously scheduled checkpoints and spare savepoints.
2043:                 // TODO: Introduce a more general solution to the race condition
2044:                 //  between different checkpoint scheduling triggers.
2045:                 //  https://issues.apache.org/jira/browse/FLINK-34519
2046:                 stopCheckpointScheduler();
2047:             }
2048: 
2049:             periodicScheduling = true;
2050:             scheduleTriggerWithDelay(clock.relativeTimeMillis(), getRandomInitDelay());
2051:         }
2052:     }
