2081:     private void abortPendingCheckpoints(
2082:             Predicate<PendingCheckpoint> checkpointToFailPredicate, CheckpointException exception) {
2083: 
2084:         assert Thread.holdsLock(lock);
2085: 
2086:         final PendingCheckpoint[] pendingCheckpointsToFail =
2087:                 pendingCheckpoints.values().stream()
2088:                         .filter(checkpointToFailPredicate)
2089:                         .toArray(PendingCheckpoint[]::new);
2090: 
2091:         // do not traverse pendingCheckpoints directly, because it might be changed during
2092:         // traversing
2093:         for (PendingCheckpoint pendingCheckpoint : pendingCheckpointsToFail) {
2094:             abortPendingCheckpoint(pendingCheckpoint, exception);
2095:         }
2096:     }
