2103:     private void cancelPeriodicTrigger() {
2104:         if (currentPeriodicTrigger != null) {
2105:             nextCheckpointTriggeringRelativeTime = Long.MAX_VALUE;
2106:             currentPeriodicTriggerFuture.cancel(false);
2107:             currentPeriodicTrigger = null;
2108:             currentPeriodicTriggerFuture = null;
