2116:     private void scheduleTriggerWithDelay(long currentRelativeTime, long initDelay) {
2117:         nextCheckpointTriggeringRelativeTime = currentRelativeTime + initDelay;
2118:         currentPeriodicTrigger = new ScheduledTrigger();
2119:         currentPeriodicTriggerFuture =
2120:                 timer.schedule(currentPeriodicTrigger, initDelay, TimeUnit.MILLISECONDS);
