2128:             final OperatorState state = operatorStates.get(coordContext.operatorId());
2129:             final ByteStreamStateHandle coordinatorState =
2130:                     state == null ? null : state.getCoordinatorState();
2131:             final byte[] bytes = coordinatorState == null ? null : coordinatorState.getData();
2132:             coordContext.resetToCheckpoint(checkpointId, bytes);
