2174:     final class ScheduledTrigger implements Runnable {
2175: 
2176:         @Override
2177:         public void run() {
2178:             synchronized (lock) {
2179:                 if (currentPeriodicTrigger != this) {
2180:                     // Another periodic trigger has been scheduled but this one
2181:                     // has not been force cancelled yet.
2182:                     return;
2183:                 }
2184: 
2185:                 long checkpointInterval = getCurrentCheckpointInterval();
2186:                 if (checkpointInterval
2187:                         != CheckpointCoordinatorConfiguration.DISABLED_CHECKPOINT_INTERVAL) {
2188:                     nextCheckpointTriggeringRelativeTime += checkpointInterval;
2189:                     currentPeriodicTriggerFuture =
2190:                             timer.schedule(
2191:                                     this,
2192:                                     Math.max(
2193:                                             0,
2194:                                             nextCheckpointTriggeringRelativeTime
2195:                                                     - clock.relativeTimeMillis()),
2196:                                     TimeUnit.MILLISECONDS);
2197:                 } else {
2198:                     nextCheckpointTriggeringRelativeTime = Long.MAX_VALUE;
2199:                     currentPeriodicTrigger = null;
2200:                     currentPeriodicTriggerFuture = null;
2201:                 }
2202:             }
2203: 
2204:             try {
2205:                 triggerCheckpoint(checkpointProperties, null, true);
2206:             } catch (Exception e) {
2207:                 LOG.error("Exception while triggering checkpoint for job {}.", job, e);
2208:             }
2209:         }
2210:     }
