80:     @Override
81:     public StreamStateHandle registerReference(
82:             final SharedStateRegistryKey registrationKey,
83:             final StreamStateHandle newHandle,
84:             final long checkpointID,
85:             final boolean preventDiscardingCreatedCheckpoint) {
86: 
87:         checkNotNull(newHandle, "State handle should not be null.");
88: 
89:         SharedStateEntry entry;
90: 
91:         synchronized (registeredStates) {
92:             checkState(open, "Attempt to register state to closed SharedStateRegistry.");
93: 
94:             entry = registeredStates.get(registrationKey);
95: 
96:             if (entry == null) {
97:                 checkState(
98:                         !isPlaceholder(newHandle),
99:                         "Attempt to reference unknown state: " + registrationKey);
100: 
101:                 LOG.trace(
102:                         "Registered new shared state {} under key {}.", newHandle, registrationKey);
103:                 entry = new SharedStateEntry(newHandle, checkpointID);
104:                 registeredStates.put(registrationKey, entry);
105: 
106:                 // no further handling
107:                 return entry.stateHandle;
108: 
109:             } else if (entry.stateHandle == newHandle) {
110:                 // might be a bug but state backend is not required to use a place-holder
111:                 LOG.info(
112:                         "Duplicated registration under key {} with the same object: {}",
113:                         registrationKey,
114:                         newHandle);
115:             } else if (Objects.equals(entry.stateHandle, newHandle)) {
116:                 LOG.trace(
117:                         "Duplicated registration under key {} with the new object: {}.",
118:                         registrationKey,
119:                         newHandle);
120:             } else if (isPlaceholder(newHandle)) {
121:                 LOG.trace(
122:                         "Duplicated registration under key {} with a placeholder (normal case)",
123:                         registrationKey);
124:             } else {
125:                 // might be a bug expect the StreamStateHandleWrapper used by
126:                 // ChangelogStateBackendHandleImpl
127:                 LOG.info(
128:                         "the registered handle should equal to the previous one or is a placeholder, register key:{}, handle:{}",
129:                         registrationKey,
130:                         newHandle);
131:                 if (entry.stateHandle instanceof EmptyDiscardStateObjectForRegister) {
132:                     // This situation means that newHandle is a StreamStateHandleWrapper registered
133:                     // by ChangelogStateBackendHandleImpl, keep the new one for discard the
134:                     // underlying handle while it was useless. Refactor this once FLINK-25862 is
135:                     // resolved.
136:                     entry.stateHandle = newHandle;
137:                 } else {
138:                     throw new IllegalStateException(
139:                             "StateObjects underlying same key should be equal !");
140:                 }
141:             }
142: 
143:             LOG.trace(
144:                     "Updating last checkpoint for {} from {} to {}",
145:                     registrationKey,
146:                     entry.lastUsedCheckpointID,
147:                     checkpointID);
148:             entry.advanceLastUsingCheckpointID(checkpointID);
149: 
150:             if (preventDiscardingCreatedCheckpoint) {
151:                 entry.preventDiscardingCreatedCheckpoint();
152:             }
153:         } // end of synchronized (registeredStates)
154: 
155:         return entry.stateHandle;
156:     }
