158:     @Override
159:     public Set<Long> unregisterUnusedState(long lowestCheckpointID) {
160:         Set<Long> checkpointInUse = new HashSet<>();
161:         LOG.debug(
162:                 "Discard state created before checkpoint {} and not used afterwards",
163:                 lowestCheckpointID);
164:         List<StreamStateHandle> subsumed = new ArrayList<>();
165:         // Iterate over all the registered state handles.
166:         // Using a simple loop and NOT index by checkpointID because:
167:         // 1. Maintaining index leads to the same time complexity and worse memory complexity
168:         // 2. Most of the entries are expected to be carried to the next checkpoint
169:         synchronized (registeredStates) {
170:             Iterator<SharedStateEntry> it = registeredStates.values().iterator();
171:             while (it.hasNext()) {
172:                 SharedStateEntry entry = it.next();
173:                 if (entry.lastUsedCheckpointID < lowestCheckpointID) {
174:                     if (entry.createdByCheckpointID > highestNotClaimedCheckpointID) {
175:                         subsumed.add(entry.stateHandle);
176:                     }
177:                     it.remove();
178:                 } else if (preventsDiscardingCreatedCheckpoint(entry)) {
179:                     // Newly created checkpoints can be discarded right after subsumption. But the
180:                     // initial checkpoint needs to be kept until all of its private AND shared state
181:                     // is not in use. This is to enable recovery in CLAIM mode from:
182:                     // - native incremental savepoints
183:                     // - non-changelog checkpoints with changelog enabled
184:                     // Keeping any checkpoint for longer leaves its folder undeleted on job
185:                     // cancellation (and also on crash or JM failover).
186:                     checkpointInUse.add(entry.createdByCheckpointID);
187:                 }
188:             }
189:         }
190:         LOG.trace("Discard {} state asynchronously", subsumed.size());
191:         for (StreamStateHandle handle : subsumed) {
192:             scheduleAsyncDelete(handle);
193:         }
194:         return checkpointInUse;
195:     }
