212:     @Override
213:     public void registerAllAfterRestored(CompletedCheckpoint checkpoint, RECOVERY_CLAIM_MODE mode) {
214:         registerAll(checkpoint.getOperatorStates().values(), checkpoint.getCheckpointID());
215:         restoredCheckpointSharingStrategies.put(
216:                 checkpoint.getCheckpointID(),
217:                 checkpoint
218:                         .getRestoredProperties()
219:                         .map(props -> props.getCheckpointType().getSharingFilesStrategy()));
220:         // In NO_CLAIM and LEGACY claim modes, shared state of the initial checkpoints must be
221:         // preserved. This is achieved by advancing highestRetainCheckpointID here, and then
222:         // checking entry.createdByCheckpointID against it on checkpoint subsumption.
223:         // In CLAIM mode, the shared state of the initial checkpoints must be
224:         // discarded as soon as it becomes unused - so highestRetainCheckpointID is not updated.
225:         if (mode != RECOVERY_CLAIM_MODE.RECOVERY_CLAIM_MODE) {
226:             highestNotClaimedCheckpointID =
227:                     Math.max(highestNotClaimedCheckpointID, checkpoint.getCheckpointID());
