243:     private void scheduleAsyncDelete(StreamStateHandle streamStateHandle) {
244:         // We do the small optimization to not issue discards for placeholders, which are NOPs.
245:         if (streamStateHandle != null && !isPlaceholder(streamStateHandle)) {
246:             LOG.debug("Scheduled delete of state handle {}.", streamStateHandle);
247:             AsyncDisposalRunnable asyncDisposalRunnable =
248:                     new AsyncDisposalRunnable(streamStateHandle);
249:             try {
250:                 asyncDisposalExecutor.execute(asyncDisposalRunnable);
251:             } catch (RejectedExecutionException ex) {
252:                 // TODO This is a temporary fix for a problem during
253:                 // ZooKeeperCompletedCheckpointStore#shutdown:
254:                 // Disposal is issued in another async thread and the shutdown proceeds to close the
255:                 // I/O Executor pool.
256:                 // This leads to RejectedExecutionException once the async deletes are triggered by
257:                 // ZK. We need to
258:                 // wait for all pending ZK deletes before closing the I/O Executor pool. We can
259:                 // simply call #run()
260:                 // because we are already in the async ZK thread that disposes the handles.
261:                 asyncDisposalRunnable.run();
262:             }
263:         }
264:     }
