401:     private boolean preventsDiscardingCreatedCheckpoint(SharedStateEntry entry) {
402:         // explicitly set by the backend, e.g. private state is reused
403:         if (entry.preventDiscardingCreatedCheckpoint
404:                 && restoredCheckpointSharingStrategies.containsKey(entry.createdByCheckpointID)) {
405:             return true;
406:         }
407:         // With NO_SHARING strategy, shared state, if any, is bundled inside the checkpoint folder.
408:         // So the folder deletion should be delayed as long as some shared state is still in use.
409:         // That allows to recover from Incremental RocksDB Native Savepoint in CLAIM mode.
410:         // noinspection RedundantIfStatement
411:         if (restoredCheckpointSharingStrategies
412:                 .getOrDefault(entry.createdByCheckpointID, Optional.empty())
413:                 .filter(sharingFilesStrategy -> sharingFilesStrategy == NO_SHARING)
414:                 .isPresent()) {
415:             return true;
416:         }
417: 
418:         return false;
