48: /** {@link SharedStateRegistry} implementation. */
49: @Internal
50: public class SharedStateRegistryImpl implements SharedStateRegistry {
51: 
52:     private static final Logger LOG = LoggerFactory.getLogger(SharedStateRegistryImpl.class);
53: 
54:     /** All registered state objects by an artificial key */
55:     private final Map<SharedStateRegistryKey, SharedStateEntry> registeredStates;
56: 
57:     private final Map<Long, Optional<SharingFilesStrategy>> restoredCheckpointSharingStrategies =
58:             new HashMap<>();
59: 
60:     /** This flag indicates whether or not the registry is open or if close() was called */
61:     private boolean open;
62: 
63:     /** Executor for async state deletion */
64:     private final Executor asyncDisposalExecutor;
65: 
66:     /** Checkpoint ID below which no state is discarded, inclusive. */
67:     private long highestNotClaimedCheckpointID = -1L;
68: 
69:     /** Default uses direct executor to delete unreferenced state */
70:     public SharedStateRegistryImpl() {
71:         this(Executors.directExecutor());
72:     }
73: 
74:     public SharedStateRegistryImpl(Executor asyncDisposalExecutor) {
75:         this.registeredStates = new HashMap<>();
76:         this.asyncDisposalExecutor = checkNotNull(asyncDisposalExecutor);
77:         this.open = true;
78:     }
79: 
80:     @Override
81:     public StreamStateHandle registerReference(
82:             final SharedStateRegistryKey registrationKey,
83:             final StreamStateHandle newHandle,
84:             final long checkpointID,
85:             final boolean preventDiscardingCreatedCheckpoint) {
86: 
87:         checkNotNull(newHandle, "State handle should not be null.");
88: 
89:         SharedStateEntry entry;
90: 
91:         synchronized (registeredStates) {
92:             checkState(open, "Attempt to register state to closed SharedStateRegistry.");
93: 
94:             entry = registeredStates.get(registrationKey);
95: 
96:             if (entry == null) {
97:                 checkState(
98:                         !isPlaceholder(newHandle),
99:                         "Attempt to reference unknown state: " + registrationKey);
100: 
101:                 LOG.trace(
102:                         "Registered new shared state {} under key {}.", newHandle, registrationKey);
103:                 entry = new SharedStateEntry(newHandle, checkpointID);
104:                 registeredStates.put(registrationKey, entry);
105: 
106:                 // no further handling
107:                 return entry.stateHandle;
108: 
109:             } else if (entry.stateHandle == newHandle) {
110:                 // might be a bug but state backend is not required to use a place-holder
111:                 LOG.info(
112:                         "Duplicated registration under key {} with the same object: {}",
113:                         registrationKey,
114:                         newHandle);
115:             } else if (Objects.equals(entry.stateHandle, newHandle)) {
116:                 LOG.trace(
117:                         "Duplicated registration under key {} with the new object: {}.",
118:                         registrationKey,
119:                         newHandle);
120:             } else if (isPlaceholder(newHandle)) {
121:                 LOG.trace(
122:                         "Duplicated registration under key {} with a placeholder (normal case)",
123:                         registrationKey);
124:             } else {
125:                 // might be a bug expect the StreamStateHandleWrapper used by
126:                 // ChangelogStateBackendHandleImpl
127:                 LOG.info(
128:                         "the registered handle should equal to the previous one or is a placeholder, register key:{}, handle:{}",
129:                         registrationKey,
130:                         newHandle);
131:                 if (entry.stateHandle instanceof EmptyDiscardStateObjectForRegister) {
132:                     // This situation means that newHandle is a StreamStateHandleWrapper registered
133:                     // by ChangelogStateBackendHandleImpl, keep the new one for discard the
134:                     // underlying handle while it was useless. Refactor this once FLINK-25862 is
135:                     // resolved.
136:                     entry.stateHandle = newHandle;
137:                 } else {
138:                     throw new IllegalStateException(
139:                             "StateObjects underlying same key should be equal !");
140:                 }
141:             }
142: 
143:             LOG.trace(
144:                     "Updating last checkpoint for {} from {} to {}",
145:                     registrationKey,
146:                     entry.lastUsedCheckpointID,
147:                     checkpointID);
148:             entry.advanceLastUsingCheckpointID(checkpointID);
149: 
150:             if (preventDiscardingCreatedCheckpoint) {
151:                 entry.preventDiscardingCreatedCheckpoint();
152:             }
153:         } // end of synchronized (registeredStates)
154: 
155:         return entry.stateHandle;
156:     }
157: 
158:     @Override
159:     public Set<Long> unregisterUnusedState(long lowestCheckpointID) {
160:         Set<Long> checkpointInUse = new HashSet<>();
161:         LOG.debug(
162:                 "Discard state created before checkpoint {} and not used afterwards",
163:                 lowestCheckpointID);
164:         List<StreamStateHandle> subsumed = new ArrayList<>();
165:         // Iterate over all the registered state handles.
166:         // Using a simple loop and NOT index by checkpointID because:
167:         // 1. Maintaining index leads to the same time complexity and worse memory complexity
168:         // 2. Most of the entries are expected to be carried to the next checkpoint
169:         synchronized (registeredStates) {
170:             Iterator<SharedStateEntry> it = registeredStates.values().iterator();
171:             while (it.hasNext()) {
172:                 SharedStateEntry entry = it.next();
173:                 if (entry.lastUsedCheckpointID < lowestCheckpointID) {
174:                     if (entry.createdByCheckpointID > highestNotClaimedCheckpointID) {
175:                         subsumed.add(entry.stateHandle);
176:                     }
177:                     it.remove();
178:                 } else if (preventsDiscardingCreatedCheckpoint(entry)) {
179:                     // Newly created checkpoints can be discarded right after subsumption. But the
180:                     // initial checkpoint needs to be kept until all of its private AND shared state
181:                     // is not in use. This is to enable recovery in CLAIM mode from:
182:                     // - native incremental savepoints
183:                     // - non-changelog checkpoints with changelog enabled
184:                     // Keeping any checkpoint for longer leaves its folder undeleted on job
185:                     // cancellation (and also on crash or JM failover).
186:                     checkpointInUse.add(entry.createdByCheckpointID);
187:                 }
188:             }
189:         }
190:         LOG.trace("Discard {} state asynchronously", subsumed.size());
191:         for (StreamStateHandle handle : subsumed) {
192:             scheduleAsyncDelete(handle);
193:         }
194:         return checkpointInUse;
195:     }
196: 
197:     @Override
198:     public void registerAll(
199:             Iterable<? extends CompositeStateHandle> stateHandles, long checkpointID) {
200: 
201:         if (stateHandles == null) {
202:             return;
203:         }
204: 
205:         synchronized (registeredStates) {
206:             for (CompositeStateHandle stateHandle : stateHandles) {
207:                 stateHandle.registerSharedStates(this, checkpointID);
208:             }
209:         }
210:     }
211: 
212:     @Override
213:     public void registerAllAfterRestored(CompletedCheckpoint checkpoint, RecoveryClaimMode mode) {
214:         registerAll(checkpoint.getOperatorStates().values(), checkpoint.getCheckpointID());
215:         restoredCheckpointSharingStrategies.put(
216:                 checkpoint.getCheckpointID(),
217:                 checkpoint
218:                         .getRestoredProperties()
219:                         .map(props -> props.getCheckpointType().getSharingFilesStrategy()));
220:         // In NO_CLAIM and LEGACY claim modes, shared state of the initial checkpoints must be
221:         // preserved. This is achieved by advancing highestRetainCheckpointID here, and then
222:         // checking entry.createdByCheckpointID against it on checkpoint subsumption.
223:         // In CLAIM mode, the shared state of the initial checkpoints must be
224:         // discarded as soon as it becomes unused - so highestRetainCheckpointID is not updated.
225:         if (mode != RecoveryClaimMode.RECOVERY_CLAIM_MODE) {
226:             highestNotClaimedCheckpointID =
227:                     Math.max(highestNotClaimedCheckpointID, checkpoint.getCheckpointID());
228:         }
229:     }
230: 
231:     @Override
232:     public void checkpointCompleted(long checkpointId) {
233:         // nothing to do here
234:     }
235: 
236:     @Override
237:     public String toString() {
238:         synchronized (registeredStates) {
239:             return "SharedStateRegistry{" + "registeredStates=" + registeredStates + '}';
240:         }
241:     }
