277:     /** Encapsulates the operation the delete state handles asynchronously. */
278:     private static final class AsyncDisposalRunnable implements Runnable {
279: 
280:         private final StateObject toDispose;
281: 
282:         public AsyncDisposalRunnable(StateObject toDispose) {
283:             this.toDispose = checkNotNull(toDispose);
284:         }
285: 
286:         @Override
287:         public void run() {
288:             try {
289:                 toDispose.discardState();
290:             } catch (Exception e) {
291:                 LOG.warn(
292:                         "A problem occurred during asynchronous disposal of a shared state object: {}",
293:                         toDispose,
294:                         e);
295:             }
296:         }
297:     }
298:     /** An entry in the registry, tracking the handle and the corresponding reference count. */
299:     private static final class SharedStateEntry {
300: 
301:         /**
302:          * Whether usage of this state should prevent deletion of the checkpoint that created this
303:          * state.
304:          */
305:         private boolean preventDiscardingCreatedCheckpoint = false;
306: 
307:         /** The shared state handle */
308:         StreamStateHandle stateHandle;
309: 
310:         private final long createdByCheckpointID;
311: 
312:         private long lastUsedCheckpointID;
313: 
314:         SharedStateEntry(StreamStateHandle value, long checkpointID) {
315:             this.stateHandle = value;
316:             this.createdByCheckpointID = checkpointID;
317:             this.lastUsedCheckpointID = checkpointID;
318:         }
319: 
320:         @Override
321:         public String toString() {
322:             return "SharedStateEntry{"
323:                     + "stateHandle="
324:                     + stateHandle
325:                     + ", createdByCheckpointID="
326:                     + createdByCheckpointID
327:                     + ", lastUsedCheckpointID="
328:                     + lastUsedCheckpointID
329:                     + '}';
330:         }
331: 
332:         private void advanceLastUsingCheckpointID(long checkpointID) {
333:             lastUsedCheckpointID = Math.max(checkpointID, lastUsedCheckpointID);
334:         }
335: 
336:         private void preventDiscardingCreatedCheckpoint() {
337:             // Changed from false to true when a newer checkpoint starts reusing this state entry
338:             // after recovery. This is to delay discarding the checkpoint until all of its
339:             // state (both shared and private) is not used. That allows to handle transition from
340:             // changelog off to on in CLAIM mode.
341:             this.preventDiscardingCreatedCheckpoint = true;
342:         }
343:     }
344: 
345:     /** An object with empty discardState for registering. */
346:     public static class EmptyDiscardStateObjectForRegister implements StreamStateHandle {
347:         private static final long serialVersionUID = 1L;
348: 
349:         private StateHandleID stateHandleID;
350: 
351:         public EmptyDiscardStateObjectForRegister(StateHandleID stateHandleID) {
352:             this.stateHandleID = stateHandleID;
353:         }
354: 
355:         @Override
356:         public void discardState() throws Exception {}
357: 
358:         @Override
359:         public long getStateSize() {
360:             throw new UnsupportedOperationException("Should not call here.");
361:         }
362: 
363:         @Override
364:         public FSDataInputStream openInputStream() throws IOException {
365:             throw new UnsupportedOperationException("Should not call here.");
366:         }
367: 
368:         @Override
369:         public Optional<byte[]> asBytesIfInMemory() {
370:             throw new UnsupportedOperationException("Should not call here.");
371:         }
372: 
373:         @Override
374:         public PhysicalStateHandleID getStreamStateHandleID() {
375:             throw new UnsupportedOperationException("Should not call here.");
376:         }
377: 
378:         @Override
379:         public boolean equals(Object o) {
380:             if (this == o) {
381:                 return true;
382:             }
383:             if (o == null || getClass() != o.getClass()) {
384:                 return false;
385:             }
386:             EmptyDiscardStateObjectForRegister that = (EmptyDiscardStateObjectForRegister) o;
387:             return Objects.equals(stateHandleID, that.stateHandleID);
388:         }
389: 
390:         @Override
391:         public int hashCode() {
392:             return Objects.hash(stateHandleID);
393:         }
394: 
395:         @Override
396:         public String toString() {
397:             return "EmptyDiscardStateObject{" + stateHandleID + '}';
398:         }
399:     }
400: 
401:     private boolean preventsDiscardingCreatedCheckpoint(SharedStateEntry entry) {
402:         // explicitly set by the backend, e.g. private state is reused
403:         if (entry.preventDiscardingCreatedCheckpoint
404:                 && restoredCheckpointSharingStrategies.containsKey(entry.createdByCheckpointID)) {
405:             return true;
406:         }
407:         // With NO_SHARING strategy, shared state, if any, is bundled inside the checkpoint folder.
408:         // So the folder deletion should be delayed as long as some shared state is still in use.
409:         // That allows to recover from Incremental RocksDB Native Savepoint in CLAIM mode.
410:         // noinspection RedundantIfStatement
411:         if (restoredCheckpointSharingStrategies
412:                 .getOrDefault(entry.createdByCheckpointID, Optional.empty())
413:                 .filter(sharingFilesStrategy -> sharingFilesStrategy == NO_SHARING)
414:                 .isPresent()) {
415:             return true;
416:         }
417: 
418:         return false;
419:     }
420: }
