41: /**
42:  * Starts a {@link MiniCluster} for every submitted job. This class guarantees to tear down the
43:  * MiniCluster in case of normal or exceptional job completion.
44:  */
45: public final class PerJobMiniClusterFactory {
46: 
47:     private static final Logger LOG = LoggerFactory.getLogger(PerJobMiniClusterFactory.class);
48: 
49:     private final Configuration configuration;
50:     private final Function<? super MiniClusterConfiguration, ? extends MiniCluster>
51:             miniClusterFactory;
52: 
53:     public static PerJobMiniClusterFactory create() {
54:         return new PerJobMiniClusterFactory(new Configuration(), MiniCluster::new);
55:     }
56: 
57:     public static PerJobMiniClusterFactory createWithFactory(
58:             Configuration configuration,
59:             Function<? super MiniClusterConfiguration, ? extends MiniCluster> miniClusterFactory) {
60:         return new PerJobMiniClusterFactory(configuration, miniClusterFactory);
61:     }
62: 
63:     private PerJobMiniClusterFactory(
64:             Configuration configuration,
65:             Function<? super MiniClusterConfiguration, ? extends MiniCluster> miniClusterFactory) {
66:         this.configuration = configuration;
67:         this.miniClusterFactory = miniClusterFactory;
68:     }
69: 
70:     /** Starts a {@link MiniCluster} and submits a job. */
71:     public CompletableFuture<JobClient> submitJob(
72:             JobGraph jobGraph, ClassLoader userCodeClassloader) throws Exception {
73:         MiniClusterConfiguration miniClusterConfig =
74:                 getMiniClusterConfig(jobGraph.getMaximumParallelism());
75:         MiniCluster miniCluster = miniClusterFactory.apply(miniClusterConfig);
76:         miniCluster.start();
77: 
78:         return miniCluster
79:                 .submitJob(jobGraph)
80:                 .thenApplyAsync(
81:                         FunctionUtils.uncheckedFunction(
82:                                 submissionResult -> {
83:                                     org.apache.flink.client.ClientUtils
84:                                             .waitUntilJobInitializationFinished(
85:                                                     () ->
86:                                                             miniCluster
87:                                                                     .getJobStatus(
88:                                                                             submissionResult
89:                                                                                     .getJobID())
90:                                                                     .get(),
91:                                                     () ->
92:                                                             miniCluster
93:                                                                     .requestJobResult(
94:                                                                             submissionResult
95:                                                                                     .getJobID())
96:                                                                     .get(),
97:                                                     userCodeClassloader);
98:                                     return submissionResult;
99:                                 }))
100:                 .thenApply(
101:                         result ->
102:                                 new MiniClusterJobClient(
103:                                         result.getJobID(),
104:                                         miniCluster,
105:                                         userCodeClassloader,
106:                                         MiniClusterJobClient.JobFinalizationBehavior
107:                                                 .SHUTDOWN_CLUSTER))
108:                 .whenComplete(
109:                         (ignored, throwable) -> {
110:                             if (throwable != null) {
111:                                 // We failed to create the JobClient and must shutdown to ensure
112:                                 // cleanup.
113:                                 shutDownCluster(miniCluster);
114:                             }
115:                         })
116:                 .thenApply(Function.identity());
117:     }
118: 
119:     private MiniClusterConfiguration getMiniClusterConfig(int maximumParallelism) {
120:         Configuration configuration = new Configuration(this.configuration);
121: 
122:         if (!configuration.contains(RestOptions.BIND_PORT)) {
123:             configuration.set(RestOptions.BIND_PORT, "0");
124:         }
125: 
126:         int numTaskManagers = configuration.get(TaskManagerOptions.MINI_CLUSTER_NUM_TASK_MANAGERS);
127: 
128:         Map<String, String> overwriteParallelisms =
129:                 configuration.get(PipelineOptions.PARALLELISM_OVERRIDES);
130:         if (overwriteParallelisms != null) {
131:             for (String overrideParallelism : overwriteParallelisms.values()) {
132:                 maximumParallelism =
133:                         Math.max(maximumParallelism, Integer.parseInt(overrideParallelism));
134:             }
135:         }
136: 
137:         int finalMaximumParallelism = maximumParallelism;
138:         int numSlotsPerTaskManager =
139:                 configuration
140:                         .getOptional(TaskManagerOptions.NUM_TASK_SLOTS)
141:                         .orElseGet(
142:                                 () ->
143:                                         finalMaximumParallelism > 0
144:                                                 ? MathUtils.divideRoundUp(
145:                                                         finalMaximumParallelism, numTaskManagers)
146:                                                 : TaskManagerOptions.NUM_TASK_SLOTS.defaultValue());
147: 
148:         return new MiniClusterConfiguration.Builder()
149:                 .setConfiguration(configuration)
150:                 .setNumTaskManagers(numTaskManagers)
151:                 .setRpcServiceSharing(RpcServiceSharing.SHARED)
152:                 .setNumSlotsPerTaskManager(numSlotsPerTaskManager)
153:                 .build();
154:     }
155: 
156:     private static void shutDownCluster(MiniCluster miniCluster) {
157:         miniCluster
158:                 .closeAsync()
159:                 .whenComplete(
160:                         (ignored, throwable) -> {
161:                             if (throwable != null) {
162:                                 LOG.warn("Shutdown of MiniCluster failed.", throwable);
163:                             }
164:                         });
165:     }
166: }
