161:     static OperatorStateHandle generatePartitionableStateHandle(
162:             Map<String, List<? extends Serializable>> states) throws IOException {
163: 
164:         List<List<? extends Serializable>> namedStateSerializables = new ArrayList<>(states.size());
165: 
166:         for (Map.Entry<String, List<? extends Serializable>> entry : states.entrySet()) {
167:             namedStateSerializables.add(entry.getValue());
168:         }
169: 
170:         Tuple2<byte[], List<long[]>> serializationWithOffsets =
171:                 serializeTogetherAndTrackOffsets(namedStateSerializables);
172: 
173:         Map<String, OperatorStateHandle.StateMetaInfo> offsetsMap = new HashMap<>(states.size());
174: 
175:         int idx = 0;
176:         for (Map.Entry<String, List<? extends Serializable>> entry : states.entrySet()) {
177:             offsetsMap.put(
178:                     entry.getKey(),
179:                     new OperatorStateHandle.StateMetaInfo(
180:                             serializationWithOffsets.f1.get(idx),
181:                             OperatorStateHandle.Mode.SPLIT_DISTRIBUTE));
182:             ++idx;
183:         }
184: 
185:         return new OperatorStreamStateHandle(
186:                 offsetsMap, generateByteStreamStateHandle(serializationWithOffsets.f0));
187:     }
