193:     static Tuple2<byte[], List<long[]>> serializeTogetherAndTrackOffsets(
194:             List<List<? extends Serializable>> serializables) throws IOException {
195: 
196:         List<long[]> offsets = new ArrayList<>(serializables.size());
197:         List<byte[]> serializedGroupValues = new ArrayList<>();
198: 
199:         int runningGroupsOffset = 0;
200:         for (List<? extends Serializable> list : serializables) {
201: 
202:             long[] currentOffsets = new long[list.size()];
203:             offsets.add(currentOffsets);
204: 
205:             for (int i = 0; i < list.size(); ++i) {
206:                 currentOffsets[i] = runningGroupsOffset;
207:                 byte[] serializedValue = InstantiationUtil.serializeObject(list.get(i));
208:                 serializedGroupValues.add(serializedValue);
209:                 runningGroupsOffset += serializedValue.length;
210:             }
211:         }
212: 
213:         // write all generated values in a single byte array, which is index by
214:         // groupOffsetsInFinalByteArray
215:         byte[] allSerializedValuesConcatenated = new byte[runningGroupsOffset];
216:         runningGroupsOffset = 0;
217:         for (byte[] serializedGroupValue : serializedGroupValues) {
218:             System.arraycopy(
219:                     serializedGroupValue,
220:                     0,
221:                     allSerializedValuesConcatenated,
222:                     runningGroupsOffset,
223:                     serializedGroupValue.length);
224:             runningGroupsOffset += serializedGroupValue.length;
225:         }
226:         return new Tuple2<>(allSerializedValuesConcatenated, offsets);
227:     }
