296:         try (FSDataInputStream inputStream = expectedHeadOpKeyGroupStateHandle.openInputStream()) {
297:             for (int groupId : expectedHeadOpKeyGroupStateHandle.getKeyGroupRange()) {
298:                 long offset = expectedHeadOpKeyGroupStateHandle.getOffsetForKeyGroup(groupId);
