300:                 int expectedKeyGroupState =
301:                         InstantiationUtil.deserializeObject(
302:                                 inputStream, Thread.currentThread().getContextClassLoader());
303:                 for (KeyedStateHandle oneActualKeyedStateHandle : actualPartitionedKeyGroupState) {
304: 
305:                     assertTrue(oneActualKeyedStateHandle instanceof KeyGroupsStateHandle);
306: 
307:                     KeyGroupsStateHandle oneActualKeyGroupStateHandle =
308:                             (KeyGroupsStateHandle) oneActualKeyedStateHandle;
309:                     if (oneActualKeyGroupStateHandle.getKeyGroupRange().contains(groupId)) {
310:                         long actualOffset =
311:                                 oneActualKeyGroupStateHandle.getOffsetForKeyGroup(groupId);
312:                         try (FSDataInputStream actualInputStream =
313:                                 oneActualKeyGroupStateHandle.openInputStream()) {
314:                             actualInputStream.seek(actualOffset);
315:                             int actualGroupState =
316:                                     InstantiationUtil.deserializeObject(
317:                                             actualInputStream,
318:                                             Thread.currentThread().getContextClassLoader());
319:                             assertEquals(expectedKeyGroupState, actualGroupState);
320:                         }
321:                     }
322:                 }
323:             }
324:         }
325:     }
