343:     void testKeyGroupedInternalPriorityQueue(boolean addAll) throws Exception {
344:         String fieldName = "key-grouped-priority-queue";
345:         CheckpointableKeyedStateBackend<Integer> backend =
346:                 createKeyedBackend(IntSerializer.INSTANCE);
347:         try {
348:             KeyGroupedInternalPriorityQueue<TestType> priorityQueue =
349:                     backend.create(fieldName, new TestType.V1TestTypeSerializer());
350: 
351:             TestType elementA42 = new TestType("a", 42);
352:             TestType elementA44 = new TestType("a", 44);
353:             TestType elementB1 = new TestType("b", 1);
354:             TestType elementB3 = new TestType("b", 3);
355: 
356:             TestType[] elements = {
357:                 elementA44, elementB1, elementB1, elementB3, elementA42,
358:             };
359: 
360:             if (addAll) {
361:                 priorityQueue.addAll(asList(elements));
362:             } else {
363:                 assertThat(priorityQueue.add(elements[0])).isTrue();
364:                 assertThat(priorityQueue.add(elements[1])).isTrue();
365:                 assertThat(priorityQueue.add(elements[2])).isFalse();
366:                 assertThat(priorityQueue.add(elements[3])).isFalse();
367:                 assertThat(priorityQueue.add(elements[4])).isFalse();
368:             }
369:             assertThat(priorityQueue.isEmpty()).isFalse();
370:             assertThat(priorityQueue.getSubsetForKeyGroup(1))
371:                     .containsExactlyInAnyOrder(elementA42, elementA44);
372:             assertThat(priorityQueue.getSubsetForKeyGroup(8))
373:                     .containsExactlyInAnyOrder(elementB1, elementB3);
374: 
375:             assertThat(priorityQueue.peek()).isEqualTo(elementB1);
376:             assertThat(priorityQueue.poll()).isEqualTo(elementB1);
377:             assertThat(priorityQueue.peek()).isEqualTo(elementB3);
378: 
379:             List<TestType> actualList = new ArrayList<>();
380:             try (CloseableIterator<TestType> iterator = priorityQueue.iterator()) {
381:                 iterator.forEachRemaining(actualList::add);
382:             }
383: 
384:             assertThat(actualList).containsExactlyInAnyOrder(elementB3, elementA42, elementA44);
385: 
386:             assertThat(priorityQueue.size()).isEqualTo(3);
387: 
388:             assertThat(priorityQueue.remove(elementB1)).isFalse();
389:             assertThat(priorityQueue.remove(elementB3)).isTrue();
390:             assertThat(priorityQueue.peek()).isEqualTo(elementA42);
391:         } finally {
392:             IOUtils.closeQuietly(backend);
393:             backend.dispose();
394:         }
395:     }
