1594:     /**
1595:      * Tests {@link ValueState#value()} and {@link InternalKvState#getSerializedValue(byte[],
1596:      * TypeSerializer, TypeSerializer, TypeSerializer)} accessing the state concurrently. They
1597:      * should not get in the way of each other.
1598:      */
1599:     @TestTemplate
1600:     @SuppressWarnings("unchecked")
1601:     void testValueStateRace() throws Exception {
1602:         final Integer namespace = 1;
1603: 
1604:         final ValueStateDescriptor<String> kvId = new ValueStateDescriptor<>("id", String.class);
1605: 
1606:         final TypeSerializer<Integer> keySerializer = IntSerializer.INSTANCE;
1607:         final TypeSerializer<Integer> namespaceSerializer = IntSerializer.INSTANCE;
1608: 
1609:         final CheckpointableKeyedStateBackend<Integer> backend =
1610:                 createKeyedBackend(IntSerializer.INSTANCE);
1611:         try {
1612:             final ValueState<String> state =
1613:                     backend.getPartitionedState(namespace, IntSerializer.INSTANCE, kvId);
1614: 
1615:             // this is only available after the backend initialized the serializer
1616:             final TypeSerializer<String> valueSerializer = kvId.getSerializer();
1617: 
1618:             @SuppressWarnings("unchecked")
1619:             final InternalKvState<Integer, Integer, String> kvState =
1620:                     (InternalKvState<Integer, Integer, String>) state;
1621: 
1622:             /**
1623:              * 1) Test that ValueState#value() before and after KvState#getSerializedValue(byte[])
1624:              * return the same value.
1625:              */
1626: 
1627:             // set some key and namespace
1628:             final int key1 = 1;
1629:             backend.setCurrentKey(key1);
1630:             kvState.setCurrentNamespace(2);
1631:             state.update("2");
1632:             assertThat(state.value()).isEqualTo("2");
1633: 
1634:             // query another key and namespace
1635:             assertThat(
1636:                             getSerializedValue(
1637:                                     kvState,
1638:                                     3,
1639:                                     keySerializer,
1640:                                     namespace,
1641:                                     IntSerializer.INSTANCE,
1642:                                     valueSerializer))
1643:                     .isNull();
1644: 
1645:             // the state should not have changed!
1646:             assertThat(state.value()).isEqualTo("2");
1647: 
1648:             // re-set values
1649:             kvState.setCurrentNamespace(namespace);
1650: 
1651:             /**
1652:              * 2) Test two threads concurrently using ValueState#value() and
1653:              * KvState#getSerializedValue(byte[]).
1654:              */
1655: 
1656:             // some modifications to the state
1657:             final int key2 = 10;
1658:             backend.setCurrentKey(key2);
1659:             assertThat(state.value()).isNull();
1660:             assertThat(
1661:                             getSerializedValue(
1662:                                     kvState,
1663:                                     key2,
1664:                                     keySerializer,
1665:                                     namespace,
1666:                                     namespaceSerializer,
1667:                                     valueSerializer))
1668:                     .isNull();
1669:             state.update("1");
1670: 
1671:             final CheckedThread getter =
1672:                     new CheckedThread("State getter") {
1673:                         @Override
1674:                         public void go() throws Exception {
1675:                             while (!isInterrupted()) {
1676:                                 assertThat(state.value()).isEqualTo("1");
1677:                             }
1678:                         }
1679:                     };
1680: 
1681:             final CheckedThread serializedGetter =
1682:                     new CheckedThread("Serialized state getter") {
1683:                         @Override
1684:                         public void go() throws Exception {
1685:                             while (!isInterrupted() && getter.isAlive()) {
1686:                                 final String serializedValue =
1687:                                         getSerializedValue(
1688:                                                 kvState,
1689:                                                 key2,
1690:                                                 keySerializer,
1691:                                                 namespace,
1692:                                                 namespaceSerializer,
1693:                                                 valueSerializer);
1694:                                 assertThat(serializedValue).isEqualTo("1");
1695:                             }
1696:                         }
1697:                     };
1698: 
1699:             getter.start();
1700:             serializedGetter.start();
1701: 
1702:             // run both threads for max 100ms
1703:             Timer t = new Timer("stopper");
1704:             t.schedule(
1705:                     new TimerTask() {
1706:                         @Override
1707:                         public void run() {
1708:                             getter.interrupt();
1709:                             serializedGetter.interrupt();
1710:                             this.cancel();
1711:                         }
1712:                     },
1713:                     100);
1714: 
1715:             // wait for both threads to finish
1716:             // serializedGetter will finish if its assertion fails or if
1717:             // getter is not alive any more
1718:             serializedGetter.sync();
1719:             // if serializedGetter crashed, getter will not know -> interrupt just in case
1720:             getter.interrupt();
1721:             getter.sync();
1722:             t.cancel(); // if not executed yet
1723:         } finally {
1724:             // clean up
1725:             IOUtils.closeQuietly(backend);
1726:             backend.dispose();
1727:         }
1728:     }
