3956:     private void testKeyGroupSnapshotRestore(
3957:             int sourceParallelism, int targetParallelism, int maxParallelism) throws Exception {
3958:         checkArgument(
3959:                 sourceParallelism > 0,
3960:                 "parallelism must be positive, current is %s.",
3961:                 sourceParallelism);
3962:         checkArgument(
3963:                 targetParallelism > 0,
3964:                 "parallelism must be positive, current is %s.",
3965:                 targetParallelism);
3966:         checkArgument(
3967:                 sourceParallelism <= maxParallelism,
3968:                 "Maximum parallelism must not be smaller than parallelism.");
