4687:     /**
4688:      * The purpose of this test is to check that parallel snapshots are possible, and work even if a
4689:      * previous snapshot is still running and blocking.
4690:      */
4691:     @TestTemplate
4692:     void testParallelAsyncSnapshots() throws Exception {
4693:         assumeThat(snapshotUsesStreamFactory()).isTrue();
4694:         OneShotLatch blocker = new OneShotLatch();
4695:         OneShotLatch waiter = new OneShotLatch();
4696:         BlockerCheckpointStreamFactory streamFactory =
4697:                 new BlockerCheckpointStreamFactory(1024 * 1024);
4698:         streamFactory.setWaiterLatch(waiter);
4699:         streamFactory.setBlockerLatch(blocker);
4700:         streamFactory.setAfterNumberInvocations(10);
4701: 
4702:         final CheckpointableKeyedStateBackend<Integer> backend =
4703:                 createKeyedBackend(IntSerializer.INSTANCE);
4704: 
4705:         try {
4706: 
4707:             if (!supportsAsynchronousSnapshots()) {
4708:                 return;
4709:             }
4710: 
4711:             // insert some data to the backend.
4712:             InternalValueState<Integer, VoidNamespace, Integer> valueState =
4713:                     backend.createOrUpdateInternalState(
4714:                             VoidNamespaceSerializer.INSTANCE,
4715:                             new ValueStateDescriptor<>("test", IntSerializer.INSTANCE));
4716: 
4717:             valueState.setCurrentNamespace(VoidNamespace.INSTANCE);
4718: 
4719:             for (int i = 0; i < 10; ++i) {
4720:                 backend.setCurrentKey(i);
4721:                 valueState.update(i);
4722:             }
4723: 
4724:             RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshot1 =
4725:                     backend.snapshot(
4726:                             0L,
4727:                             0L,
4728:                             streamFactory,
4729:                             CheckpointOptions.forCheckpointWithDefaultLocation());
4730: 
4731:             Thread runner1 = new Thread(snapshot1, "snapshot-1-runner");
4732:             runner1.start();
4733:             // after this call returns, we have a running snapshot-1 that is blocked in IO.
4734:             waiter.await();
4735: 
4736:             // do some updates in between the snapshots.
4737:             for (int i = 5; i < 15; ++i) {
4738:                 backend.setCurrentKey(i);
4739:                 valueState.update(i + 1);
4740:             }
4741: 
4742:             // we don't want to block the second snapshot.
4743:             streamFactory.setWaiterLatch(null);
4744:             streamFactory.setBlockerLatch(null);
4745: 
4746:             RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshot2 =
4747:                     backend.snapshot(
4748:                             1L,
4749:                             1L,
4750:                             streamFactory,
4751:                             CheckpointOptions.forCheckpointWithDefaultLocation());
4752: 
4753:             Thread runner2 = new Thread(snapshot2, "snapshot-2-runner");
4754:             runner2.start();
4755:             // snapshot-2 should run and succeed, while snapshot-1 is still running and blocked in
4756:             // IO.
4757:             snapshot2.get();
4758: 
4759:             // we release the blocking IO so that snapshot-1 can also finish and succeed.
4760:             blocker.trigger();
4761:             snapshot1.get();
4762: 
4763:         } finally {
4764:             IOUtils.closeQuietly(backend);
4765:             backend.dispose();
4766:         }
4767:     }
