188:     /**
189:      * Executions the run action.
190:      *
191:      * @param args Command line arguments for the run action.
192:      */
193:     protected void run(String[] args) throws Exception {
194:         LOG.info("Running 'run' command.");
195: 
196:         final Options commandOptions = CliFrontendParser.getRunCommandOptions();
197:         final CommandLine commandLine = getCommandLine(commandOptions, args, true);
198: 
199:         // evaluate help flag
200:         if (commandLine.hasOption(HELP_OPTION.getOpt())) {
201:             CliFrontendParser.printHelpForRun(customCommandLines);
202:             return;
203:         }
204: 
205:         final CustomCommandLine activeCommandLine =
206:                 validateAndGetActiveCommandLine(checkNotNull(commandLine));
207: 
208:         if (isDeploymentTargetApplication(activeCommandLine, commandLine)) {
209:             final ApplicationDeployer deployer =
210:                     new ApplicationClusterDeployer(clusterClientServiceLoader);
211: 
212:             final ProgramOptions programOptions;
213:             final Configuration effectiveConfiguration;
214: 
215:             // No need to set a jarFile path for PyFlink job.
216:             if (ProgramOptionsUtils.isPythonEntryPoint(commandLine)) {
217:                 programOptions = ProgramOptionsUtils.createPythonProgramOptions(commandLine);
218:                 effectiveConfiguration =
219:                         getEffectiveConfiguration(
220:                                 activeCommandLine,
221:                                 commandLine,
222:                                 programOptions,
223:                                 Collections.emptyList());
224:             } else {
225:                 programOptions = new ProgramOptions(commandLine);
226:                 programOptions.validate();
227:                 final URI uri = PackagedProgramUtils.resolveURI(programOptions.getJarFilePath());
228:                 effectiveConfiguration =
229:                         getEffectiveConfiguration(
230:                                 activeCommandLine,
231:                                 commandLine,
232:                                 programOptions,
233:                                 Collections.singletonList(uri.toString()));
234:             }
235: 
236:             final ApplicationConfiguration applicationConfiguration =
237:                     new ApplicationConfiguration(
238:                             programOptions.getProgramArgs(),
239:                             programOptions.getEntryPointClassName());
240:             deployer.run(effectiveConfiguration, applicationConfiguration);
241:         } else {
242:             final ProgramOptions programOptions = ProgramOptions.create(commandLine);
243: 
244:             final List<URL> jobJars = getJobJarAndDependencies(programOptions);
245: 
246:             final Configuration effectiveConfiguration =
247:                     getEffectiveConfiguration(
248:                             activeCommandLine, commandLine, programOptions, jobJars);
249: 
250:             LOG.debug("Effective executor configuration: {}", effectiveConfiguration);
251: 
252:             try (PackagedProgram program =
253:                     getPackagedProgram(programOptions, effectiveConfiguration)) {
254:                 executeProgram(effectiveConfiguration, program);
255:             }
256:         }
257:     }
258: 
259:     protected boolean isDeploymentTargetApplication(
260:             final CustomCommandLine activeCustomCommandLine, final CommandLine commandLine)
261:             throws FlinkException {
262:         final Configuration effectiveConfiguration =
263:                 getEffectiveConfiguration(activeCustomCommandLine, commandLine);
264: 
265:         final String executionTarget =
266:                 effectiveConfiguration
267:                         .getOptional(DeploymentOptions.TARGET)
268:                         .orElseThrow(
269:                                 () ->
270:                                         new IllegalArgumentException(
271:                                                 String.format(
272:                                                         "Config '%s' has to be set.",
273:                                                         DeploymentOptions.TARGET.key())));
274: 
275:         return executionTarget.trim().endsWith("application");
276:     }
