278:     /** Get all provided libraries needed to run the program from the ProgramOptions. */
279:     private List<URL> getJobJarAndDependencies(ProgramOptions programOptions)
280:             throws CliArgsException {
281:         String entryPointClass = programOptions.getEntryPointClassName();
282:         String jarFilePath = programOptions.getJarFilePath();
283: 
284:         try {
285:             File jarFile = jarFilePath != null ? getJarFile(jarFilePath) : null;
286:             return PackagedProgram.getJobJarAndDependencies(jarFile, entryPointClass);
287:         } catch (FileNotFoundException | ProgramInvocationException e) {
288:             throw new CliArgsException(
289:                     "Could not get job jar and dependencies from JAR file: " + e.getMessage(), e);
290:         }
291:     }
292: 
293:     private PackagedProgram getPackagedProgram(
294:             ProgramOptions programOptions, Configuration effectiveConfiguration)
295:             throws ProgramInvocationException, CliArgsException {
296:         PackagedProgram program;
297:         try {
298:             LOG.info("Building program from JAR file");
299:             program = buildProgram(programOptions, effectiveConfiguration);
300:         } catch (FileNotFoundException e) {
301:             throw new CliArgsException(
302:                     "Could not build the program from JAR file: " + e.getMessage(), e);
303:         }
304:         return program;
305:     }
