307:     private Configuration getEffectiveConfiguration(
308:             final CustomCommandLine activeCustomCommandLine, final CommandLine commandLine)
309:             throws FlinkException {
310: 
311:         final Configuration effectiveConfiguration = new Configuration(configuration);
312: 
313:         final Configuration commandLineConfiguration =
314:                 checkNotNull(activeCustomCommandLine).toConfiguration(commandLine);
315: 
316:         effectiveConfiguration.addAll(commandLineConfiguration);
317: 
318:         return effectiveConfiguration;
319:     }
