321:     private <T> Configuration getEffectiveConfiguration(
322:             final CustomCommandLine activeCustomCommandLine,
323:             final CommandLine commandLine,
324:             final ProgramOptions programOptions,
325:             final List<T> jobJars)
326:             throws FlinkException {
327: 
328:         final Configuration effectiveConfiguration =
329:                 getEffectiveConfiguration(activeCustomCommandLine, commandLine);
330: 
331:         final ExecutionConfigAccessor executionParameters =
332:                 ExecutionConfigAccessor.fromProgramOptions(
333:                         checkNotNull(programOptions), checkNotNull(jobJars));
334: 
335:         executionParameters.applyToConfiguration(effectiveConfiguration);
336: 
337:         LOG.debug(
338:                 "Effective configuration after Flink conf, custom commandline, and program options: {}",
339:                 effectiveConfiguration);
340:         return effectiveConfiguration;
341:     }
