358:         if (commandLine.hasOption(HELP_OPTION.getOpt())) {
359:             CliFrontendParser.printHelpForInfo();
360:             return;
361:         }
362: 
363:         // -------- build the packaged program -------------
364: 
365:         LOG.info("Building program from JAR file");
366: 
367:         PackagedProgram program = null;
368: 
369:         try {
370:             LOG.info("Creating program plan dump");
