382:             program = buildProgram(programOptions, effectiveConfiguration);
383: 
384:             int parallelism = programOptions.getParallelism();
385:             if (ExecutionConfig.PARALLELISM_DEFAULT == parallelism) {
386:                 parallelism = getDefaultParallelism(effectiveConfiguration);
387:             }
