464:     private <ClusterID> void listJobs(
465:             ClusterClient<ClusterID> clusterClient,
466:             boolean showRunning,
467:             boolean showScheduled,
468:             boolean showAll)
469:             throws FlinkException {
470:         Collection<JobStatusMessage> jobDetails;
471:         try {
472:             CompletableFuture<Collection<JobStatusMessage>> jobDetailsFuture =
473:                     clusterClient.listJobs();
474: 
475:             logAndSysout("Waiting for response...");
476:             jobDetails = jobDetailsFuture.get();
477: 
478:         } catch (Exception e) {
479:             Throwable cause = ExceptionUtils.stripExecutionException(e);
480:             throw new FlinkException("Failed to retrieve job list.", cause);
481:         }
482: 
483:         LOG.info("Successfully retrieved list of jobs");
484: 
485:         final List<JobStatusMessage> runningJobs = new ArrayList<>();
486:         final List<JobStatusMessage> scheduledJobs = new ArrayList<>();
487:         final List<JobStatusMessage> terminatedJobs = new ArrayList<>();
488:         jobDetails.forEach(
489:                 details -> {
490:                     if (details.getJobState() == JobStatus.CREATED
491:                             || details.getJobState() == JobStatus.INITIALIZING) {
492:                         scheduledJobs.add(details);
493:                     } else if (!details.getJobState().isGloballyTerminalState()) {
494:                         runningJobs.add(details);
495:                     } else {
496:                         terminatedJobs.add(details);
497:                     }
498:                 });
499: 
500:         if (showRunning || showAll) {
501:             if (runningJobs.size() == 0) {
502:                 System.out.println("No running jobs.");
503:             } else {
504:                 System.out.println(
505:                         "------------------ Running/Restarting Jobs -------------------");
506:                 printJobStatusMessages(runningJobs);
507:                 System.out.println(
508:                         "--------------------------------------------------------------");
509:             }
510:         }
511:         if (showScheduled || showAll) {
512:             if (scheduledJobs.size() == 0) {
513:                 System.out.println("No scheduled jobs.");
514:             } else {
515:                 System.out.println(
516:                         "----------------------- Scheduled Jobs -----------------------");
517:                 printJobStatusMessages(scheduledJobs);
518:                 System.out.println(
519:                         "--------------------------------------------------------------");
520:             }
521:         }
522:         if (showAll) {
523:             if (terminatedJobs.size() != 0) {
524:                 System.out.println(
525:                         "---------------------- Terminated Jobs -----------------------");
526:                 printJobStatusMessages(terminatedJobs);
527:                 System.out.println(
528:                         "--------------------------------------------------------------");
529:             }
530:         }
531:     }
532: 
533:     private static void printJobStatusMessages(List<JobStatusMessage> jobs) {
534:         SimpleDateFormat dateFormat = new SimpleDateFormat("dd.MM.yyyy HH:mm:ss");
535:         sortJobStatusMessages(jobs)
536:                 .forEachOrdered(
537:                         job ->
538:                                 System.out.println(
539:                                         dateFormat.format(new Date(job.getStartTime()))
540:                                                 + " : "
541:                                                 + job.getJobId()
542:                                                 + " : "
543:                                                 + job.getJobName()
544:                                                 + " ("
545:                                                 + job.getJobState()
546:                                                 + ")"));
547:     }
548: 
549:     @VisibleForTesting
550:     static Stream<JobStatusMessage> sortJobStatusMessages(List<JobStatusMessage> jobs) {
551:         Comparator<Map.Entry<JobStatus, List<JobStatusMessage>>> statusComparator =
552:                 (o1, o2) ->
553:                         String.CASE_INSENSITIVE_ORDER.compare(
554:                                 o1.getKey().toString(), o2.getKey().toString());
555: 
556:         Map<JobStatus, List<JobStatusMessage>> jobsByState =
557:                 jobs.stream().collect(Collectors.groupingBy(JobStatusMessage::getJobState));
558:         return jobsByState.entrySet().stream()
559:                 .sorted(statusComparator)
560:                 .map(Map.Entry::getValue)
561:                 .flatMap(List::stream)
562:                 .sorted(Comparator.comparing(JobStatusMessage::getStartTime));
563:     }
