565:     /**
566:      * Executes the STOP action.
567:      *
568:      * @param args Command line arguments for the stop action.
569:      */
570:     protected void stop(String[] args) throws Exception {
571:         LOG.info("Running 'stop-with-savepoint' command.");
572: 
573:         final Options commandOptions = CliFrontendParser.getStopCommandOptions();
574:         final CommandLine commandLine = getCommandLine(commandOptions, args, false);
575: 
576:         final StopOptions stopOptions = new StopOptions(commandLine);
577:         if (stopOptions.isPrintHelp()) {
578:             CliFrontendParser.printHelpForStop(customCommandLines);
579:             return;
580:         }
581: 
582:         final String[] cleanedArgs = stopOptions.getArgs();
583: 
584:         final String targetDirectory =
585:                 stopOptions.hasSavepointFlag() && cleanedArgs.length > 0
586:                         ? stopOptions.getTargetDirectory()
587:                         : null; // the default savepoint location is going to be used in this case.
588: 
589:         final JobID jobId =
590:                 cleanedArgs.length != 0
591:                         ? parseJobId(cleanedArgs[0])
592:                         : parseJobId(stopOptions.getTargetDirectory());
593: 
594:         final boolean advanceToEndOfEventTime = stopOptions.shouldAdvanceToEndOfEventTime();
595: 
596:         final SavepointFormatType formatType = stopOptions.getFormatType();
597:         logAndSysout(
598:                 (advanceToEndOfEventTime ? "Draining job " : "Suspending job ")
599:                         + "\""
600:                         + jobId
601:                         + "\" with a "
602:                         + formatType
603:                         + " savepoint.");
604: 
605:         final CustomCommandLine activeCommandLine = validateAndGetActiveCommandLine(commandLine);
606: 
607:         runClusterAction(
608:                 activeCommandLine,
609:                 commandLine,
610:                 (clusterClient, effectiveConfiguration) -> {
611:                     // Trigger savepoint in detached mode
612:                     if (stopOptions.isDetached()) {
613:                         // trigger stop-with-savepoint in detached mode and
614:                         // return the trigger id immediately
615:                         stopWithDetachedSavepoint(
616:                                 clusterClient,
617:                                 jobId,
618:                                 advanceToEndOfEventTime,
619:                                 targetDirectory,
620:                                 formatType,
621:                                 getClientTimeout(effectiveConfiguration));
622:                     } else {
623:                         stopWithSavepoint(
624:                                 clusterClient,
625:                                 jobId,
626:                                 advanceToEndOfEventTime,
627:                                 targetDirectory,
628:                                 formatType,
629:                                 getClientTimeout(effectiveConfiguration));
630:                     }
631:                 });
632:     }
