634:     /**
635:      * Executes the CANCEL action.
636:      *
637:      * @param args Command line arguments for the cancel action.
638:      */
639:     protected void cancel(String[] args) throws Exception {
640:         LOG.info("Running 'cancel' command.");
641: 
642:         final Options commandOptions = CliFrontendParser.getCancelCommandOptions();
643:         final CommandLine commandLine = getCommandLine(commandOptions, args, false);
644: 
645:         CancelOptions cancelOptions = new CancelOptions(commandLine);
646: 
647:         // evaluate help flag
648:         if (cancelOptions.isPrintHelp()) {
649:             CliFrontendParser.printHelpForCancel(customCommandLines);
650:             return;
651:         }
652: 
653:         final CustomCommandLine activeCommandLine = validateAndGetActiveCommandLine(commandLine);
654: 
655:         final String[] cleanedArgs = cancelOptions.getArgs();
656: 
657:         if (cancelOptions.isWithSavepoint()) {
658: 
659:             logAndSysout(
660:                     "DEPRECATION WARNING: Cancelling a job with savepoint is deprecated. Use \"stop\" instead.");
661: 
662:             final JobID jobId;
663:             final String targetDirectory;
664: 
665:             if (cleanedArgs.length > 0) {
666:                 jobId = parseJobId(cleanedArgs[0]);
667:                 targetDirectory = cancelOptions.getSavepointTargetDirectory();
668:             } else {
669:                 jobId = parseJobId(cancelOptions.getSavepointTargetDirectory());
670:                 targetDirectory = null;
671:             }
672: 
673:             final SavepointFormatType formatType = cancelOptions.getFormatType();
674:             if (targetDirectory == null) {
675:                 logAndSysout(
676:                         "Cancelling job "
677:                                 + jobId
678:                                 + " with "
679:                                 + formatType
680:                                 + " savepoint to default savepoint directory.");
681:             } else {
682:                 logAndSysout(
683:                         "Cancelling job "
684:                                 + jobId
685:                                 + " with "
686:                                 + formatType
687:                                 + " savepoint to "
688:                                 + targetDirectory
689:                                 + '.');
690:             }
691: 
692:             runClusterAction(
693:                     activeCommandLine,
694:                     commandLine,
695:                     (clusterClient, effectiveConfiguration) -> {
696:                         final String savepointPath;
697:                         try {
698:                             savepointPath =
699:                                     clusterClient
700:                                             .cancelWithSavepoint(jobId, targetDirectory, formatType)
701:                                             .get(
702:                                                     getClientTimeout(effectiveConfiguration)
703:                                                             .toMillis(),
704:                                                     TimeUnit.MILLISECONDS);
705:                         } catch (Exception e) {
706:                             throw new FlinkException("Could not cancel job " + jobId + '.', e);
707:                         }
708:                         logAndSysout(
709:                                 "Cancelled job "
710:                                         + jobId
711:                                         + ". Savepoint stored in "
712:                                         + savepointPath
713:                                         + '.');
714:                     });
715:         } else {
716:             final JobID jobId;
717: 
718:             if (cleanedArgs.length > 0) {
719:                 jobId = parseJobId(cleanedArgs[0]);
720:             } else {
721:                 throw new CliArgsException("Missing JobID. Specify a JobID to cancel a job.");
722:             }
723: 
724:             logAndSysout("Cancelling job " + jobId + '.');
725: 
726:             runClusterAction(
727:                     activeCommandLine,
728:                     commandLine,
729:                     (clusterClient, effectiveConfiguration) -> {
730:                         try {
731:                             clusterClient
732:                                     .cancel(jobId)
733:                                     .get(
734:                                             getClientTimeout(effectiveConfiguration).toMillis(),
735:                                             TimeUnit.MILLISECONDS);
736:                         } catch (Exception e) {
737:                             throw new FlinkException("Could not cancel job " + jobId + '.', e);
738:                         }
739:                     });
740: 
741:             logAndSysout("Cancelled job " + jobId + '.');
742:         }
743:     }
