753:     /**
754:      * Executes the SAVEPOINT action.
755:      *
756:      * @param args Command line arguments for the savepoint action.
757:      */
758:     protected void savepoint(String[] args) throws Exception {
759:         LOG.info("Running 'savepoint' command.");
760: 
761:         final Options commandOptions = CliFrontendParser.getSavepointCommandOptions();
762: 
763:         final CommandLine commandLine = getCommandLine(commandOptions, args, false);
764: 
765:         final SavepointOptions savepointOptions = new SavepointOptions(commandLine);
766: 
767:         // evaluate help flag
768:         if (savepointOptions.isPrintHelp()) {
769:             CliFrontendParser.printHelpForSavepoint(customCommandLines);
770:             return;
771:         }
772: 
773:         final CustomCommandLine activeCommandLine = validateAndGetActiveCommandLine(commandLine);
774: 
775:         if (savepointOptions.isDispose()) {
776:             runClusterAction(
777:                     activeCommandLine,
778:                     commandLine,
779:                     (clusterClient, effectiveConfiguration) ->
780:                             disposeSavepoint(
781:                                     clusterClient,
782:                                     savepointOptions.getSavepointPath(),
783:                                     getClientTimeout(effectiveConfiguration)));
784:         } else {
785:             String[] cleanedArgs = savepointOptions.getArgs();
786: 
787:             final JobID jobId;
788: 
789:             if (cleanedArgs.length >= 1) {
790:                 String jobIdString = cleanedArgs[0];
791: 
792:                 jobId = parseJobId(jobIdString);
793:             } else {
794:                 throw new CliArgsException(
795:                         "Missing JobID. " + "Specify a Job ID to trigger a savepoint.");
796:             }
797: 
798:             final String savepointDirectory;
799:             if (cleanedArgs.length >= 2) {
800:                 savepointDirectory = cleanedArgs[1];
801:             } else {
802:                 savepointDirectory = null;
803:             }
804: 
805:             // Print superfluous arguments
806:             if (cleanedArgs.length >= 3) {
807:                 logAndSysout(
808:                         "Provided more arguments than required. Ignoring not needed arguments.");
809:             }
810: 
811:             runClusterAction(
812:                     activeCommandLine,
813:                     commandLine,
814:                     (clusterClient, effectiveConfiguration) -> {
815:                         // Trigger savepoint in detached mode
816:                         if (savepointOptions.isDetached()) {
817:                             // trigger savepoint in detached mode and
818:                             // return the trigger id immediately
819:                             triggerDetachedSavepoint(
820:                                     clusterClient,
821:                                     jobId,
822:                                     savepointDirectory,
823:                                     savepointOptions.getFormatType(),
824:                                     getClientTimeout(effectiveConfiguration));
825:                         } else {
826:                             triggerSavepoint(
827:                                     clusterClient,
828:                                     jobId,
829:                                     savepointDirectory,
830:                                     savepointOptions.getFormatType(),
831:                                     getClientTimeout(effectiveConfiguration));
832:                         }
833:                     });
834:         }
835:     }
