971:     protected void checkpoint(String[] args) throws Exception {
972:         LOG.info("Running 'checkpoint' command.");
973: 
974:         final Options commandOptions = CliFrontendParser.getCheckpointCommandOptions();
975: 
976:         final CommandLine commandLine = getCommandLine(commandOptions, args, false);
977: 
978:         final CheckpointOptions checkpointOptions = new CheckpointOptions(commandLine);
