1001:                 activeCommandLine,
1002:                 commandLine,
1003:                 (clusterClient, effectiveConfiguration) ->
1004:                         triggerCheckpoint(
1005:                                 clusterClient,
1006:                                 jobId,
1007:                                 checkpointOptions.getCheckpointType(),
1008:                                 getClientTimeout(effectiveConfiguration)));
