1071:      * @return A PackagedProgram (upon success)
1072:      */
1073:     PackagedProgram buildProgram(final ProgramOptions runOptions, final Configuration configuration)
1074:             throws FileNotFoundException, ProgramInvocationException, CliArgsException {
1075:         runOptions.validate();
1076: 
1077:         String[] programArgs = runOptions.getProgramArgs();
1078:         String jarFilePath = runOptions.getJarFilePath();
1079:         List<URL> classpaths = runOptions.getClasspaths();
1080: 
1081:         // Get assembler class
1082:         String entryPointClass = runOptions.getEntryPointClassName();
1083:         File jarFile = jarFilePath != null ? getJarFile(jarFilePath) : null;
1084: 
1085:         return PackagedProgram.newBuilder()
1086:                 .setJarFile(jarFile)
1087:                 .setUserClassPaths(classpaths)
1088:                 .setEntryPointClassName(entryPointClass)
1089:                 .setConfiguration(configuration)
1090:                 .setSavepointRestoreSettings(runOptions.getSavepointRestoreSettings())
1091:                 .setArguments(programArgs)
1092:                 .build();
1093:     }
