1209:     /**
1210:      * Retrieves the {@link ClusterClient} from the given {@link CustomCommandLine} and runs the
1211:      * given {@link ClusterAction} against it.
1212:      *
1213:      * @param activeCommandLine to create the {@link ClusterDescriptor} from
1214:      * @param commandLine containing the parsed command line options
1215:      * @param clusterAction the cluster action to run against the retrieved {@link ClusterClient}.
1216:      * @param <ClusterID> type of the cluster id
1217:      * @throws FlinkException if something goes wrong
1218:      */
1219:     private <ClusterID> void runClusterAction(
1220:             CustomCommandLine activeCommandLine,
1221:             CommandLine commandLine,
1222:             ClusterAction<ClusterID> clusterAction)
1223:             throws FlinkException {
1224:         final Configuration effectiveConfiguration =
1225:                 getEffectiveConfiguration(activeCommandLine, commandLine);
1226:         LOG.debug(
1227:                 "Effective configuration after Flink conf, and custom commandline: {}",
1228:                 effectiveConfiguration);
1229: 
1230:         final ClusterClientFactory<ClusterID> clusterClientFactory =
1231:                 clusterClientServiceLoader.getClusterClientFactory(effectiveConfiguration);
1232: 
1233:         final ClusterID clusterId = clusterClientFactory.getClusterId(effectiveConfiguration);
1234:         if (clusterId == null) {
1235:             throw new FlinkException(
1236:                     "No cluster id was specified. Please specify a cluster to which you would like to connect.");
1237:         }
1238: 
1239:         try (final ClusterDescriptor<ClusterID> clusterDescriptor =
1240:                 clusterClientFactory.createClusterDescriptor(effectiveConfiguration)) {
1241:             try (final ClusterClient<ClusterID> clusterClient =
1242:                     clusterDescriptor.retrieve(clusterId).getClusterClient()) {
1243:                 clusterAction.runAction(clusterClient, effectiveConfiguration);
1244:             }
1245:         }
1246:     }
