1272:     /**
1273:      * Parses the command line arguments and starts the requested action.
1274:      *
1275:      * @param args command line arguments of the client.
1276:      * @return The return code of the program
1277:      */
1278:     public int parseAndRun(String[] args) {
1279: 
1280:         // check for action
1281:         if (args.length < 1) {
1282:             CliFrontendParser.printHelp(customCommandLines);
1283:             System.out.println("Please specify an action.");
1284:             return 1;
1285:         }
1286: 
1287:         // get action
1288:         String action = args[0];
1289: 
1290:         // remove action from parameters
1291:         final String[] params = Arrays.copyOfRange(args, 1, args.length);
1292: 
1293:         try {
1294:             // do action
1295:             switch (action) {
1296:                 case ACTION_RUN:
1297:                     run(params);
1298:                     return 0;
1299:                 case ACTION_RUN_APPLICATION:
1300:                     runApplication(params);
1301:                     return 0;
1302:                 case ACTION_LIST:
1303:                     list(params);
1304:                     return 0;
1305:                 case ACTION_INFO:
1306:                     info(params);
1307:                     return 0;
1308:                 case ACTION_CANCEL:
1309:                     cancel(params);
1310:                     return 0;
1311:                 case ACTION_STOP:
1312:                     stop(params);
1313:                     return 0;
1314:                 case ACTION_SAVEPOINT:
1315:                     savepoint(params);
1316:                     return 0;
1317:                 case ACTION_CHECKPOINT:
1318:                     checkpoint(params);
1319:                     return 0;
1320:                 case "-h":
1321:                 case "--help":
1322:                     CliFrontendParser.printHelp(customCommandLines);
1323:                     return 0;
1324:                 case "-v":
1325:                 case "--version":
1326:                     String version = EnvironmentInformation.getVersion();
1327:                     String commitID = EnvironmentInformation.getRevisionInformation().commitId;
1328:                     System.out.print("Version: " + version);
1329:                     System.out.println(
1330:                             commitID.equals(EnvironmentInformation.UNKNOWN)
1331:                                     ? ""
1332:                                     : ", Commit ID: " + commitID);
1333:                     return 0;
1334:                 default:
1335:                     System.out.printf("\"%s\" is not a valid action.\n", action);
1336:                     System.out.println();
1337:                     System.out.println(
1338:                             "Valid actions are \"run\", \"run-application\" (deprecated), \"list\", \"info\", \"savepoint\", \"stop\", or \"cancel\".");
1339:                     System.out.println();
1340:                     System.out.println(
1341:                             "Specify the version option (-v or --version) to print Flink version.");
1342:                     System.out.println();
1343:                     System.out.println(
1344:                             "Specify the help option (-h or --help) to get help on the command.");
1345:                     return 1;
1346:             }
1347:         } catch (CliArgsException ce) {
1348:             return handleArgException(ce);
1349:         } catch (ProgramParametrizationException ppe) {
1350:             return handleParametrizationException(ppe);
1351:         } catch (ProgramMissingJobException pmje) {
1352:             return handleMissingJobException();
1353:         } catch (Exception e) {
1354:             return handleError(e);
1355:         }
1356:     }
