1369:     static int mainInternal(final String[] args) {
1370:         EnvironmentInformation.logEnvironmentInfo(LOG, "Command Line Client", args);
1371: 
1372:         // 1. find the configuration directory
1373:         final String configurationDirectory = getConfigurationDirectoryFromEnv();
1374: 
1375:         // 2. load the global configuration
1376:         final Configuration configuration =
1377:                 GlobalConfiguration.loadConfiguration(configurationDirectory);
1378: 
1379:         // 3. load the custom command lines
1380:         final List<CustomCommandLine> customCommandLines =
1381:                 loadCustomCommandLines(configuration, configurationDirectory);
1382: 
1383:         int retCode = INITIAL_RET_CODE;
