1389:                             Arrays.copyOfRange(args, min(args.length, 1), args.length),
1390:                             true);
1391:             Configuration securityConfig = new Configuration(cli.configuration);
1392:             DynamicPropertiesUtil.encodeDynamicProperties(commandLine, securityConfig);
1393:             SecurityUtils.install(new SecurityConfiguration(securityConfig));
1394:             retCode = SecurityUtils.getInstalledContext().runSecured(() -> cli.parseAndRun(args));
1395:         } catch (Throwable t) {
1396:             final Throwable strippedThrowable =
1397:                     ExceptionUtils.stripException(t, UndeclaredThrowableException.class);
1398:             LOG.error("Fatal error while running command line interface.", strippedThrowable);
1399:             strippedThrowable.printStackTrace();
