577:     private CompletableFuture<ApplicationStatus> shutDownAsync(
578:             ApplicationStatus applicationStatus,
579:             ShutdownBehaviour shutdownBehaviour,
580:             @Nullable String diagnostics,
581:             boolean cleanupHaData) {
582:         if (isShutDown.compareAndSet(false, true)) {
583:             LOG.info(
584:                     "Shutting {} down with application status {}. Diagnostics {}.",
585:                     getClass().getSimpleName(),
586:                     applicationStatus,
587:                     diagnostics);
588: 
589:             final CompletableFuture<Void> shutDownApplicationFuture =
590:                     closeClusterComponent(applicationStatus, shutdownBehaviour, diagnostics);
591: 
592:             final CompletableFuture<Void> serviceShutdownFuture =
593:                     FutureUtils.composeAfterwards(
594:                             shutDownApplicationFuture, () -> stopClusterServices(cleanupHaData));
595: 
596:             final CompletableFuture<Void> rpcSystemClassLoaderCloseFuture =
597:                     FutureUtils.runAfterwards(serviceShutdownFuture, rpcSystem::close);
598: 
599:             final CompletableFuture<Void> cleanupDirectoriesFuture =
600:                     FutureUtils.runAfterwards(
601:                             rpcSystemClassLoaderCloseFuture,
602:                             () -> cleanupDirectories(shutdownBehaviour));
603: 
604:             cleanupDirectoriesFuture.whenComplete(
605:                     (Void ignored2, Throwable serviceThrowable) -> {
606:                         if (serviceThrowable != null) {
607:                             terminationFuture.completeExceptionally(serviceThrowable);
608:                         } else {
609:                             terminationFuture.complete(applicationStatus);
610:                         }
611:                     });
612:         }
613: 
614:         return terminationFuture;
615:     }
