617:     /**
618:      * Close cluster components and deregister the Flink application from the resource management
619:      * system by signalling the {@link ResourceManager}.
620:      *
621:      * @param applicationStatus to terminate the application with
622:      * @param shutdownBehaviour shutdown behaviour
623:      * @param diagnostics additional information about the shut down, can be {@code null}
624:      * @return Future which is completed once the shut down
625:      */
626:     private CompletableFuture<Void> closeClusterComponent(
627:             ApplicationStatus applicationStatus,
628:             ShutdownBehaviour shutdownBehaviour,
629:             @Nullable String diagnostics) {
630:         synchronized (lock) {
631:             if (clusterComponent != null) {
632:                 switch (shutdownBehaviour) {
633:                     case GRACEFUL_SHUTDOWN:
634:                         return clusterComponent.stopApplication(applicationStatus, diagnostics);
635:                     case PROCESS_FAILURE:
636:                     default:
637:                         return clusterComponent.stopProcess();
638:                 }
639:             } else {
640:                 return CompletableFuture.completedFuture(null);
641:             }
642:         }
643:     }
