645:     /**
646:      * Clean up of temporary directories created by the {@link ClusterEntrypoint}.
647:      *
648:      * @param shutdownBehaviour specifying the shutdown behaviour
649:      * @throws IOException if the temporary directories could not be cleaned up
650:      */
651:     protected void cleanupDirectories(ShutdownBehaviour shutdownBehaviour) throws IOException {
652:         IOException ioException = null;
653: 
654:         final String webTmpDir = configuration.get(WebOptions.TMP_DIR);
655: 
656:         try {
657:             FileUtils.deleteDirectory(new File(webTmpDir));
658:         } catch (IOException ioe) {
659:             ioException = ioe;
660:         }
661: 
662:         synchronized (lock) {
663:             if (workingDirectory != null) {
664:                 // We only clean up the working directory if we gracefully shut down or if its path
665:                 // is nondeterministic. If it is a process failure, then we want to keep the working
666:                 // directory for potential recoveries.
667:                 if (!workingDirectory.isDeterministic()
668:                         || shutdownBehaviour == ShutdownBehaviour.GRACEFUL_SHUTDOWN) {
669:                     try {
670:                         workingDirectory.unwrap().delete();
671:                     } catch (IOException ioe) {
672:                         ioException = ExceptionUtils.firstOrSuppressed(ioe, ioException);
673:                     }
674:                 }
675:             }
676:         }
677: 
678:         if (ioException != null) {
679:             throw ioException;
680:         }
681:     }
