349:     /**
350:      * Get resource requirements from memory and cpu.
351:      *
352:      * @param resourceRequirements resource requirements in pod template
353:      * @param mem Memory in mb.
354:      * @param memoryLimitFactor limit factor for the memory, used to set the limit resources.
355:      * @param cpu cpu.
356:      * @param cpuLimitFactor limit factor for the cpu, used to set the limit resources.
357:      * @param externalResources external resources
358:      * @param externalResourceConfigKeys config keys of external resources
359:      * @return KubernetesResource requirements.
360:      */
361:     public static ResourceRequirements getResourceRequirements(
362:             ResourceRequirements resourceRequirements,
363:             int mem,
364:             double memoryLimitFactor,
365:             double cpu,
366:             double cpuLimitFactor,
367:             Map<String, ExternalResource> externalResources,
368:             Map<String, String> externalResourceConfigKeys) {
369:         final Quantity cpuQuantity = new Quantity(String.valueOf(cpu));
370:         final Quantity cpuLimitQuantity = new Quantity(String.valueOf(cpu * cpuLimitFactor));
371:         final Quantity memQuantity = new Quantity(mem + Constants.RESOURCE_UNIT_MB);
372:         final Quantity memQuantityLimit =
373:                 new Quantity(((int) (mem * memoryLimitFactor)) + Constants.RESOURCE_UNIT_MB);
374: 
375:         ResourceRequirementsBuilder resourceRequirementsBuilder =
376:                 new ResourceRequirementsBuilder(resourceRequirements)
377:                         .addToRequests(Constants.RESOURCE_NAME_MEMORY, memQuantity)
378:                         .addToRequests(Constants.RESOURCE_NAME_CPU, cpuQuantity)
379:                         .addToLimits(Constants.RESOURCE_NAME_MEMORY, memQuantityLimit)
380:                         .addToLimits(Constants.RESOURCE_NAME_CPU, cpuLimitQuantity);
381: 
382:         // Add the external resources to resource requirement.
383:         for (Map.Entry<String, ExternalResource> externalResource : externalResources.entrySet()) {
384:             final String configKey = externalResourceConfigKeys.get(externalResource.getKey());
385:             if (!StringUtils.isNullOrWhitespaceOnly(configKey)) {
386:                 final Quantity resourceQuantity =
387:                         new Quantity(
388:                                 String.valueOf(externalResource.getValue().getValue().longValue()));
389:                 resourceRequirementsBuilder
390:                         .addToRequests(configKey, resourceQuantity)
391:                         .addToLimits(configKey, resourceQuantity);
392:                 LOG.info(
393:                         "Request external resource {} with config key {}.",
394:                         resourceQuantity.getAmount(),
395:                         configKey);
396:             }
397:         }
398: 
399:         return resourceRequirementsBuilder.build();
400:     }
