218:     private static final class IntegerStreamSource extends RichSourceFunction<Integer> {
219: 
220:         private static final long serialVersionUID = 1L;
221:         private static CountDownLatch latch;
222:         private static boolean failedBefore;
223: 
224:         private final int numRecords;
225:         private boolean block;
226:         private volatile boolean running;
227:         private int emittedCount;
228:         private boolean needFailover;
229: 
230:         public IntegerStreamSource(int numRecords, boolean block, boolean needFailover) {
231:             this.numRecords = numRecords;
232:             this.running = true;
233:             this.block = block;
234:             this.needFailover = needFailover;
235:             this.emittedCount = 0;
236:         }
237: 
238:         @Override
239:         public void run(SourceContext<Integer> ctx) throws Exception {
240:             while (running && emittedCount < numRecords) {
241:                 synchronized (ctx.getCheckpointLock()) {
242:                     ctx.collect(emittedCount);
243:                 }
244:                 ++emittedCount;
245:             }
246:             if (block && latch != null) {
247:                 latch.await();
248:             }
249:             if (needFailover && !failedBefore) {
250:                 failedBefore = true;
251:                 throw new RuntimeException("forced failure");
252:             }
253:         }
254: 
255:         @Override
256:         public void cancel() {
257:             running = false;
258:         }
259:     }
