468:         final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
469:         env.setStateBackend(new EmbeddedRocksDBStateBackend(true));
470:         env.getCheckpointConfig()
471:                 .setExternalizedCheckpointRetention(
472:                         ExternalizedCheckpointRetention.RETAIN_ON_CANCELLATION);
473:         env.getCheckpointConfig().setCheckpointStorage(folder.newFolder().toURI());
474:         env.setParallelism(parallelism);
475: 
476:         final SharedReference<CountDownLatch> counter =
477:                 sharedObjects.add(new CountDownLatch(10_000));
478:         env.fromSequence(1, Long.MAX_VALUE)
479:                 .keyBy(i -> i % parallelism)
480:                 .process(
481:                         new KeyedProcessFunction<Long, Long, Long>() {
482:                             private ListState<Long> last;
483: 
484:                             @Override
485:                             public void open(OpenContext openContext) {
486:                                 // we use list state here to create sst files of a significant size
487:                                 // if sst files do not reach certain thresholds they are not stored
488:                                 // in files, but as a byte stream in checkpoints metadata
489:                                 last =
490:                                         getRuntimeContext()
491:                                                 .getListState(
492:                                                         new ListStateDescriptor<>(
493:                                                                 "last",
494:                                                                 BasicTypeInfo.LONG_TYPE_INFO));
495:                             }
496: 
497:                             @Override
498:                             public void processElement(
499:                                     Long value,
500:                                     KeyedProcessFunction<Long, Long, Long>.Context ctx,
501:                                     Collector<Long> out)
502:                                     throws Exception {
503:                                 last.add(value);
504:                                 out.collect(value);
505:                             }
506:                         })
507:                 .addSink(
508:                         new SinkFunction<Long>() {
509:                             @Override
510:                             public void invoke(Long value) {
511:                                 counter.consumeSync(CountDownLatch::countDown);
512:                             }
513:                         })
514:                 .setParallelism(1);
515: 
516:         final JobGraph jobGraph = env.getStreamGraph().getJobGraph();
517: 
518:         MiniClusterWithClientResource cluster =
519:                 new MiniClusterWithClientResource(
