528:             cluster.getClusterClient().submitJob(jobGraph).get();
529:             CommonTestUtils.waitForAllTaskRunning(cluster.getMiniCluster(), jobID1, false);
530:             // wait for some records to be processed before taking the checkpoint
531:             counter.get().await();
532:             final String firstCheckpoint = cluster.getMiniCluster().triggerCheckpoint(jobID1).get();
533: 
534:             cluster.getClusterClient().cancel(jobID1).get();
535:             jobGraph.setSavepointRestoreSettings(
536:                     SavepointRestoreSettings.forPath(firstCheckpoint, false, RecoveryClaimMode.NO_CLAIM));
537:             final JobID jobID2 = new JobID();
538:             jobGraph.setJobID(jobID2);
539:             cluster.getClusterClient().submitJob(jobGraph).get();
540:             CommonTestUtils.waitForAllTaskRunning(cluster.getMiniCluster(), jobID2, false);
541:             String secondCheckpoint = cluster.getMiniCluster().triggerCheckpoint(jobID2).get();
542:             cluster.getClusterClient().cancel(jobID2).get();
