681:     @FunctionalInterface
682:     interface PostCancelChecker {
683:         void check(MiniClusterWithClientResource cluster) throws Exception;
684:     }
685: 
686:     private void restoreJobAndVerifyState(
687:             MiniClusterResourceFactory clusterFactory,
688:             int parallelism,
689:             SavepointRestoreSettings savepointRestoreSettings,
690:             PostCancelChecker postCancelChecks)
691:             throws Exception {
692:         final JobGraph jobGraph = createJobGraph(parallelism, 0, 1000);
693:         jobGraph.setSavepointRestoreSettings(savepointRestoreSettings);
694:         final JobID jobId = jobGraph.getJobID();
695:         StatefulCounter.resetForTest(parallelism);
696: 
697:         MiniClusterWithClientResource cluster = clusterFactory.get();
698:         cluster.before();
699:         ClusterClient<?> client = cluster.getClusterClient();
700: 
701:         try {
702:             client.submitJob(jobGraph).get();
703: 
704:             // Await state is restored
705:             StatefulCounter.getRestoreLatch().await();
706: 
707:             // Await some progress after restore
708:             StatefulCounter.getProgressLatch().await();
709: 
710:             client.cancel(jobId).get();
711: 
712:             FutureUtils.retrySuccessfulWithDelay(
713:                     () -> client.getJobStatus(jobId),
714:                     Duration.ofMillis(50),
715:                     Deadline.now().plus(Duration.ofSeconds(30)),
716:                     status -> status == JobStatus.CANCELED,
717:                     new ScheduledExecutorServiceAdapter(EXECUTOR_RESOURCE.getExecutor()));
718: 
719:             postCancelChecks.check(cluster);
720:         } finally {
721:             cluster.after();
722:             StatefulCounter.resetForTest(parallelism);
723:         }
724:     }
