847:     static class BoundedPassThroughOperator<T> extends AbstractStreamOperator<T>
848:             implements OneInputStreamOperator<T, T>, BoundedOneInput {
849:         static volatile CountDownLatch progressLatch;
850:         static volatile CountDownLatch snapshotAllowedLatch;
851:         static volatile CountDownLatch snapshotStartedLatch;
852:         static volatile boolean inputEnded;
853: 
854:         private transient boolean processed;
855: 
856:         BoundedPassThroughOperator(ChainingStrategy chainingStrategy) {
857:             this.chainingStrategy = chainingStrategy;
858:         }
859: 
860:         private static void allowSnapshots() {
861:             snapshotAllowedLatch.countDown();
862:         }
863: 
864:         public static void awaitSnapshotStarted() throws InterruptedException {
865:             snapshotStartedLatch.await();
866:         }
867: 
868:         @Override
869:         public void endInput() throws Exception {
870:             inputEnded = true;
871:         }
872: 
873:         @Override
874:         public void processElement(StreamRecord<T> element) throws Exception {
875:             output.collect(element);
876:             if (!processed) {
877:                 processed = true;
878:                 progressLatch.countDown();
879:             }
880:         }
881: 
882:         @Override
883:         public void snapshotState(StateSnapshotContext context) throws Exception {
884:             snapshotStartedLatch.countDown();
885:             snapshotAllowedLatch.await();
886:             super.snapshotState(context);
887:         }
888: 
889:         // --------------------------------------------------------------------
890: 
891:         static CountDownLatch getProgressLatch() {
892:             return progressLatch;
893:         }
894: 
895:         static void resetForTest(int parallelism, boolean allowSnapshots) {
896:             progressLatch = new CountDownLatch(parallelism);
897:             snapshotAllowedLatch = new CountDownLatch(allowSnapshots ? 0 : 1);
898:             snapshotStartedLatch = new CountDownLatch(parallelism);
899:             inputEnded = false;
900:         }
901:     }
