1100:     private static OneShotLatch failingPipelineLatch;
1101:     private static OneShotLatch succeedingPipelineLatch;
1102: 
1103:     /**
1104:      * FLINK-21030
1105:      *
1106:      * <p>Tests the handling of a failure that happened while stopping an embarrassingly parallel
1107:      * job with a Savepoint. The test expects that the stopping action fails and all executions are
1108:      * in state {@code RUNNING} afterwards.
1109:      *
1110:      * @param failingSource the failing {@link SourceFunction} used in one of the two pipelines.
1111:      * @param expectedMaximumNumberOfRestarts the maximum number of restarts allowed by the restart
1112:      *     strategy.
1113:      * @param exceptionAssertion asserts the client-call exception to verify that the right error
1114:      *     was handled.
1115:      * @see SavepointITCase#failingPipelineLatch The latch used to trigger the successful start of
1116:      *     the later on failing pipeline.
1117:      * @see SavepointITCase#succeedingPipelineLatch The latch that triggers the successful start of
1118:      *     the succeeding pipeline.
1119:      * @throws Exception if an error occurred while running the test.
1120:      */
1121:     private static void testStopWithFailingSourceInOnePipeline(
1122:             InfiniteTestSource failingSource,
1123:             File savepointDir,
1124:             int expectedMaximumNumberOfRestarts,
1125:             BiFunction<JobID, ExecutionException, Boolean> exceptionAssertion,
1126:             boolean shouldRestart)
1127:             throws Exception {
1128:         MiniClusterWithClientResource cluster =
1129:                 new MiniClusterWithClientResource(
1130:                         new MiniClusterResourceConfiguration.Builder().build());
1131: 
1132:         failingPipelineLatch = new OneShotLatch();
1133:         succeedingPipelineLatch = new OneShotLatch();
1134: 
1135:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
1136:         env.setParallelism(1);
1137:         env.getConfig()
1138:                 .setRestartStrategy(
1139:                         RestartStrategies.fixedDelayRestart(expectedMaximumNumberOfRestarts, 0));
1140:         env.addSource(failingSource)
1141:                 .name("Failing Source")
1142:                 .map(
1143:                         value -> {
1144:                             failingPipelineLatch.trigger();
1145:                             return value;
1146:                         })
1147:                 .sinkTo(new DiscardingSink<>());
1148:         env.addSource(new InfiniteTestSource())
1149:                 .name("Succeeding Source")
1150:                 .map(
1151:                         value -> {
1152:                             succeedingPipelineLatch.trigger();
1153:                             return value;
1154:                         })
1155:                 .sinkTo(new DiscardingSink<>());
1156: 
1157:         final JobGraph jobGraph = env.getStreamGraph().getJobGraph();
1158: 
1159:         cluster.before();
1160:         try {
1161:             ClusterClient<?> client = cluster.getClusterClient();
1162:             JobID jobID = client.submitJob(jobGraph).get();
1163: 
1164:             // we need to wait for both pipelines to be in state RUNNING because that's the only
1165:             // state which allows creating a savepoint
1166:             failingPipelineLatch.await();
1167:             succeedingPipelineLatch.await();
1168:             waitForAllTaskRunning(cluster.getMiniCluster(), jobID, false);
1169: 
1170:             try {
1171:                 client.stopWithSavepoint(
1172:                                 jobGraph.getJobID(),
1173:                                 false,
1174:                                 savepointDir.getAbsolutePath(),
1175:                                 SavepointFormatType.CANONICAL)
1176:                         .get();
1177:                 fail("The future should fail exceptionally.");
1178:             } catch (ExecutionException e) {
1179:                 assertThrowable(e, ex -> exceptionAssertion.apply(jobGraph.getJobID(), e));
1180:             }
1181: 
1182:             if (shouldRestart) {
1183:                 waitUntilAllTasksAreRunning(cluster.getRestClusterClient(), jobGraph.getJobID());
1184:             }
1185:         } finally {
1186:             cluster.after();
1187:         }
1188:     }
