1190:     public static void waitUntilAllTasksAreRunning(
1191:             RestClusterClient<?> restClusterClient, JobID jobId) throws Exception {
1192:         // access the REST endpoint of the cluster to determine the state of each
1193:         // ExecutionVertex
1194: 
1195:         final JobDetailsHeaders detailsHeaders = JobDetailsHeaders.getInstance();
1196:         final JobMessageParameters params = detailsHeaders.getUnresolvedMessageParameters();
1197:         params.jobPathParameter.resolve(jobId);
1198: 
1199:         CommonTestUtils.waitUntilCondition(
1200:                 () ->
1201:                         restClusterClient
1202:                                 .sendRequest(detailsHeaders, params, EmptyRequestBody.getInstance())
1203:                                 .thenApply(
1204:                                         detailsInfo ->
1205:                                                 allVerticesRunning(
1206:                                                         detailsInfo.getJobVerticesPerState()))
1207:                                 .get());
1208:     }
1209: 
1210:     private static boolean allVerticesRunning(Map<ExecutionState, Integer> states) {
1211:         return states.entrySet().stream()
1212:                 .allMatch(
1213:                         entry -> {
1214:                             if (entry.getKey() == ExecutionState.RUNNING) {
1215:                                 return entry.getValue() > 0;
1216:                             } else {
1217:                                 return entry.getValue() == 0; // no vertices in non-running state.
1218:                             }
1219:                         });
1220:     }
