1375:     private static class InfiniteTestSource implements ParallelSourceFunction<Integer> {
1376: 
1377:         private static final long serialVersionUID = 1L;
1378:         private volatile boolean running = true;
1379:         private volatile boolean suspended = false;
1380:         private static final Collection<InfiniteTestSource> createdSources =
1381:                 new CopyOnWriteArrayList<>();
1382:         private transient volatile CompletableFuture<Void> completeFuture;
1383: 
1384:         @Override
1385:         public void run(SourceContext<Integer> ctx) throws Exception {
1386:             completeFuture = new CompletableFuture<>();
1387:             createdSources.add(this);
1388:             try {
1389:                 while (running) {
1390:                     if (!suspended) {
1391:                         synchronized (ctx.getCheckpointLock()) {
1392:                             ctx.collect(1);
1393:                         }
1394:                     }
1395:                     Thread.sleep(1);
1396:                 }
1397:                 completeFuture.complete(null);
1398:             } catch (Exception e) {
1399:                 completeFuture.completeExceptionally(e);
1400:                 throw e;
1401:             }
1402:         }
1403: 
1404:         @Override
1405:         public void cancel() {
1406:             running = false;
1407:         }
1408: 
1409:         public void suspend() {
1410:             suspended = true;
1411:         }
1412: 
1413:         public static void resetForTest() {
1414:             createdSources.clear();
1415:         }
1416: 
1417:         public CompletableFuture<Void> getCompleteFuture() {
1418:             return completeFuture;
1419:         }
