1421:         public static void cancelAllAndAwait() throws ExecutionException, InterruptedException {
1422:             createdSources.forEach(InfiniteTestSource::cancel);
1423:             allOf(
1424:                             createdSources.stream()
1425:                                     .map(InfiniteTestSource::getCompleteFuture)
1426:                                     .toArray(CompletableFuture[]::new))
1427:                     .get();
1428:         }
1429: 
1430:         public static void suspendAll() {
1431:             createdSources.forEach(InfiniteTestSource::suspend);
1432:         }
