59: /**
60:  * A utility class with the methods to write/load/dispose the checkpoint and savepoint metadata.
61:  *
62:  * <p>Stored checkpoint metadata files have the following format:
63:  *
64:  * <pre>[MagicNumber (int) | Format Version (int) | Checkpoint Metadata (variable)]</pre>
65:  *
66:  * <p>The actual savepoint serialization is version-specific via the {@link MetadataSerializer}.
67:  */
68: public class Checkpoints {
69: 
70:     private static final Logger LOG = LoggerFactory.getLogger(Checkpoints.class);
71: 
72:     /** Magic number at the beginning of every checkpoint metadata file, for sanity checks. */
73:     public static final int HEADER_MAGIC_NUMBER = 0x4960672d;
74: 
75:     // ------------------------------------------------------------------------
76:     //  Writing out checkpoint metadata
77:     // ------------------------------------------------------------------------
78: 
79:     public static void storeCheckpointMetadata(
80:             CheckpointMetadata checkpointMetadata, OutputStream out) throws IOException {
81: 
82:         DataOutputStream dos = new DataOutputStream(out);
83:         storeCheckpointMetadata(checkpointMetadata, dos);
84:     }
85: 
86:     public static void storeCheckpointMetadata(
87:             CheckpointMetadata checkpointMetadata, DataOutputStream out) throws IOException {
88:         storeCheckpointMetadata(checkpointMetadata, out, MetadataV4Serializer.INSTANCE);
89:     }
90: 
91:     public static void storeCheckpointMetadata(
92:             CheckpointMetadata checkpointMetadata,
93:             DataOutputStream out,
94:             MetadataSerializer serializer)
95:             throws IOException {
96: 
97:         // write generic header
98:         out.writeInt(HEADER_MAGIC_NUMBER);
99: 
100:         out.writeInt(serializer.getVersion());
101:         serializer.serialize(checkpointMetadata, out);
102:     }
103: 
104:     // ------------------------------------------------------------------------
105:     //  Reading and validating checkpoint metadata
106:     // ------------------------------------------------------------------------
107: 
108:     public static CheckpointMetadata loadCheckpointMetadata(
109:             DataInputStream in, ClassLoader classLoader, String externalPointer)
110:             throws IOException {
111:         checkNotNull(in, "input stream");
112:         checkNotNull(classLoader, "classLoader");
113: 
114:         final int magicNumber = in.readInt();
115: 
116:         if (magicNumber == HEADER_MAGIC_NUMBER) {
117:             final int version = in.readInt();
118:             final MetadataSerializer serializer = MetadataSerializers.getSerializer(version);
119:             return serializer.deserialize(in, classLoader, externalPointer);
120:         } else {
121:             throw new IOException(
122:                     "Unexpected magic number. This can have multiple reasons: "
123:                             + "(1) You are trying to load a Flink 1.0 savepoint, which is not supported by this "
124:                             + "version of Flink. (2) The file you were pointing to is not a savepoint at all. "
125:                             + "(3) The savepoint file has been corrupted.");
126:         }
127:     }
128: 
129:     public static CompletedCheckpoint loadAndValidateCheckpoint(
130:             JobID jobId,
131:             Map<JobVertexID, ExecutionJobVertex> tasks,
132:             CompletedCheckpointStorageLocation location,
133:             ClassLoader classLoader,
134:             boolean allowNonRestoredState,
135:             CheckpointProperties checkpointProperties)
136:             throws IOException {
137: 
138:         checkNotNull(jobId, "jobId");
139:         checkNotNull(tasks, "tasks");
140:         checkNotNull(location, "location");
141:         checkNotNull(classLoader, "classLoader");
142: 
143:         final StreamStateHandle metadataHandle = location.getMetadataHandle();
144:         final String checkpointPointer = location.getExternalPointer();
145: 
146:         // (1) load the savepoint
147:         final CheckpointMetadata checkpointMetadata;
148:         try (InputStream in = metadataHandle.openInputStream()) {
149:             DataInputStream dis = new DataInputStream(in);
150:             checkpointMetadata = loadCheckpointMetadata(dis, classLoader, checkpointPointer);
151:         }
152: 
153:         // generate mapping from operator to task
154:         Map<OperatorID, ExecutionJobVertex> operatorToJobVertexMapping = new HashMap<>();
155:         for (ExecutionJobVertex task : tasks.values()) {
156:             for (OperatorIDPair operatorIDPair : task.getOperatorIDs()) {
157:                 operatorToJobVertexMapping.put(operatorIDPair.getGeneratedOperatorID(), task);
158:                 operatorIDPair
159:                         .getUserDefinedOperatorID()
160:                         .ifPresent(id -> operatorToJobVertexMapping.put(id, task));
161:             }
162:         }
163: 
164:         // (2) validate it (parallelism, etc)
165:         HashMap<OperatorID, OperatorState> operatorStates =
166:                 CollectionUtil.newHashMapWithExpectedSize(
167:                         checkpointMetadata.getOperatorStates().size());
168:         for (OperatorState operatorState : checkpointMetadata.getOperatorStates()) {
169: 
170:             ExecutionJobVertex executionJobVertex =
171:                     operatorToJobVertexMapping.get(operatorState.getOperatorID());
172: 
173:             if (executionJobVertex != null) {
174: 
175:                 if (executionJobVertex.getMaxParallelism() == operatorState.getMaxParallelism()
176:                         || executionJobVertex.canRescaleMaxParallelism(
177:                                 operatorState.getMaxParallelism())) {
178:                     operatorStates.put(operatorState.getOperatorID(), operatorState);
179:                 } else {
180:                     String msg =
181:                             String.format(
182:                                     "Failed to rollback to checkpoint/savepoint %s. "
183:                                             + "Max parallelism mismatch between checkpoint/savepoint state and new program. "
184:                                             + "Cannot map operator %s with max parallelism %d to new program with "
185:                                             + "max parallelism %d. This indicates that the program has been changed "
186:                                             + "in a non-compatible way after the checkpoint/savepoint.",
187:                                     checkpointMetadata,
188:                                     operatorState.getOperatorID(),
189:                                     operatorState.getMaxParallelism(),
190:                                     executionJobVertex.getMaxParallelism());
191: 
192:                     throw new IllegalStateException(msg);
193:                 }
194:             } else if (allowNonRestoredState) {
195:                 LOG.info(
196:                         "Skipping savepoint state for operator {}.", operatorState.getOperatorID());
197:             } else {
198:                 if (operatorState.getCoordinatorState() != null) {
199:                     throwNonRestoredStateException(
200:                             checkpointPointer, operatorState.getOperatorID());
201:                 }
202: 
203:                 for (OperatorSubtaskState operatorSubtaskState : operatorState.getStates()) {
204:                     if (operatorSubtaskState.hasState()) {
205:                         throwNonRestoredStateException(
206:                                 checkpointPointer, operatorState.getOperatorID());
207:                     }
208:                 }
209: 
210:                 LOG.info(
211:                         "Skipping empty savepoint state for operator {}.",
212:                         operatorState.getOperatorID());
213:             }
214:         }
215: 
216:         return new CompletedCheckpoint(
217:                 jobId,
218:                 checkpointMetadata.getCheckpointId(),
219:                 0L,
220:                 0L,
221:                 operatorStates,
222:                 checkpointMetadata.getMasterStates(),
223:                 checkpointProperties,
224:                 location,
225:                 null,
226:                 checkpointMetadata.getCheckpointProperties());
227:     }
228: 
229:     private static void throwNonRestoredStateException(
230:             String checkpointPointer, OperatorID operatorId) {
231:         String msg =
232:                 String.format(
233:                         "Failed to rollback to checkpoint/savepoint %s. "
234:                                 + "Cannot map checkpoint/savepoint state for operator %s to the new program, "
235:                                 + "because the operator is not available in the new program. If "
236:                                 + "you want to allow to skip this, you can set the --allowNonRestoredState "
237:                                 + "option on the CLI.",
238:                         checkpointPointer, operatorId);
239: 
240:         throw new IllegalStateException(msg);
241:     }
