247:     public static void disposeSavepoint(
248:             String pointer, CheckpointStorage checkpointStorage, ClassLoader classLoader)
249:             throws IOException, FlinkException {
250: 
251:         checkNotNull(pointer, "location");
252:         checkNotNull(checkpointStorage, "stateBackend");
253:         checkNotNull(classLoader, "classLoader");
254: 
255:         final CompletedCheckpointStorageLocation checkpointLocation =
256:                 checkpointStorage.resolveCheckpoint(pointer);
257: 
258:         final StreamStateHandle metadataHandle = checkpointLocation.getMetadataHandle();
259: 
260:         // load the savepoint object (the metadata) to have all the state handles that we need
261:         // to dispose of all state
262:         final CheckpointMetadata metadata;
263:         try (InputStream in = metadataHandle.openInputStream();
264:                 DataInputStream dis = new DataInputStream(in)) {
265: 
266:             metadata = loadCheckpointMetadata(dis, classLoader, pointer);
267:         }
268: 
269:         Exception exception = null;
270: 
271:         // first dispose the savepoint metadata, so that the savepoint is not
272:         // addressable any more even if the following disposal fails
273:         try {
274:             metadataHandle.discardState();
275:         } catch (Exception e) {
276:             exception = e;
277:         }
278: 
279:         // now dispose the savepoint data
280:         try {
281:             metadata.dispose();
282:         } catch (Exception e) {
283:             exception = ExceptionUtils.firstOrSuppressed(e, exception);
284:         }
285: 
286:         // now dispose the location (directory, table, whatever)
287:         try {
288:             checkpointLocation.disposeStorageLocation();
289:         } catch (Exception e) {
290:             exception = ExceptionUtils.firstOrSuppressed(e, exception);
291:         }
292: 
293:         // forward exceptions caught in the process
294:         if (exception != null) {
295:             ExceptionUtils.rethrowIOException(exception);
296:         }
297:     }
