299:     public static void disposeSavepoint(
300:             String pointer,
301:             Configuration configuration,
302:             ClassLoader classLoader,
303:             @Nullable Logger logger)
304:             throws IOException, FlinkException {
305: 
306:         checkNotNull(pointer, "location");
307:         checkNotNull(configuration, "configuration");
308:         checkNotNull(classLoader, "classLoader");
309: 
310:         // An empty job configuration is utilized here because `disposeSavepoint` is intended
311:         // for cluster-wide operations, which do not require job-specific configuration.
312:         CheckpointStorage storage =
313:                 loadCheckpointStorage(new Configuration(), configuration, classLoader, logger);
314: 
315:         disposeSavepoint(pointer, storage, classLoader);
316:     }
