318:     @Nonnull
319:     public static StateBackend loadStateBackend(
320:             Configuration jobConfig,
321:             Configuration clusterConfig,
322:             ClassLoader classLoader,
323:             @Nullable Logger logger) {
324:         if (logger != null) {
325:             logger.info("Attempting to load configured state backend for savepoint disposal");
326:         }
327: 
328:         // Job level config can override the cluster level config.
329:         Configuration mergedConfig = new Configuration(clusterConfig);
330:         mergedConfig.addAll(jobConfig);
331:         try {
332:             return StateBackendLoader.loadStateBackendFromConfig(mergedConfig, classLoader, null);
333:         } catch (Throwable t) {
334:             // catches exceptions and errors (like linking errors)
335:             if (logger != null) {
336:                 logger.info("Could not load configured state backend.");
337:                 logger.debug("Detailed exception:", t);
338:             }
339:             return new HashMapStateBackend();
340:         }
341:     }
342: 
343:     @Nonnull
344:     public static CheckpointStorage loadCheckpointStorage(
345:             Configuration jobConfig,
346:             Configuration clusterConfig,
347:             ClassLoader classLoader,
348:             @Nullable Logger logger) {
349:         StateBackend backend = loadStateBackend(jobConfig, clusterConfig, classLoader, logger);
350: 
351:         if (logger != null) {
352:             logger.info("Attempting to load configured checkpoint storage for savepoint disposal");
353:         }
354: 
355:         CheckpointStorage checkpointStorage = null;
356:         try {
357:             checkpointStorage =
358:                     CheckpointStorageLoader.load(
359:                             null, backend, jobConfig, clusterConfig, classLoader, null);
360:         } catch (Throwable t) {
361:             // catches exceptions and errors (like linking errors)
362:             if (logger != null) {
363:                 logger.info("Could not load configured state backend.");
364:                 logger.debug("Detailed exception:", t);
365:             }
366:         }
367: 
368:         if (checkpointStorage == null) {
369:             // We use the jobmanager checkpoint storage by default.
370:             // The JobManagerCheckpointStorage is actually
371:             // FileSystem-based for metadata
372:             return new JobManagerCheckpointStorage();
373:         }
374:         return checkpointStorage;
375:     }
