97:     @Override
98:     public void init() throws Exception {
99:         StreamConfig configuration = getConfiguration();
100:         int numberOfInputs = configuration.getNumberOfNetworkInputs();
101: 
102:         if (numberOfInputs > 0) {
103:             CheckpointedInputGate inputGate = createCheckpointedInputGate();
104:             Counter numRecordsIn = setupNumRecordsInCounter(mainOperator);
105:             DataOutput<IN> output = createDataOutput(numRecordsIn);
106:             StreamTaskInput<IN> input = createTaskInput(inputGate);
107: 
108:             StreamConfig.InputConfig[] inputConfigs =
109:                     configuration.getInputs(getUserCodeClassLoader());
110:             StreamConfig.InputConfig inputConfig = inputConfigs[0];
111:             if (requiresSorting(inputConfig)) {
112:                 checkState(
113:                         !configuration.isCheckpointingEnabled(),
114:                         "Checkpointing is not allowed with sorted inputs.");
115:                 input = wrapWithSorted(input);
116:             }
117: 
118:             getEnvironment()
119:                     .getMetricGroup()
120:                     .getIOMetricGroup()
121:                     .reuseRecordsInputCounter(numRecordsIn);
122: 
123:             inputProcessor = new StreamOneInputProcessor<>(input, output, operatorChain);
124:         }
125:         mainOperator
126:                 .getMetricGroup()
127:                 .gauge(MetricNames.IO_CURRENT_INPUT_WATERMARK, inputWatermarkGauge);
128:         // wrap watermark gauge since registered metrics must be unique
129:         getEnvironment()
130:                 .getMetricGroup()
131:                 .gauge(MetricNames.IO_CURRENT_INPUT_WATERMARK, inputWatermarkGauge::getValue);
132:     }
