144:                 configuration.getStateKeySerializer(userCodeClassLoader),
145:                 configuration.getStatePartitioner(input.getInputIndex(), userCodeClassLoader),
146:                 getEnvironment().getMemoryManager(),
147:                 getEnvironment().getIOManager(),
148:                 getExecutionConfig().isObjectReuseEnabled(),
149:                 configuration.getManagedMemoryFractionOperatorUseCaseOfSlot(
150:                         ManagedMemoryUseCase.OPERATOR,
151:                         getJobConfiguration(),
