174:         CheckpointedInputGate[] checkpointedInputGates =
175:                 InputProcessorUtil.createCheckpointedMultipleInputGate(
176:                         mainMailboxExecutor,
177:                         new List[] {Arrays.asList(inputGates)},
178:                         getEnvironment().getMetricGroup().getIOMetricGroup(),
179:                         checkpointBarrierHandler,
