192:     private StreamTaskInput<IN> createTaskInput(CheckpointedInputGate inputGate) {
193:         StatusWatermarkValve statusWatermarkValve = new StatusWatermarkValve(inputGate);
194: 
195:         TypeSerializer<IN> inSerializer =
196:                 configuration.getTypeSerializerIn1(getUserCodeClassLoader());
197: 
198:         return StreamTaskNetworkInputFactory.create(
199:                 inputGate,
200:                 inSerializer,
201:                 getEnvironment().getIOManager(),
202:                 statusWatermarkValve,
203:                 0,
204:                 getEnvironment().getTaskStateManager().getInputRescalingDescriptor(),
205:                 gateIndex ->
206:                         configuration
207:                                 .getInPhysicalEdges(getUserCodeClassLoader())
208:                                 .get(gateIndex)
209:                                 .getPartitioner(),
210:                 getEnvironment().getTaskInfo(),
211:                 getCanEmitBatchOfRecords());
212:     }
