231:             this.numRecordsIn = checkNotNull(numRecordsIn);
232:             this.recordProcessor = RecordProcessorUtils.getRecordProcessor(operator);
233:         }
234: 
235:         @Override
236:         public void emitRecord(StreamRecord<IN> record) throws Exception {
237:             numRecordsIn.inc();
238:             recordProcessor.accept(record);
239:         }
240: 
241:         @Override
242:         public void emitWatermark(Watermark watermark) throws Exception {
243:             watermarkGauge.setCurrentWatermark(watermark.getTimestamp());
244:             operator.processWatermark(watermark);
245:         }
246: 
247:         @Override
248:         public void emitWatermarkStatus(WatermarkStatus watermarkStatus) throws Exception {
249:             operator.processWatermarkStatus(watermarkStatus);
250:         }
251: 
252:         @Override
253:         public void emitLatencyMarker(LatencyMarker latencyMarker) throws Exception {
254:             operator.processLatencyMarker(latencyMarker);
255:         }
256: 
257:         @Override
258:         public void emitRecordAttributes(RecordAttributes recordAttributes) throws Exception {
259:             operator.processRecordAttributes(recordAttributes);
260:         }
261:     }
