751:     /**
752:      * Starts additional TaskManager process.
753:      *
754:      * <p>When the MiniCluster starts up, it always starts {@link
755:      * MiniClusterConfiguration#getNumTaskManagers} TaskManagers. All TaskManagers are indexed from
756:      * 0 to the number of TaskManagers, started so far, minus one. This method starts a TaskManager
757:      * with the next index which is the number of TaskManagers, started so far. The index always
758:      * increases with each new started TaskManager. The indices of terminated TaskManagers are not
759:      * reused after {@link #terminateTaskManager(int)}.
760:      */
761:     public void startTaskManager() throws Exception {
762:         synchronized (lock) {
763:             final Configuration configuration = miniClusterConfiguration.getConfiguration();
764: 
765:             final TaskExecutor taskExecutor =
766:                     TaskManagerRunner.startTaskManager(
767:                             configuration,
768:                             new ResourceID(UUID.randomUUID().toString()),
769:                             taskManagerRpcServiceFactory.createRpcService(),
770:                             haServices,
771:                             heartbeatServices,
772:                             metricRegistry,
773:                             blobCacheService,
774:                             useLocalCommunication(),
775:                             ExternalResourceInfoProvider.NO_EXTERNAL_RESOURCES,
776:                             workingDirectory.createSubWorkingDirectory("tm_" + taskManagers.size()),
777:                             taskManagerTerminatingFatalErrorHandlerFactory.create(
778:                                     taskManagers.size()),
779:                             delegationTokenReceiverRepository);
780: 
781:             taskExecutor.start();
782:             taskManagers.add(taskExecutor);
783:         }
784:     }
