1037:     public JobExecutionResult executeJobBlocking(JobGraph job)
1038:             throws JobExecutionException, InterruptedException {
1039:         checkNotNull(job, "job is null");
1040: 
1041:         final CompletableFuture<JobSubmissionResult> submissionFuture = submitJob(job);
1042: 
1043:         final CompletableFuture<JobResult> jobResultFuture =
1044:                 submissionFuture.thenCompose(
1045:                         (JobSubmissionResult ignored) -> requestJobResult(job.getJobID()));
1046: 
1047:         final JobResult jobResult;
1048: 
