1304:         // collect the first exception, but continue and add all successive
1305:         // exceptions as suppressed
1306:         Exception exception = null;
1307: 
1308:         synchronized (lock) {
1309:             if (blobCacheService != null) {
1310:                 try {
1311:                     blobCacheService.close();
1312:                 } catch (Exception e) {
1313:                     exception = ExceptionUtils.firstOrSuppressed(e, exception);
1314:                 }
1315:                 blobCacheService = null;
1316:             }
1317: 
1318:             // shut down the blob server
1319:             if (blobServer != null) {
1320:                 try {
1321:                     blobServer.close();
1322:                 } catch (Exception e) {
1323:                     exception = ExceptionUtils.firstOrSuppressed(e, exception);
1324:                 }
1325:                 blobServer = null;
1326:             }
1327: 
1328:             // shut down high-availability services
1329:             if (haServices != null) {
1330:                 haServices.closeWithOptionalClean(cleanupHaData);
1331:                 haServices = null;
1332:             }
1333: 
1334:             try {
1335:                 if (rpcSystem.isOwned()) {
1336:                     rpcSystem.deref().close();
1337:                 }
1338:             } catch (Exception e) {
1339:                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1340:             }
1341: 
1342:             if (exception != null) {
1343:                 throw exception;
1344:             }
1345:         }
