235:     private void testRestoreLatestCheckpointedState(
236:             List<TestingVertex> vertices, Collection<CompletedCheckpoint> completedCheckpoints)
237:             throws Exception {
238:         final ExecutionGraph executionGraph = createExecutionGraph(vertices);
239:         final EmbeddedCompletedCheckpointStore store =
240:                 new EmbeddedCompletedCheckpointStore(
241:                         completedCheckpoints.size(), completedCheckpoints, RecoveryClaimMode.DEFAULT);
242: 
243:         // set up the coordinator and validate the initial state
244:         final CheckpointCoordinator coordinator =
245:                 new CheckpointCoordinatorBuilder()
246:                         .setTimer(manuallyTriggeredScheduledExecutor)
247:                         .setCompletedCheckpointStore(store)
248:                         .build(executionGraph);
249: 
250:         final Set<ExecutionJobVertex> executionVertices =
251:                 vertices.stream()
252:                         .map(TestingVertex::getId)
253:                         .map(executionGraph::getJobVertex)
254:                         .collect(Collectors.toSet());
255:         assertThat(coordinator.restoreLatestCheckpointedStateToAll(executionVertices, false))
256:                 .isTrue();
257: 
258:         // validate that all shared states are registered again after the recovery.
259:         for (CompletedCheckpoint completedCheckpoint : completedCheckpoints) {
260:             for (OperatorState taskState : completedCheckpoint.getOperatorStates().values()) {
261:                 for (OperatorSubtaskState subtaskState : taskState.getStates()) {
262:                     verify(subtaskState, times(2))
263:                             .registerSharedStates(
264:                                     any(SharedStateRegistry.class),
265:                                     eq(completedCheckpoint.getCheckpointID()));
266:                 }
267:             }
268:         }
269: 
270:         // verify the restored state
271:         for (ExecutionJobVertex executionVertex : executionVertices) {
272:             verifyStateRestore(executionVertex);
273:         }
274:     }
