319: 
320:         // trigger the checkpoint
321:         coord.triggerCheckpoint(false);
322:         manuallyTriggeredScheduledExecutor.triggerAll();
323: 
324:         assertThat(coord.getPendingCheckpoints().size()).isOne();
325:         long checkpointId = Iterables.getOnlyElement(coord.getPendingCheckpoints().keySet());
326: 
327:         List<KeyGroupRange> keyGroupPartitions1 =
328:                 StateAssignmentOperation.createKeyGroupPartitions(maxParallelism1, parallelism1);
329:         List<KeyGroupRange> keyGroupPartitions2 =
330:                 StateAssignmentOperation.createKeyGroupPartitions(maxParallelism2, parallelism2);
331: 
332:         // vertex 1
333:         for (int index = 0; index < jobVertex1.getParallelism(); index++) {
334:             OperatorStateHandle opStateBackend =
335:                     generatePartitionableStateHandle(jobVertexID1, index, 2, 8, false);
336:             KeyGroupsStateHandle keyedStateBackend =
337:                     generateKeyGroupState(jobVertexID1, keyGroupPartitions1.get(index), false);
338:             KeyGroupsStateHandle keyedStateRaw =
339:                     generateKeyGroupState(jobVertexID1, keyGroupPartitions1.get(index), true);
340:             OperatorSubtaskState operatorSubtaskState =
341:                     OperatorSubtaskState.builder()
342:                             .setManagedOperatorState(opStateBackend)
343:                             .setManagedKeyedState(keyedStateBackend)
344:                             .setRawKeyedState(keyedStateRaw)
345:                             .setInputChannelState(
346:                                     StateObjectCollection.singleton(
347:                                             createNewInputChannelStateHandle(3, new Random())))
348:                             .build();
349:             TaskStateSnapshot taskOperatorSubtaskStates = new TaskStateSnapshot();
350:             taskOperatorSubtaskStates.putSubtaskStateByOperatorID(
351:                     OperatorID.fromJobVertexID(jobVertexID1), operatorSubtaskState);
352: 
353:             AcknowledgeCheckpoint acknowledgeCheckpoint =
354:                     new AcknowledgeCheckpoint(
355:                             graph.getJobID(),
356:                             jobVertex1
357:                                     .getTaskVertices()[index]
358:                                     .getCurrentExecutionAttempt()
359:                                     .getAttemptId(),
360:                             checkpointId,
361:                             new CheckpointMetrics(),
362:                             taskOperatorSubtaskStates);
363: 
364:             coord.receiveAcknowledgeMessage(acknowledgeCheckpoint, TASK_MANAGER_LOCATION_INFO);
365:         }
366: 
367:         // vertex 2
368:         final List<ChainedStateHandle<OperatorStateHandle>> expectedOpStatesBackend =
369:                 new ArrayList<>(jobVertex2.getParallelism());
370:         final List<ChainedStateHandle<OperatorStateHandle>> expectedOpStatesRaw =
371:                 new ArrayList<>(jobVertex2.getParallelism());
372:         for (int index = 0; index < jobVertex2.getParallelism(); index++) {
373:             KeyGroupsStateHandle keyedStateBackend =
374:                     generateKeyGroupState(jobVertexID2, keyGroupPartitions2.get(index), false);
375:             KeyGroupsStateHandle keyedStateRaw =
376:                     generateKeyGroupState(jobVertexID2, keyGroupPartitions2.get(index), true);
377:             OperatorStateHandle opStateBackend =
378:                     generatePartitionableStateHandle(jobVertexID2, index, 2, 8, false);
379:             OperatorStateHandle opStateRaw =
380:                     generatePartitionableStateHandle(jobVertexID2, index, 2, 8, true);
381:             expectedOpStatesBackend.add(new ChainedStateHandle<>(singletonList(opStateBackend)));
382:             expectedOpStatesRaw.add(new ChainedStateHandle<>(singletonList(opStateRaw)));
383: 
384:             OperatorSubtaskState operatorSubtaskState =
385:                     OperatorSubtaskState.builder()
386:                             .setManagedOperatorState(opStateBackend)
387:                             .setRawOperatorState(opStateRaw)
388:                             .setManagedKeyedState(keyedStateBackend)
389:                             .setRawKeyedState(keyedStateRaw)
390:                             .build();
391:             TaskStateSnapshot taskOperatorSubtaskStates = new TaskStateSnapshot();
392:             taskOperatorSubtaskStates.putSubtaskStateByOperatorID(
393:                     OperatorID.fromJobVertexID(jobVertexID2), operatorSubtaskState);
394: 
395:             AcknowledgeCheckpoint acknowledgeCheckpoint =
396:                     new AcknowledgeCheckpoint(
397:                             graph.getJobID(),
398:                             jobVertex2
399:                                     .getTaskVertices()[index]
400:                                     .getCurrentExecutionAttempt()
401:                                     .getAttemptId(),
