410: 
411:         assertThat(completedCheckpoints.size()).isOne();
412: 
413:         List<KeyGroupRange> newKeyGroupPartitions2 =
414:                 StateAssignmentOperation.createKeyGroupPartitions(maxParallelism2, newParallelism2);
