435:         tasks.add(newJobVertex2);
436:         assertThat(newCoord.restoreLatestCheckpointedStateToAll(tasks, false)).isTrue();
437: 
438:         // verify the restored state
439:         verifyStateRestore(jobVertexID1, newJobVertex1, keyGroupPartitions1);
440:         List<List<Collection<OperatorStateHandle>>> actualOpStatesBackend =
441:                 new ArrayList<>(newJobVertex2.getParallelism());
442:         List<List<Collection<OperatorStateHandle>>> actualOpStatesRaw =
443:                 new ArrayList<>(newJobVertex2.getParallelism());
444:         for (int i = 0; i < newJobVertex2.getParallelism(); i++) {
445: 
446:             List<OperatorIDPair> operatorIDs = newJobVertex2.getOperatorIDs();
447: 
448:             KeyGroupsStateHandle originalKeyedStateBackend =
449:                     generateKeyGroupState(jobVertexID2, newKeyGroupPartitions2.get(i), false);
450:             KeyGroupsStateHandle originalKeyedStateRaw =
451:                     generateKeyGroupState(jobVertexID2, newKeyGroupPartitions2.get(i), true);
452: 
453:             JobManagerTaskRestore taskRestore =
454:                     newJobVertex2
455:                             .getTaskVertices()[i]
456:                             .getCurrentExecutionAttempt()
457:                             .getTaskRestore();
458:             assertThat(taskRestore.getRestoreCheckpointId()).isOne();
459:             TaskStateSnapshot taskStateHandles = taskRestore.getTaskStateSnapshot();
460: 
461:             final int headOpIndex = operatorIDs.size() - 1;
462:             List<Collection<OperatorStateHandle>> allParallelManagedOpStates =
463:                     new ArrayList<>(operatorIDs.size());
464:             List<Collection<OperatorStateHandle>> allParallelRawOpStates =
465:                     new ArrayList<>(operatorIDs.size());
466: 
467:             for (int idx = 0; idx < operatorIDs.size(); ++idx) {
468:                 OperatorID operatorID = operatorIDs.get(idx).getGeneratedOperatorID();
469:                 OperatorSubtaskState opState =
470:                         taskStateHandles.getSubtaskStateByOperatorID(operatorID);
471:                 Collection<OperatorStateHandle> opStateBackend = opState.getManagedOperatorState();
472:                 Collection<OperatorStateHandle> opStateRaw = opState.getRawOperatorState();
473:                 allParallelManagedOpStates.add(opStateBackend);
474:                 allParallelRawOpStates.add(opStateRaw);
475:                 if (idx == headOpIndex) {
476:                     Collection<KeyedStateHandle> keyedStateBackend = opState.getManagedKeyedState();
477:                     Collection<KeyedStateHandle> keyGroupStateRaw = opState.getRawKeyedState();
478:                     compareKeyedState(singletonList(originalKeyedStateBackend), keyedStateBackend);
479:                     compareKeyedState(singletonList(originalKeyedStateRaw), keyGroupStateRaw);
480:                 }
481:             }
482:             actualOpStatesBackend.add(allParallelManagedOpStates);
483:             actualOpStatesRaw.add(allParallelRawOpStates);
484:         }
485: 
486:         comparePartitionableState(expectedOpStatesBackend, actualOpStatesBackend);
487:         comparePartitionableState(expectedOpStatesRaw, actualOpStatesRaw);
488:     }
