948:     static CompletedCheckpointStore storeFor(
949:             SharedStateRegistry sharedStateRegistry,
950:             Runnable postCleanupAction,
951:             CompletedCheckpoint... checkpoints)
952:             throws Exception {
953:         StandaloneCompletedCheckpointStore store =
954:                 new StandaloneCompletedCheckpointStore(checkpoints.length);
955:         CheckpointsCleaner checkpointsCleaner = new CheckpointsCleaner();
956:         for (final CompletedCheckpoint checkpoint : checkpoints) {
957:             store.addCheckpointAndSubsumeOldestOne(
958:                     checkpoint, checkpointsCleaner, postCleanupAction);
959:         }
960:         return store;
961:     }
