208: 
209:         private SharedReference<CountDownLatch> finalCheckpointLatch;
210: 
211:         private ListState<Integer> nextValueState;
212: 
213:         private int nextValue;
214: 
215:         private volatile boolean snapshottedAfterAllRecordsOutput;
216: 
217:         private volatile boolean isWaitingCheckpointComplete;
218: 
219:         private volatile boolean isCanceled;
220: 
221:         public StatefulSource(
222:                 boolean takingSavepointMode, SharedReference<CountDownLatch> finalCheckpointLatch) {
223:             this.takingSavepointMode = takingSavepointMode;
224:             this.finalCheckpointLatch = finalCheckpointLatch;
225:         }
226: 
227:         @Override
228:         public void initializeState(FunctionInitializationContext context) throws Exception {
229:             nextValueState =
230:                     context.getOperatorStateStore()
231:                             .getListState(new ListStateDescriptor<>("nextValue", Integer.class));
232: 
233:             if (nextValueState.get() != null && nextValueState.get().iterator().hasNext()) {
234:                 nextValue = nextValueState.get().iterator().next();
235:             }
236:         }
237: 
238:         @Override
239:         public void run(SourceContext<Integer> ctx) throws Exception {
240:             if (takingSavepointMode) {
241:                 sendRecordsUntil(NUM_RECORDS / 3, 0, ctx);
242:                 sendRecordsUntil(NUM_RECORDS / 2, 100, ctx);
243: 
244:                 while (true) {
245:                     Thread.sleep(5000);
246:                 }
247:             } else {
248:                 sendRecordsUntil(NUM_RECORDS, 0, ctx);
249: 
250:                 // Wait the last checkpoint to commit all the pending records.
251:                 isWaitingCheckpointComplete = true;
252:                 finalCheckpointLatch.get().await();
253:             }
254:         }
255: 
256:         private void sendRecordsUntil(
257:                 int targetNumber, int sleepInMillis, SourceContext<Integer> ctx)
258:                 throws InterruptedException {
259:             while (!isCanceled && nextValue < targetNumber) {
260:                 synchronized (ctx.getCheckpointLock()) {
261:                     ctx.collect(nextValue++);
262:                 }
263: 
264:                 if (sleepInMillis > 0) {
265:                     Thread.sleep(sleepInMillis);
266:                 }
267:             }
268:         }
269: 
270:         @Override
271:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
272:             nextValueState.update(Collections.singletonList(nextValue));
273: 
274:             if (isWaitingCheckpointComplete) {
275:                 snapshottedAfterAllRecordsOutput = true;
276:             }
277:         }
278: 
279:         @Override
280:         public void notifyCheckpointComplete(long checkpointId) throws Exception {
281:             if (isWaitingCheckpointComplete && snapshottedAfterAllRecordsOutput) {
282:                 finalCheckpointLatch.get().countDown();
283:             }
284:         }
285: 
286:         @Override
287:         public void cancel() {
288:             isCanceled = true;
289:         }
