60: 
61:     private final boolean hasParallelismOpt;
62: 
63:     private final int parallelism;
64: 
65:     private final boolean detachedMode;
66: 
67:     private final boolean shutdownOnAttachedExit;
68: 
69:     private final SavepointRestoreSettings savepointSettings;
