71:     protected ProgramOptions(CommandLine line) throws CliArgsException {
72:         super(line);
73: 
74:         this.entryPointClass =
75:                 line.hasOption(CLASS_OPTION.getOpt())
76:                         ? line.getOptionValue(CLASS_OPTION.getOpt())
77:                         : null;
78: 
79:         this.jarFilePath =
80:                 line.hasOption(JAR_OPTION.getOpt())
81:                         ? line.getOptionValue(JAR_OPTION.getOpt())
82:                         : null;
83: 
84:         this.programArgs = extractProgramArgs(line);
85: 
86:         List<URL> classpaths = new ArrayList<URL>();
87:         if (line.hasOption(CLASSPATH_OPTION.getOpt())) {
88:             for (String path : line.getOptionValues(CLASSPATH_OPTION.getOpt())) {
89:                 try {
90:                     classpaths.add(new URL(path));
91:                 } catch (MalformedURLException e) {
92:                     throw new CliArgsException("Bad syntax for classpath: " + path);
93:                 }
94:             }
95:         }
96:         this.classpaths = classpaths;
97: 
98:         if (line.hasOption(PARALLELISM_OPTION.getOpt())) {
99:             hasParallelismOpt = true;
100:             String parString = line.getOptionValue(PARALLELISM_OPTION.getOpt());
101:             try {
102:                 parallelism = Integer.parseInt(parString);
103:                 if (parallelism <= 0 && parallelism != ExecutionConfig.PARALLELISM_DEFAULT) {
104:                     throw new NumberFormatException();
105:                 }
106:             } catch (NumberFormatException e) {
107:                 throw new CliArgsException(
108:                         "The parallelism must be a positive number: " + parString);
109:             }
110:         } else {
111:             hasParallelismOpt = false;
112:             parallelism = ExecutionConfig.PARALLELISM_DEFAULT;
113:         }
114: 
115:         detachedMode =
116:                 line.hasOption(DETACHED_OPTION.getOpt())
