396:      * <p>This is a probabilistic test case which only fails if executed repeatedly without the fix
397:      * for FLINK-12863.
398:      */
399:     @Test
400:     void testAllocatedSlotReportDoesNotContainStaleInformation() throws Exception {
401:         final CompletableFuture<Void> assertionFuture = new CompletableFuture<>();
402:         final UnresolvedTaskManagerLocation unresolvedTaskManagerLocation =
403:                 new LocalUnresolvedTaskManagerLocation();
404:         final AtomicBoolean terminateHeartbeatVerification = new AtomicBoolean(false);
405:         final OneShotLatch hasReceivedSlotOffers = new OneShotLatch();
406:         final TestingTaskExecutorGateway taskExecutorGateway =
407:                 new TestingTaskExecutorGatewayBuilder()
408:                         .setHeartbeatJobManagerFunction(
409:                                 (taskManagerId, allocatedSlotReport) -> {
410:                                     try {
411:                                         if (hasReceivedSlotOffers.isTriggered()) {
412:                                             assertThat(allocatedSlotReport.getAllocatedSlotInfos())
413:                                                     .hasSize(1);
414:                                         } else {
415:                                             assertThat(allocatedSlotReport.getAllocatedSlotInfos())
416:                                                     .isEmpty();
417:                                         }
418:                                     } catch (AssertionError e) {
419:                                         assertionFuture.completeExceptionally(e);
420:                                     }
421: 
422:                                     if (terminateHeartbeatVerification.get()) {
423:                                         assertionFuture.complete(null);
424:                                     }
425:                                     return FutureUtils.completedVoidFuture();
426:                                 })
427:                         .createTestingTaskExecutorGateway();
