441:             jobMaster.start();
442: 
443:             final JobMasterGateway jobMasterGateway =
444:                     jobMaster.getSelfGateway(JobMasterGateway.class);
445: 
446:             // register task manager will trigger monitor heartbeat target, schedule heartbeat
447:             // request at interval time
448:             CompletableFuture<RegistrationResponse> registrationResponse =
449:                     jobMasterGateway.registerTaskManager(
450:                             jobGraph.getJobID(),
451:                             TaskManagerRegistrationInformation.create(
452:                                     taskExecutorGateway.getAddress(),
453:                                     unresolvedTaskManagerLocation,
454:                                     TestingUtils.zeroUUID()),
455:                             testingTimeout);
456: 
457:             // wait for the completion of the registration
458:             registrationResponse.get();
459: 
460:             final SlotOffer slotOffer = new SlotOffer(new AllocationID(), 0, ResourceProfile.ANY);
461: 
462:             final CompletableFuture<Collection<SlotOffer>> slotOfferFuture =
463:                     jobMasterGateway.offerSlots(
464:                             unresolvedTaskManagerLocation.getResourceID(),
465:                             Collections.singleton(slotOffer),
466:                             testingTimeout);
467: 
468:             assertThat(slotOfferFuture.get()).containsExactly(slotOffer);
469: 
470:             terminateHeartbeatVerification.set(true);
471: 
472:             // make sure that no assertion has been violated
473:             assertionFuture.get();
474:         }
475:     }
