670:                 jobManagerRegistrationFuture = new CompletableFuture<>();
671:         final CompletableFuture<JobID> disconnectedJobManagerFuture = new CompletableFuture<>();
672:         final CountDownLatch registrationAttempts = new CountDownLatch(2);
673: 
674:         resourceManagerGateway.setRegisterJobManagerFunction(
675:                 (jobMasterId, resourceID, s, jobID) -> {
676:                     jobManagerRegistrationFuture.complete(
677:                             Tuple3.of(jobMasterId, resourceID, jobID));
678:                     registrationAttempts.countDown();
679: 
680:                     return CompletableFuture.completedFuture(
681:                             resourceManagerGateway.getJobMasterRegistrationSuccess());
682:                 });
683: 
684:         resourceManagerGateway.setDisconnectJobManagerConsumer(
685:                 tuple -> disconnectedJobManagerFuture.complete(tuple.f0));
686: 
687:         rpcService.registerGateway(resourceManagerAddress, resourceManagerGateway);
688: 
689:         try (final JobMaster jobMaster =
690:                 new JobMasterBuilder(jobGraph, rpcService)
691:                         .withJobMasterId(jobMasterId)
692:                         .withResourceId(jmResourceId)
693:                         .withConfiguration(configuration)
694:                         .withHighAvailabilityServices(haServices)
695:                         .withHeartbeatServices(fastHeartbeatServices)
696:                         .createJobMaster()) {
697: 
698:             jobMaster.start();
699: 
700:             // define a leader and see that a registration happens
701:             rmLeaderRetrievalService.notifyListener(
702:                     resourceManagerAddress, resourceManagerId.toUUID());
703: 
704:             // register job manager success will trigger monitor heartbeat target between jm and rm
705:             final Tuple3<JobMasterId, ResourceID, JobID> registrationInformation =
706:                     jobManagerRegistrationFuture.get(
707:                             testingTimeout.toMilliseconds(), TimeUnit.MILLISECONDS);
708: 
709:             assertThat(registrationInformation.f0).isEqualTo(jobMasterId);
710:             assertThat(registrationInformation.f1).isEqualTo(jmResourceId);
711:             assertThat(registrationInformation.f2).isEqualTo(jobGraph.getJobID());
712: 
713:             final JobID disconnectedJobManager =
714:                     disconnectedJobManagerFuture.get(
715:                             testingTimeout.toMilliseconds(), TimeUnit.MILLISECONDS);
716: 
717:             // heartbeat timeout should trigger disconnect JobManager from ResourceManager
718:             assertThat(disconnectedJobManager).isEqualTo(jobGraph.getJobID());
719: 
720:             // the JobMaster should try to reconnect to the RM
721:             registrationAttempts.await();
722:         }
723:     }
