1059:     private void runRequestNextInputSplitTest(
1060:             Function<List<List<InputSplit>>, Collection<InputSplit>> expectedRemainingInputSplits)
1061:             throws Exception {
1062:         final int parallelism = 2;
1063:         final int splitsPerTask = 2;
1064: 
1065:         final int totalSplits = parallelism * splitsPerTask;
1066:         final List<TestingInputSplit> allInputSplits = new ArrayList<>(totalSplits);
1067: 
1068:         for (int i = 0; i < totalSplits; i++) {
1069:             allInputSplits.add(new TestingInputSplit(i));
1070:         }
1071: 
1072:         final InputSplitSource<TestingInputSplit> inputSplitSource =
1073:                 new TestingInputSplitSource(allInputSplits);
1074: 
1075:         JobVertex source = new JobVertex("source");
1076:         source.setParallelism(parallelism);
1077:         source.setInputSplitSource(inputSplitSource);
1078:         source.setInvokableClass(AbstractInvokable.class);
1079: 
1080:         final ExecutionConfig executionConfig = new ExecutionConfig();
1081:         executionConfig.setRestartStrategy(RestartStrategies.fixedDelayRestart(100, 0));
1082: 
1083:         final JobGraph inputSplitJobGraph =
1084:                 JobGraphBuilder.newStreamingJobGraphBuilder()
1085:                         .addJobVertex(source)
1086:                         .setExecutionConfig(executionConfig)
1087:                         .build();
1088: 
1089:         try (final JobMaster jobMaster =
1090:                 new JobMasterBuilder(inputSplitJobGraph, rpcService)
1091:                         .withConfiguration(configuration)
1092:                         .withHighAvailabilityServices(haServices)
1093:                         .withHeartbeatServices(heartbeatServices)
1094:                         .createJobMaster()) {
1095: 
1096:             jobMaster.start();
1097: 
1098:             final JobMasterGateway jobMasterGateway =
1099:                     jobMaster.getSelfGateway(JobMasterGateway.class);
1100: 
1101:             registerSlotsRequiredForJobExecution(
1102:                     jobMasterGateway, inputSplitJobGraph.getJobID(), parallelism);
1103: 
1104:             waitUntilAllExecutionsAreScheduledOrDeployed(jobMasterGateway);
1105: 
1106:             final JobVertexID sourceId = source.getID();
1107: 
1108:             final List<AccessExecution> executions = getExecutions(jobMasterGateway, sourceId);
1109:             final ExecutionAttemptID initialAttemptId = executions.get(0).getAttemptId();
1110:             final List<List<InputSplit>> inputSplitsPerTask = new ArrayList<>(parallelism);
1111: 
1112:             // request all input splits
1113:             for (AccessExecution execution : executions) {
1114:                 inputSplitsPerTask.add(
1115:                         getInputSplits(
1116:                                 splitsPerTask,
1117:                                 getInputSplitSupplier(
1118:                                         sourceId, jobMasterGateway, execution.getAttemptId())));
1119:             }
1120: 
1121:             final List<InputSplit> allRequestedInputSplits = flattenCollection(inputSplitsPerTask);
1122:             assertThat(allRequestedInputSplits)
1123:                     .containsExactlyInAnyOrder(allInputSplits.toArray(EMPTY_TESTING_INPUT_SPLITS));
1124: 
1125:             // fail the first execution to trigger a failover
1126:             jobMasterGateway
1127:                     .updateTaskExecutionState(
1128:                             new TaskExecutionState(initialAttemptId, ExecutionState.FAILED))
1129:                     .get();
1130: 
1131:             // wait until the job has been recovered
1132:             waitUntilAllExecutionsAreScheduledOrDeployed(jobMasterGateway);
1133: 
1134:             final ExecutionAttemptID restartedAttemptId =
1135:                     getFirstExecution(jobMasterGateway, sourceId).getAttemptId();
1136: 
1137:             final List<InputSplit> inputSplits =
1138:                     getRemainingInputSplits(
1139:                             getInputSplitSupplier(sourceId, jobMasterGateway, restartedAttemptId));
1140: 
1141:             assertThat(inputSplits)
1142:                     .containsExactlyInAnyOrder(
1143:                             expectedRemainingInputSplits
1144:                                     .apply(inputSplitsPerTask)
1145:                                     .toArray(EMPTY_TESTING_INPUT_SPLITS));
1146:         }
1147:     }
