1220:     @Nonnull
1221:     private static List<InputSplit> getInputSplits(
1222:             int numberInputSplits, Supplier<SerializedInputSplit> nextInputSplit) throws Exception {
1223:         final List<InputSplit> actualInputSplits = new ArrayList<>(numberInputSplits);
1224: 
1225:         for (int i = 0; i < numberInputSplits; i++) {
1226:             final SerializedInputSplit serializedInputSplit = nextInputSplit.get();
1227: 
1228:             assertThat(serializedInputSplit.isEmpty()).isFalse();
1229: 
1230:             actualInputSplits.add(
1231:                     InstantiationUtil.deserializeObject(
1232:                             serializedInputSplit.getInputSplitData(),
1233:                             ClassLoader.getSystemClassLoader()));
1234:         }
1235: 
1236:         return actualInputSplits;
1237:     }
