1239:     private List<InputSplit> getRemainingInputSplits(Supplier<SerializedInputSplit> nextInputSplit)
1240:             throws Exception {
1241:         final List<InputSplit> actualInputSplits = new ArrayList<>(16);
1242:         boolean hasMoreInputSplits = true;
1243: 
1244:         while (hasMoreInputSplits) {
1245:             final SerializedInputSplit serializedInputSplit = nextInputSplit.get();
1246: 
1247:             if (serializedInputSplit.isEmpty()) {
1248:                 hasMoreInputSplits = false;
1249:             } else {
1250:                 final InputSplit inputSplit =
1251:                         InstantiationUtil.deserializeObject(
1252:                                 serializedInputSplit.getInputSplitData(),
1253:                                 ClassLoader.getSystemClassLoader());
1254: 
1255:                 if (inputSplit == null) {
1256:                     hasMoreInputSplits = false;
1257:                 } else {
1258:                     actualInputSplits.add(inputSplit);
1259:                 }
1260:             }
1261:         }
1262: 
1263:         return actualInputSplits;
1264:     }
