1348:             final CompletableFuture<TaskDeploymentDescriptor> tddFuture = new CompletableFuture<>();
1349:             final TestingTaskExecutorGateway testingTaskExecutorGateway =
1350:                     new TestingTaskExecutorGatewayBuilder()
1351:                             .setSubmitTaskConsumer(
1352:                                     (taskDeploymentDescriptor, jobMasterId) -> {
1353:                                         tddFuture.complete(taskDeploymentDescriptor);
1354:                                         return CompletableFuture.completedFuture(Acknowledge.get());
1355:                                     })
1356:                             .createTestingTaskExecutorGateway();
1357:             final LocalUnresolvedTaskManagerLocation taskManagerLocation =
1358:                     new LocalUnresolvedTaskManagerLocation();
1359: 
1360:             final JobMasterGateway jobMasterGateway =
1361:                     jobMaster.getSelfGateway(JobMasterGateway.class);
1362: 
1363:             final Collection<SlotOffer> slotOffers =
1364:                     registerSlotsAtJobMaster(
1365:                             1,
1366:                             jobMasterGateway,
1367:                             producerConsumerJobGraph.getJobID(),
1368:                             testingTaskExecutorGateway,
1369:                             taskManagerLocation);
1370: 
1371:             assertThat(slotOffers).hasSize(1);
1372: 
1373:             // obtain tdd for the result partition ids
1374:             final TaskDeploymentDescriptor tdd = tddFuture.get();
1375: 
1376:             assertThat(tdd.getProducedPartitions()).hasSize(1);
1377:             final ResultPartitionDeploymentDescriptor partition =
1378:                     tdd.getProducedPartitions().iterator().next();
1379: 
1380:             final ExecutionAttemptID executionAttemptId = tdd.getExecutionAttemptId();
1381:             final ExecutionAttemptID copiedExecutionAttemptId =
1382:                     InstantiationUtil.clone(executionAttemptId);
1383: 
1384:             // finish the producer task
1385:             jobMasterGateway
1386:                     .updateTaskExecutionState(
1387:                             SchedulerTestingUtils.createFinishedTaskExecutionState(
1388:                                     executionAttemptId))
1389:                     .get();
1390: 
1391:             // request the state of the result partition of the producer
1392:             final ResultPartitionID partitionId =
1393:                     new ResultPartitionID(partition.getPartitionId(), copiedExecutionAttemptId);
1394:             CompletableFuture<ExecutionState> partitionStateFuture =
1395:                     jobMasterGateway.requestPartitionState(partition.getResultId(), partitionId);
1396: 
1397:             assertThat(partitionStateFuture.get()).isEqualTo(ExecutionState.FINISHED);
1398: 
1399:             // ask for unknown result partition
1400:             partitionStateFuture =
1401:                     jobMasterGateway.requestPartitionState(
1402:                             partition.getResultId(), new ResultPartitionID());
1403: 
1404:             assertThatThrownBy(partitionStateFuture::get)
1405:                     .hasRootCauseInstanceOf(IllegalArgumentException.class);
1406: 
1407:             // ask for wrong intermediate data set id
1408:             partitionStateFuture =
1409:                     jobMasterGateway.requestPartitionState(
1410:                             new IntermediateDataSetID(), partitionId);
1411: 
1412:             assertThatThrownBy(partitionStateFuture::get)
1413:                     .hasRootCauseInstanceOf(IllegalArgumentException.class);
