704:     public void addAll(Configuration other, String prefix) {
705:         final StringBuilder bld = new StringBuilder();
706:         bld.append(prefix);
707:         final int pl = bld.length();
708: 
709:         synchronized (this.confData) {
710:             synchronized (other.confData) {
711:                 for (Map.Entry<String, Object> entry : other.confData.entrySet()) {
712:                     bld.setLength(pl);
713:                     bld.append(entry.getKey());
714:                     this.confData.put(bld.toString(), entry.getValue());
715:                 }
716:             }
717:         }
718:     }
