740:     /**
741:      * Checks whether there is an entry for the given config option.
742:      *
743:      * @param configOption The configuration option
744:      * @return <tt>true</tt> if a valid (current or deprecated) key of the config option is stored,
745:      *     <tt>false</tt> otherwise
746:      */
747:     @PublicEvolving
748:     public boolean contains(ConfigOption<?> configOption) {
749:         synchronized (this.confData) {
750:             final BiFunction<String, Boolean, Optional<Boolean>> applier =
751:                     (key, canBePrefixMap) -> {
752:                         if (canBePrefixMap && containsPrefixMap(this.confData, key)
753:                                 || this.confData.containsKey(key)) {
754:                             return Optional.of(true);
755:                         }
756:                         return Optional.empty();
757:                     };
758:             return applyWithOption(configOption, applier).orElse(false);
759:         }
760:     }
761: 
762:     private <T> Optional<T> applyWithOption(
763:             ConfigOption<?> option, BiFunction<String, Boolean, Optional<T>> applier) {
764:         final boolean canBePrefixMap = canBePrefixMap(option);
765:         final Optional<T> valueFromExactKey = applier.apply(option.key(), canBePrefixMap);
766:         if (valueFromExactKey.isPresent()) {
767:             return valueFromExactKey;
768:         } else if (option.hasFallbackKeys()) {
769:             // try the fallback keys
770:             for (FallbackKey fallbackKey : option.fallbackKeys()) {
771:                 final Optional<T> valueFromFallbackKey =
772:                         applier.apply(fallbackKey.getKey(), canBePrefixMap);
773:                 if (valueFromFallbackKey.isPresent()) {
774:                     loggingFallback(fallbackKey, option);
775:                     return valueFromFallbackKey;
776:                 }
777:             }
778:         }
779:         return Optional.empty();
780:     }
