826:             throw new IllegalArgumentException(
827:                     GlobalConfiguration.isSensitive(option.key())
828:                             ? String.format("Could not parse value for key '%s'.", option.key())
829:                             : String.format(
830:                                     "Could not parse value '%s' for key '%s'.",
831:                                     rawValue.map(Object::toString).orElse(""), option.key()),
832:                     e);
833:         }
