859:     /**
860:      * Convert Config into a {@code Map<String, String>} representation.
861:      *
862:      * <p>NOTE: This method is extracted from the {@link Configuration#toMap} method and should be
863:      * called when Config needs to be written to a file.
864:      *
865:      * <p>This method ensures the value is properly escaped when writing the key-value pair to a
866:      * standard YAML file.
867:      */
868:     @Internal
869:     public Map<String, String> toFileWritableMap() {
870:         if (standardYaml) {
871:             synchronized (this.confData) {
872:                 Map<String, String> ret =
873:                         CollectionUtil.newHashMapWithExpectedSize(this.confData.size());
874:                 for (Map.Entry<String, Object> entry : confData.entrySet()) {
875:                     // Because some character in standard yaml should be escaped by quotes, such as
876:                     // '*', here we should wrap the value by Yaml pattern
877:                     ret.put(entry.getKey(), YamlParserUtils.toYAMLString(entry.getValue()));
878:                 }
879:                 return ret;
880:             }
881:         } else {
882:             return toMap();
883:         }
