923:     <T> void setValueInternal(String key, T value, boolean canBePrefixMap) {
924:         if (key == null) {
925:             throw new NullPointerException("Key must not be null.");
926:         }
927:         if (value == null) {
928:             throw new NullPointerException("Value must not be null.");
929:         }
930: 
931:         synchronized (this.confData) {
932:             if (canBePrefixMap) {
933:                 removePrefixMap(this.confData, key);
934:             }
935:             this.confData.put(key, value);
936:         }
937:     }
