947:     private Optional<Object> getRawValue(String key, boolean canBePrefixMap) {
948:         if (key == null) {
949:             throw new NullPointerException("Key must not be null.");
950:         }
951: 
952:         synchronized (this.confData) {
953:             final Object valueFromExactKey = this.confData.get(key);
954:             if (!canBePrefixMap || valueFromExactKey != null) {
955:                 return Optional.ofNullable(valueFromExactKey);
956:             }
957:             final Map<String, String> valueFromPrefixMap =
958:                     convertToPropertiesPrefixed(confData, key, standardYaml);
959:             if (valueFromPrefixMap.isEmpty()) {
960:                 return Optional.empty();
961:             }
962:             return Optional.of(valueFromPrefixMap);
963:         }
964:     }
