470:      * @param key Key to be removed from ConfigMap
471:      * @return True if the state handle isn't listed anymore.
472:      * @throws Exception if removing the key or discarding the state failed
473:      */
474:     @Override
475:     public boolean releaseAndTryRemove(String key) throws Exception {
476:         checkNotNull(key, "Key in ConfigMap.");
477:         final AtomicReference<RetrievableStateHandle<T>> stateHandleRefer = new AtomicReference<>();
478:         final AtomicBoolean stateHandleDoesNotExist = new AtomicBoolean(false);
479:         return updateConfigMap(
480:                         configMap -> {
481:                             final String content = configMap.getData().get(key);
482:                             if (content != null) {
483:                                 try {
484:                                     final StateHandleWithDeleteMarker<T> result =
485:                                             deserializeStateHandle(content);
486:                                     if (!result.isMarkedForDeletion()) {
487:                                         // Mark the ConfigMap entry as deleting. This basically
488:                                         // starts a "removal transaction" that allows us to retry
489:                                         // the removal if needed.
490:                                         configMap
491:                                                 .getData()
492:                                                 .put(
493:                                                         key,
494:                                                         serializeStateHandle(result.toDeleting()));
495:                                     }
496:                                     stateHandleRefer.set(result.getInner());
497:                                 } catch (IOException e) {
498:                                     logInvalidEntry(key, configMapName, e);
499:                                     // Remove entry from the config map as we can't recover from
500:                                     // this (the serialization would fail on the retry as well).
501:                                     Objects.requireNonNull(configMap.getData().remove(key));
502:                                 }
503:                                 return Optional.of(configMap);
504:                             } else {
505:                                 stateHandleDoesNotExist.set(true);
506:                             }
507:                             return Optional.empty();
508:                         })
509:                 .thenCompose(
510:                         updated -> {
511:                             if (updated && stateHandleRefer.get() != null) {
512:                                 try {
513:                                     stateHandleRefer.get().discardState();
514:                                     return updateConfigMap(
515:                                             configMap -> {
516:                                                 // Now we can safely commit the "removal
517:                                                 // transaction" by removing the entry from the
518:                                                 // ConfigMap.
519:                                                 configMap.getData().remove(key);
520:                                                 return Optional.of(configMap);
521:                                             });
522:                                 } catch (Exception e) {
523:                                     throw new CompletionException(e);
524:                                 }
525:                             }
526:                             return CompletableFuture.completedFuture(
527:                                     stateHandleDoesNotExist.get() || updated);
528:                         })
529:                 .get();
530:     }
