579:     /**
580:      * Adds entry into the ConfigMap. If the entry already exists and contains delete marker, we try
581:      * to finish the removal before the actual update.
582:      */
583:     private Optional<KubernetesConfigMap> addEntry(
584:             KubernetesConfigMap configMap, String key, byte[] serializedStateHandle)
585:             throws Exception {
586:         final String oldBase64Content = configMap.getData().get(key);
587:         final String newBase64Content = toBase64(serializedStateHandle);
588:         if (oldBase64Content != null) {
589:             try {
590:                 final StateHandleWithDeleteMarker<T> stateHandle =
591:                         deserializeStateHandle(oldBase64Content);
592:                 if (stateHandle.isMarkedForDeletion()) {
593:                     // This might be a left-over after the fail-over. As the remove operation is
594:                     // idempotent let's try to finish it.
595:                     if (!releaseAndTryRemove(key)) {
596:                         throw new IllegalStateException(
597:                                 "Unable to remove the marked as deleting entry.");
598:                     }
599:                 } else {
600:                     // It could happen that the kubernetes client retries a transaction that has
601:                     // already succeeded due to network issues. So we simply ignore when the
602:                     // new content is same as the existing one.
603:                     if (oldBase64Content.equals(newBase64Content)) {
604:                         return Optional.of(configMap);
605:                     }
606:                     throw getKeyAlreadyExistException(key);
607:                 }
608:             } catch (IOException e) {
609:                 // Just log the invalid entry, it will be overridden
610:                 // by the update code path below.
611:                 logInvalidEntry(key, configMapName, e);
612:             }
613:         }
614:         configMap.getData().put(key, newBase64Content);
615:         return Optional.of(configMap);
616:     }
617: 
618:     /**
619:      * Replace the entry in the ConfigMap. If the entry already exists and contains delete marker,
620:      * we treat it as non-existent and perform the best effort removal.
621:      */
622:     private Optional<KubernetesConfigMap> replaceEntry(
623:             KubernetesConfigMap configMap,
624:             String key,
625:             byte[] serializedStateHandle,
626:             AtomicReference<RetrievableStateHandle<T>> oldStateHandleRef)
627:             throws NotExistException {
628:         final String content = configMap.getData().get(key);
629:         if (content != null) {
630:             try {
631:                 final StateHandleWithDeleteMarker<T> stateHandle = deserializeStateHandle(content);
632:                 oldStateHandleRef.set(stateHandle.getInner());
633:                 if (stateHandle.isMarkedForDeletion()) {
634:                     final NotExistException exception = getKeyNotExistException(key);
635:                     try {
636:                         // Try to finish the removal. We don't really care whether this succeeds or
637:                         // not, from the "replace" point of view, the entry doesn't exist.
638:                         releaseAndTryRemove(key);
639:                     } catch (Exception e) {
640:                         exception.addSuppressed(e);
641:                     }
642:                     throw exception;
643:                 }
644:             } catch (IOException e) {
645:                 // Just log the invalid entry, it will be removed by the update code path below.
646:                 logInvalidEntry(key, configMapName, e);
647:             }
648:             configMap.getData().put(key, toBase64(serializedStateHandle));
649:             return Optional.of(configMap);
650:         }
651:         throw getKeyNotExistException(key);
652:     }
653: 
654:     private KubernetesException getConfigMapNotExistException() {
655:         return new KubernetesException(
656:                 "ConfigMap "
657:                         + configMapName
658:                         + " does not exists. "
659:                         + "It may be deleted externally.");
660:     }
661: 
662:     private NotExistException getKeyNotExistException(String key) {
663:         return new NotExistException("Could not find " + key + " in ConfigMap " + configMapName);
664:     }
665: 
666:     private NotExistException getKeyMarkedAsDeletedException(String key) {
667:         return new NotExistException(
668:                 "Already marked for deletion " + key + " in ConfigMap " + configMapName);
669:     }
670: 
671:     private AlreadyExistException getKeyAlreadyExistException(String key) {
672:         return new AlreadyExistException(key + " already exists in ConfigMap " + configMapName);
673:     }
674: 
675:     private static void logInvalidEntry(String key, String configMapName, Throwable e) {
676:         LOG.warn(
677:                 "Could not retrieve the state handle of '{}' from ConfigMap '{}'. Removing the entry as we don't have any way to recover.",
678:                 key,
679:                 configMapName,
680:                 e);
681:     }
