19: package org.apache.flink.client.cli;
20: 
21: import org.apache.flink.annotation.Internal;
22: import org.apache.flink.configuration.ConfigUtils;
23: import org.apache.flink.configuration.Configuration;
24: import org.apache.flink.configuration.CoreOptions;
25: import org.apache.flink.configuration.DeploymentOptions;
26: import org.apache.flink.configuration.PipelineOptions;
27: import org.apache.flink.runtime.jobgraph.SavepointRestoreSettings;
28: 
29: import java.net.MalformedURLException;
30: import java.net.URL;
31: import java.util.List;
32: 
33: import static org.apache.flink.util.Preconditions.checkNotNull;
34: 
35: /**
36:  * Accessor that exposes config settings that are relevant for execution from an underlying {@link
37:  * Configuration}.
38:  */
39: @Internal
40: public class ExecutionConfigAccessor {
41: 
42:     private final Configuration configuration;
43: 
44:     private ExecutionConfigAccessor(final Configuration configuration) {
45:         this.configuration = checkNotNull(configuration);
46:     }
47: 
48:     /** Creates an {@link ExecutionConfigAccessor} based on the provided {@link Configuration}. */
49:     public static ExecutionConfigAccessor fromConfiguration(final Configuration configuration) {
50:         return new ExecutionConfigAccessor(checkNotNull(configuration));
51:     }
52: 
53:     /**
54:      * Creates an {@link ExecutionConfigAccessor} based on the provided {@link ProgramOptions} as
55:      * provided by the user through the CLI.
56:      */
57:     public static <T> ExecutionConfigAccessor fromProgramOptions(
58:             final ProgramOptions options, final List<T> jobJars) {
59:         checkNotNull(options);
60:         checkNotNull(jobJars);
61: 
62:         final Configuration configuration = new Configuration();
63: 
64:         options.applyToConfiguration(configuration);
65:         ConfigUtils.encodeCollectionToConfig(
66:                 configuration, PipelineOptions.JARS, jobJars, Object::toString);
67: 
68:         return new ExecutionConfigAccessor(configuration);
69:     }
70: 
71:     public Configuration applyToConfiguration(final Configuration baseConfiguration) {
72:         baseConfiguration.addAll(configuration);
73:         return baseConfiguration;
74:     }
75: 
76:     public List<URL> getJars() throws MalformedURLException {
77:         return ConfigUtils.decodeListFromConfig(configuration, PipelineOptions.JARS, URL::new);
78:     }
79: 
80:     public List<URL> getClasspaths() throws MalformedURLException {
81:         return ConfigUtils.decodeListFromConfig(
82:                 configuration, PipelineOptions.CLASSPATHS, URL::new);
83:     }
84: 
85:     public int getParallelism() {
86:         return configuration.get(CoreOptions.DEFAULT_PARALLELISM);
87:     }
88: 
89:     public boolean getDetachedMode() {
90:         return !configuration.get(DeploymentOptions.ATTACHED);
91:     }
92: 
93:     public SavepointRestoreSettings getSavepointRestoreSettings() {
94:         return SavepointRestoreSettings.fromConfiguration(configuration);
95:     }
96: 
97:     public boolean isShutdownOnAttachedExit() {
98:         return configuration.get(DeploymentOptions.SHUTDOWN_IF_ATTACHED);
99:     }
100: }
